INSERT INTO "posts" ("slug", "kind", "category", "title", "excerpt", "body", "cover_file", "read_minutes", "author_name", "diseases", "tags",
  "seo_description", "status", "published_at", "updated_by")
SELECT v.slug, 'article', v.category, v.title, v.excerpt, v.body, v.cover, v.minutes, 'Cây Cảnh Miền Tây', v.diseases, v.tags, v.seo,
  'published', now() - (v.ord * interval '10 minutes'), 'Hệ thống'
FROM (VALUES
('thay-chau-cay-canh-dung-cach', 'cham-soc', 'Thay chậu cho cây cảnh: khi nào cần thay và làm từng bước để cây không sốc', 'Cây đứng lá, rễ trồi khỏi lỗ thoát nước, đất tưới vào là chảy tuột xuống đĩa — đó là lúc cây cần chậu mới. Bài này hướng dẫn chọn cỡ chậu, chuẩn bị đất và thay chậu từng bước, kèm cách chăm 2 tuần sau đó.', '[{"type": "p", "text": "Cây cảnh trồng chậu lâu ngày sẽ đến lúc rễ chật kín chậu. Lúc đó cây không còn chỗ để rễ mới mọc ra, đất cũ đã chai và nghèo dinh dưỡng, tưới bao nhiêu cũng nhanh khô. Thay chậu đúng lúc giúp cây ra lá mới khỏe hơn hẳn; thay sai cách thì cây dễ sốc, rũ lá cả tuần."}, {"type": "h2", "text": "Dấu hiệu cây cần thay chậu"}, {"type": "list", "items": ["Rễ trồi ra khỏi lỗ thoát nước dưới đáy chậu, hoặc nổi lên mặt đất.", "Tưới nước vào chảy tuột xuống đĩa rất nhanh, đất không giữ được ẩm như trước.", "Cây đứng lá cả mùa sinh trưởng dù vẫn bón phân, lá mới ra nhỏ dần.", "Cây cao, tán to so với chậu, gió nhẹ là ngã.", "Đất trên mặt đóng váng trắng, chai cứng, có mùi chua."], "ordered": false}, {"type": "p", "text": "Thông thường cây kiểng lá trong nhà thay chậu 1–2 năm một lần. Cây mọc nhanh như [trầu bà đế vương](/san-pham/trau-ba-de-vuong-xanh), [lan ý](/san-pham/lan-y) có thể cần thay sớm hơn; cây mọc chậm như [lưỡi hổ](/san-pham/luoi-ho) thì 2–3 năm mới cần."}, {"type": "h2", "text": "Chọn chậu mới lớn hơn bao nhiêu?"}, {"type": "p", "text": "Nguyên tắc dễ nhớ: **chậu mới rộng hơn chậu cũ khoảng 3–5cm đường kính** với cây nhỏ, 5–8cm với cây lớn. Chậu quá rộng so với bộ rễ là lỗi hay gặp: phần đất dư không có rễ hút nước nên ướt lâu, rễ dễ thối. Nếu bạn quen dùng mã chậu của nhà vườn, mỗi lần chỉ nên tăng lên một cỡ (ví dụ từ C7 lên C8). Xem thêm [cách đọc mã chậu C6, C7, C9, C10](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."}, {"type": "p", "text": "Chậu bắt buộc có lỗ thoát nước. Chậu sứ, chậu gốm đẹp mà không có lỗ thì nên dùng làm chậu bọc ngoài, bên trong vẫn là chậu nhựa có lỗ."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Trowel.jpg/960px-Trowel.jpg", "caption": "Chuẩn bị sẵn đất trộn và xẻng nhỏ trước khi lấy cây ra khỏi chậu cũ để rễ không phải phơi lâu ngoài không khí."}, {"type": "h2", "text": "Thời điểm thay chậu"}, {"type": "p", "text": "Thời điểm tốt nhất là khi cây đang mọc mạnh, trời mát. Ở miền Tây, đầu mùa mưa (tháng 5–6) và những ngày mát cuối năm đều thuận. Tránh thay chậu khi cây đang ra hoa, đang bệnh nặng, hoặc giữa trưa nắng gắt. Cây vừa mua về nên để quen chỗ 1–2 tuần rồi hãy thay."}, {"type": "h2", "text": "Thay chậu từng bước"}, {"type": "list", "items": ["Tưới ẩm cây trước 1 ngày để bầu rễ mềm, dễ lấy ra và rễ ít đứt.", "Lót đáy chậu mới một lớp sỏi nhẹ hoặc xơ dừa mỏng để đất không lọt qua lỗ.", "Cho một lớp đất trộn sẵn vào đáy, sao cho khi đặt bầu cây vào thì mặt bầu thấp hơn miệng chậu khoảng 2–3cm.", "Nghiêng chậu cũ, bóp nhẹ thành chậu, đỡ gốc cây và kéo bầu ra. Đừng nắm thân giật mạnh.", "Gỡ nhẹ lớp rễ cuộn quanh bầu. Cắt bỏ rễ đen, mềm, có mùi hôi bằng kéo sạch.", "Đặt cây vào giữa chậu, lấp đất quanh bầu, ấn nhẹ cho chặt, không nén quá cứng.", "Tưới đẫm một lần cho đất lún xuống, châm thêm đất nếu bị hụt."], "ordered": true}, {"type": "p", "text": "Đất cho cây kiểng lá trong nhà nên tơi, thoát nước nhanh. Nếu muốn tự trộn, xem [công thức trộn đất trồng cây kiểng lá](/goc-cham-cay/tron-dat-trong-cay-kieng-la)."}, {"type": "h2", "text": "Chăm sóc 2 tuần sau khi thay chậu"}, {"type": "list", "items": ["Đặt cây ở chỗ sáng nhẹ, tránh nắng trực tiếp trong 7–10 ngày đầu.", "Không bón phân trong 3–4 tuần: rễ vừa bị động cần thời gian lành, bón sớm dễ cháy rễ.", "Tưới khi mặt đất khô 2–3cm, không tưới theo lịch cố định.", "Cây rũ nhẹ 2–3 ngày đầu là bình thường. Nếu sau 1 tuần lá vẫn vàng, gốc mềm thì kiểm tra lại rễ, xem bài [thối rễ](/benh-cay/thoi-re)."], "ordered": false}, {"type": "note", "title": "Mẹo nhỏ", "text": "Cây đang khỏe mà chỉ muốn đổi chậu cho đẹp thì giữ nguyên bầu đất, đặt cả bầu vào chậu mới cùng cỡ hoặc dùng chậu bọc ngoài. Cây ít bị động rễ hơn nhiều."}, {"type": "products", "title": "Cây dễ thay chậu cho người mới", "slugs": ["luoi-ho", "lan-y", "trau-ba-de-vuong-xanh", "ngoc-ngan"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/OAI0YI23DR.jpg', 4, '["thoi-re"]'::jsonb, '["thay chậu", "đất trồng", "chậu cây", "kiểng lá"]'::jsonb, 'Khi nào cần thay chậu cây cảnh, chọn chậu lớn hơn bao nhiêu, cách thay chậu từng bước và chăm cây sau khi thay để cây không bị sốc, vàng lá.', 0),
('tron-dat-trong-cay-kieng-la', 'cham-soc', 'Tự trộn đất trồng cây kiểng lá trong nhà: tơi, thoát nước, không úng rễ', 'Đất vườn đem vào chậu trong nhà thường bí và giữ nước quá lâu — nguyên nhân hàng đầu khiến kiểng lá thối rễ. Đây là cách tự trộn đất bằng vật liệu dễ mua ở miền Tây: xơ dừa, tro trấu, đá perlite, phân trùn quế.', '[{"type": "p", "text": "Cây kiểng lá trong nhà như trầu bà, vạn lộc, môn, lan ý có bộ rễ cần cả nước lẫn không khí. Đất quá chặt thì rễ thiếu khí, nước đọng lâu và rễ thối dần mà ta không thấy. Vì vậy đất trồng chậu trong nhà không giống đất trồng ngoài vườn."}, {"type": "h2", "text": "Vì sao không nên dùng đất vườn nguyên chất?"}, {"type": "p", "text": "Đất vườn, đất phù sa miền Tây rất màu mỡ khi trồng dưới đất. Nhưng cho vào chậu, nhất là chậu đặt trong nhà ít nắng gió, đất này nén chặt sau vài lần tưới, khô thì nứt cứng, ướt thì bết dính. Ngoài ra đất vườn có thể mang theo trứng sâu, mầm nấm, hạt cỏ."}, {"type": "h2", "text": "Các vật liệu thường dùng"}, {"type": "table", "rows": [["Vật liệu", "Tác dụng", "Lưu ý"], ["Xơ dừa (mụn dừa)", "Giữ ẩm, làm đất tơi", "Phải xả chát (ngâm, xả nước nhiều lần) trước khi dùng"], ["Tro trấu", "Tơi, thoát nước, nhẹ chậu", "Dùng tro đã nguội, đã xả bớt kiềm"], ["Đá perlite / đá bọt", "Tạo lỗ thoát khí, không mục", "Đeo khẩu trang khi trộn vì bụi mịn"], ["Phân trùn quế", "Bổ sung dinh dưỡng nhẹ, an toàn cho rễ", "Chỉ chiếm phần nhỏ trong hỗn hợp"], ["Vỏ thông, than củi vụn", "Thoáng khí cho cây họ Ráy", "Hợp với môn, trầu bà rễ to"]]}, {"type": "h2", "text": "Ba công thức đơn giản"}, {"type": "h3", "text": "1. Kiểng lá thông thường (trầu bà, vạn lộc, ngọc ngân, phú quý)"}, {"type": "p", "text": "Trộn theo tỉ lệ thể tích: 4 phần xơ dừa + 3 phần tro trấu + 2 phần perlite + 1 phần phân trùn quế. Hỗn hợp này giữ ẩm vừa phải, tưới xong nước thấm và thoát ra đáy chậu trong vài giây."}, {"type": "h3", "text": "2. Cây môn, cây có củ (môn quan âm, môn melo)"}, {"type": "p", "text": "Củ môn rất sợ úng, nên tăng phần thoát nước: 3 phần xơ dừa + 3 phần perlite hoặc đá bọt + 2 phần vỏ thông + 1 phần tro trấu + 1 phần phân trùn quế. Xem thêm [cách chăm môn quan âm và môn melo](/goc-cham-cay/mon-quan-am-va-mon-melo)."}, {"type": "h3", "text": "3. Cây mọng nước, lưỡi hổ, ngọc bích"}, {"type": "p", "text": "Cần khô nhanh: 4 phần đất thịt nhẹ hoặc xơ dừa + 4 phần cát thô hoặc đá bọt + 2 phần tro trấu. Không cần nhiều phân."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/HandsInSoil.jpg/960px-HandsInSoil.jpg", "caption": "Trộn đều các thành phần khi còn hơi ẩm để bụi không bay và hỗn hợp tơi đều."}, {"type": "h2", "text": "Cách kiểm tra đất trộn đạt chưa"}, {"type": "list", "items": ["Nắm một nắm đất ẩm rồi mở tay: đất giữ hình nhưng chạm nhẹ là vỡ ra là đạt. Bết thành cục là quá nhiều đất hoặc xơ dừa mịn.", "Tưới thử một chậu: nước phải thoát ra đáy trong vòng vài giây, không đọng trên mặt.", "Sau 2–3 ngày trong nhà, mặt đất khô dần nhưng lớp dưới vẫn hơi ẩm."], "ordered": false}, {"type": "h2", "text": "Những lỗi hay gặp"}, {"type": "list", "items": ["Dùng xơ dừa chưa xả chát: cây vàng lá, rễ non bị cháy.", "Cho quá nhiều phân hữu cơ vào đất ngay từ đầu: đất nóng, bốc mùi, rễ thối.", "Trộn đất quá mịn, như bột: tưới vài lần là nén chặt như đất sét.", "Dùng lại đất cũ của cây bệnh mà không xử lý: mầm nấm vẫn còn, cây mới cũng bệnh theo."], "ordered": true}, {"type": "note", "title": "Đất cũ có dùng lại được không?", "text": "Đất của cây khỏe có thể phơi nắng vài ngày, trộn thêm xơ dừa, tro trấu và phân trùn quế mới rồi dùng cho cây khác. Đất của cây thối rễ, nấm bệnh thì nên bỏ."}, {"type": "p", "text": "Đất tốt chỉ là một nửa — tưới đúng mới giữ được rễ khỏe. Đọc thêm [tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach)."}, {"type": "products", "title": "Kiểng lá trồng hợp với đất trộn tơi", "slugs": ["phu-quy", "van-loc", "trau-ba-de-vuong-do", "mon-quan-am", "mon-melo"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Pro-Mix_Potting_Soil.jpg/960px-Pro-Mix_Potting_Soil.jpg', 3, '["thoi-re"]'::jsonb, '["đất trồng", "giá thể", "xơ dừa", "tro trấu", "kiểng lá"]'::jsonb, 'Công thức tự trộn đất trồng cây kiểng lá trong nhà bằng xơ dừa, tro trấu, perlite, phân trùn quế: tơi xốp, thoát nước tốt, hạn chế thối rễ.', 7),
('anh-sang-cho-cay-trong-nha', 'cham-soc', 'Ánh sáng cho cây trong nhà: phân biệt nắng trực tiếp, sáng tán xạ và bóng râm', '"Ưa sáng tán xạ", "chịu bóng", "cần nắng nhẹ" — nhãn cây nào cũng ghi vậy, nhưng ở nhà thực tế là chỗ nào? Bài này giúp bạn nhận ra từng mức ánh sáng ngay trong căn nhà mình và đặt cây cho đúng.', '[{"type": "p", "text": "Nước tưới có thể chỉnh mỗi ngày, nhưng ánh sáng thì cây phải chịu suốt ngày đêm ở chỗ ta đặt. Rất nhiều cây \"khó chăm\" thật ra chỉ bị đặt sai chỗ: quá tối thì cây vươn dài, lá nhỏ, mất màu; quá nắng thì lá cháy thành mảng trắng, nâu."}, {"type": "h2", "text": "Bốn mức ánh sáng thường gặp"}, {"type": "table", "rows": [["Mức ánh sáng", "Ở nhà là chỗ nào", "Cây hợp"], ["Nắng trực tiếp", "Ban công, sân thượng, cửa sổ hướng Tây không rèm", "Hoa hồng, tùng thơm, tắc cẩm thạch"], ["Sáng tán xạ mạnh", "Cách cửa sổ 0,5–1,5m, có rèm mỏng hoặc nắng không chiếu thẳng lên lá", "Môn quan âm, đuôi công, trầu bà đế vương"], ["Sáng tán xạ vừa / bóng râm sáng", "Giữa phòng khách có cửa sổ, góc sáng văn phòng", "Vạn lộc, ngọc ngân, lan ý, phú quý"], ["Thiếu sáng", "Hành lang, phòng không cửa sổ, chỉ có đèn", "Lưỡi hổ, bạch mã, trầu bà xanh (thay phiên đem ra chỗ sáng)"]]}, {"type": "h2", "text": "Cách \"đo\" ánh sáng không cần máy"}, {"type": "p", "text": "**Thử bằng bóng tay:** buổi trưa, giơ tay cách mặt chỗ đặt cây khoảng 30cm. Bóng tay sắc nét là nắng trực tiếp; bóng mờ có viền rõ là sáng tán xạ mạnh; bóng rất mờ, khó thấy là thiếu sáng."}, {"type": "p", "text": "**Đọc sách không cần đèn:** nếu ban ngày bạn đọc sách thoải mái ở chỗ đó mà không bật đèn, phần lớn kiểng lá chịu bóng sống được. Phải bật đèn mới đọc được thì chỗ đó chỉ hợp vài cây rất chịu tối."}, {"type": "p", "text": "Bạn có thể tham khảo thêm danh sách [cây sống khỏe ở góc thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang)."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/36UBBAQB99.jpg", "caption": "Cây đặt gần cửa sổ có rèm mỏng nhận ánh sáng tán xạ — mức hợp với phần lớn cây kiểng lá."}, {"type": "h2", "text": "Cây báo thiếu sáng hay thừa nắng thế nào?"}, {"type": "h3", "text": "Thiếu sáng"}, {"type": "list", "items": ["Thân vươn dài, khoảng cách giữa các lá thưa ra, cây nghiêng hẳn về phía cửa sổ.", "Lá mới nhỏ hơn lá cũ, lá đốm, lá màu nhạt dần về xanh trơn.", "Đất lâu khô, dễ úng rễ vì cây hút nước chậm."], "ordered": false}, {"type": "h3", "text": "Thừa nắng"}, {"type": "list", "items": ["Lá có mảng bạc, trắng hoặc nâu khô ở phần hứng nắng nhiều nhất.", "Mép lá cuộn lại, lá đuôi công cuộn tròn ban ngày.", "Màu lá đỏ, tím nhạt đi, bạc màu. Xem thêm [cháy lá do nắng gắt](/benh-cay/chay-la-do-nang)."], "ordered": false}, {"type": "h2", "text": "Một vài mẹo đặt cây"}, {"type": "list", "items": ["Xoay chậu một phần tư vòng mỗi tuần để cây mọc đều, không nghiêng.", "Cửa kính hướng Tây buổi chiều rất gắt, kể cả với cây \"ưa sáng\". Nên có rèm mỏng hoặc kéo cây lùi vào 1m.", "Đổi chỗ từ tối ra nắng phải làm dần trong 1–2 tuần. Đem thẳng cây trong nhà ra nắng gắt là cháy lá chỉ sau một buổi.", "Đèn văn phòng giúp cây sống được, nhưng cây phát triển rất chậm. Nếu có thể, cho cây ra chỗ sáng vài ngày mỗi tháng.", "Lá bám bụi dày làm cây nhận ít sáng hơn. Thỉnh thoảng [lau lá](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la) bằng khăn ẩm."], "ordered": true}, {"type": "products", "title": "Cây theo từng mức ánh sáng", "slugs": ["luoi-ho", "bach-ma-hoang-tu", "van-loc", "mon-quan-am", "hoa-hong", "tung-thom"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/HYEGYZNLA6.jpg', 3, '["chay-la-do-nang"]'::jsonb, '["ánh sáng", "cây trong nhà", "vị trí đặt cây"]'::jsonb, 'Ánh sáng tán xạ là gì, bóng râm là gì? Cách nhận biết mức ánh sáng trong nhà và đặt cây cảnh đúng chỗ để cây không vươn dài, nhạt màu hay cháy lá.', 14),
('cham-cay-khi-di-vang', 'cham-soc', 'Đi vắng 1–2 tuần: cách giữ cây trong nhà không chết khát', 'Về quê ăn Tết, đi công tác dài ngày là nỗi lo của người trồng cây. Chỉ cần chuẩn bị trước 1–2 ngày với vài mẹo đơn giản — gom cây, tưới bấc, che nắng — phần lớn cây trong nhà sẽ chờ bạn về mà vẫn xanh.', '[{"type": "p", "text": "Cây trong nhà thường chết khi chủ đi vắng vì hai lý do trái ngược: không ai tưới nên khô kiệt, hoặc chủ tưới thật đẫm trước khi đi rồi đóng kín cửa khiến rễ úng. Cách làm đúng là giữ ẩm vừa đủ và làm cây \"uống chậm lại\"."}, {"type": "h2", "text": "Trước khi đi 1–2 ngày"}, {"type": "list", "items": ["**Tưới đẫm rồi để ráo:** tưới kỹ cho nước thoát ra đáy chậu, đổ hết nước trong đĩa. Đừng để cây ngâm trong đĩa nước suốt chuyến đi.", "**Gom cây lại một chỗ:** đặt các chậu gần nhau, cách cửa sổ 1–2m. Cây đứng gần nhau giữ ẩm cho nhau, ít mất nước hơn đứng lẻ.", "**Kéo cây khỏi nắng gắt:** cây ở ban công nắng nên dời vào chỗ râm hơn. Ít nắng thì cây hút ít nước.", "**Cắt bớt hoa, nụ, lá già:** cây ra hoa tốn rất nhiều nước.", "**Không bón phân, không thay chậu** ngay trước khi đi."], "ordered": true}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/NTKJQC0VBJ.jpg", "caption": "Các chậu đặt sát nhau giữ ẩm cho nhau, mất nước chậm hơn khi đứng riêng lẻ."}, {"type": "h2", "text": "Ba cách tự tưới đơn giản"}, {"type": "h3", "text": "1. Tưới bằng bấc vải"}, {"type": "p", "text": "Dùng một xô hoặc chai nước đặt cao hơn mặt chậu. Cắt dải vải cotton hoặc dây dù to, một đầu ngâm trong nước, đầu kia cắm sâu 3–5cm vào đất. Nước thấm dần theo bấc vào chậu. Nên thử trước 1–2 ngày xem đất có ướt quá không."}, {"type": "h3", "text": "2. Chai nhựa nhỏ giọt"}, {"type": "p", "text": "Đục 1–2 lỗ nhỏ trên nắp chai nhựa, đổ đầy nước, cắm ngược chai vào đất. Lỗ càng nhỏ nước chảy càng chậm. Cách này hợp với chậu từ 20cm trở lên."}, {"type": "h3", "text": "3. Bồn tắm hoặc chậu lớn lót khăn"}, {"type": "p", "text": "Lót khăn ẩm dày dưới đáy bồn, đặt các chậu nhỏ lên. Khăn giữ ẩm dưới đáy chậu. Chỉ dùng cho chuyến đi ngắn, vì đáy chậu ẩm liên tục quá lâu dễ úng rễ."}, {"type": "h2", "text": "Cây nào chịu được đi vắng dài?"}, {"type": "list", "items": ["**Rất chịu khô (10–14 ngày):** [lưỡi hổ](/san-pham/luoi-ho), [ngọc bích](/san-pham/ngoc-bich), cây mọng nước. Chỉ cần tưới trước khi đi.", "**Chịu được 7–10 ngày:** [phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc), [bạch mã](/san-pham/bach-ma-hoang-tu), trầu bà đế vương — nhóm này lá dày, chịu khô vừa.", "**Cần ẩm thường xuyên:** [dương xỉ](/san-pham/duong-xi), [đuôi công](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea), [lan ý](/san-pham/lan-y), hoa đang nở. Nhóm này nên dùng bấc vải hoặc nhờ người tưới."], "ordered": false}, {"type": "h2", "text": "Về nhà nên làm gì?"}, {"type": "p", "text": "Đừng vội tưới ngập nếu cây chỉ hơi rũ. Kiểm tra đất bằng ngón tay: khô 3–4cm thì tưới đẫm một lần, để cây hồi lại trong ngày. Lá héo nặng, giòn thì cắt bỏ, cây sẽ ra lá mới. Xem thêm [dấu hiệu héo do thiếu nước](/benh-cay/heo-thieu-nuoc)."}, {"type": "note", "title": "Đi vắng dài hơn 2 tuần", "text": "Nên nhờ hàng xóm tưới mỗi tuần một lần, chụp ảnh đánh dấu chậu nào tưới nhiều, chậu nào tưới ít để người tưới khỏi nhầm."}, {"type": "products", "title": "Cây chịu khô cho người hay đi vắng", "slugs": ["luoi-ho", "ngoc-bich", "phu-quy", "van-loc", "bach-ma-hoang-tu"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/RegaderaMetalica.jpg/960px-RegaderaMetalica.jpg', 3, '["heo-thieu-nuoc"]'::jsonb, '["tưới cây", "đi vắng", "cây trong nhà", "mẹo chăm cây"]'::jsonb, 'Mẹo giữ cây cảnh trong nhà không chết khi đi vắng 1–2 tuần: gom cây, tưới bằng bấc vải, chai nhỏ giọt, che nắng và những việc không nên làm.', 21),
('lau-la-cat-tia-cay-kieng-la', 'cham-soc', 'Lau lá, cắt tỉa lá già: việc nhỏ 10 phút giúp cây kiểng lá đẹp lâu', 'Lá bám bụi làm cây xỉn màu và nhận ít ánh sáng; lá già vàng để lâu thành chỗ trú của sâu bệnh. Mỗi tuần dành 10 phút lau lá, cắt tỉa đúng cách, cây kiểng lá sẽ bóng đẹp như mới mua.', '[{"type": "p", "text": "Ở thành phố, chỉ sau 2–3 tuần là lá cây trong nhà đã phủ một lớp bụi mỏng. Lớp bụi này cản ánh sáng, làm lá trông xỉn và còn là chỗ nhện đỏ, rệp sáp ẩn nấp. Lau lá định kỳ là cách vừa làm đẹp vừa phát hiện sâu bệnh sớm."}, {"type": "h2", "text": "Lau lá thế nào cho đúng?"}, {"type": "list", "items": ["Dùng khăn mềm hoặc miếng bông nhúng nước sạch, vắt ráo.", "Một tay đỡ dưới lá, tay kia lau nhẹ từ cuống ra ngọn lá. Không kéo căng hoặc bẻ lá.", "Lau cả **mặt dưới lá** — đây là chỗ nhện đỏ, rệp hay bám nhất.", "Lá to, cây lớn có thể đem ra tắm vòi sen nhẹ bằng nước mát, che mặt đất để đất không bị xói, rồi để ráo nơi thoáng.", "Lau vào buổi sáng để lá khô trước tối."], "ordered": true}, {"type": "p", "text": "Cây lá có lông tơ hoặc lá mỏng như đuôi công, dương xỉ thì không lau mà chỉ phun sương hoặc xả nước nhẹ."}, {"type": "h2", "text": "Có nên dùng chất làm bóng lá?"}, {"type": "p", "text": "Không cần thiết. Các loại xịt bóng lá, dầu, sữa, bia có thể bít lỗ khí trên mặt lá, giữ bụi lại lâu hơn. Lá cây khỏe tự có độ bóng tự nhiên sau khi lau sạch bằng nước. Nếu nước nhà bạn nhiều đá vôi để lại vệt trắng, có thể dùng nước mưa hoặc nước đã để lắng qua đêm."}, {"type": "h2", "text": "Cắt tỉa lá già, lá vàng"}, {"type": "list", "items": ["Lá già ở gốc vàng dần rồi khô là quá trình tự nhiên. Khi lá vàng quá nửa thì cắt sát cuống bằng kéo sạch.", "Lá chỉ khô đầu, cháy mép: có thể cắt theo đường viền lá, giữ lại phần xanh để lá vẫn làm việc.", "Lá bị đốm nấm, thối nhũn: cắt bỏ ngay, bỏ vào túi kín, không vứt lại trong chậu.", "Cành khô, ngọn vươn dài ở cây thân bụi: cắt phía trên một mắt lá để cây đâm nhánh mới."], "ordered": false}, {"type": "note", "title": "Lau kéo trước và sau khi cắt", "text": "Lau lưỡi kéo bằng cồn y tế giữa các cây, nhất là khi vừa cắt lá bệnh. Đây là cách đơn giản nhất để không lây nấm từ cây này sang cây khác."}, {"type": "h2", "text": "Tranh thủ kiểm tra sâu bệnh"}, {"type": "p", "text": "Khi lau lá, hãy để ý các dấu hiệu sau:"}, {"type": "list", "items": ["Chấm vàng li ti, có tơ mảnh ở mặt dưới lá: có thể là [nhện đỏ](/benh-cay/nhen-do).", "Cục bông trắng ở nách lá, kẽ cuống: [rệp sáp](/benh-cay/rep-sap).", "Lá dính nhớt, có lớp bụi đen: rệp tiết mật, đọc thêm [muội đen](/benh-cay/muoi-den)."], "ordered": false}, {"type": "p", "text": "Phát hiện sớm khi mới vài con thì chỉ cần lau sạch bằng khăn ẩm, cách ly cây và theo dõi thêm, chưa cần dùng thuốc."}, {"type": "h2", "text": "Lịch gợi ý"}, {"type": "table", "rows": [["Việc", "Bao lâu một lần"], ["Lau bụi lá", "2–3 tuần"], ["Kiểm tra mặt dưới lá", "Mỗi lần tưới"], ["Cắt lá vàng, lá khô", "Khi thấy"], ["Tắm cây dưới vòi sen", "1–2 tháng"]]}, {"type": "products", "title": "Cây lá to bóng, đẹp hơn sau khi lau", "slugs": ["trau-ba-de-vuong-xanh", "trau-ba-de-vuong-do", "bach-ma-hoang-tu", "ngan-hau", "van-nien-thanh"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/%E0%AE%9A%E0%AF%80%E0%AE%AE%E0%AF%88_%E0%AE%86%E0%AE%B2%E0%AE%AE%E0%AE%B0%E0%AE%AE%E0%AF%8D_1_%28Ficus_elastica%29.jpg/960px-%E0%AE%9A%E0%AF%80%E0%AE%AE%E0%AF%88_%E0%AE%86%E0%AE%B2%E0%AE%AE%E0%AE%B0%E0%AE%AE%E0%AF%8D_1_%28Ficus_elastica%29.jpg', 3, '["nhen-do", "rep-sap"]'::jsonb, '["lau lá", "cắt tỉa", "kiểng lá", "chăm sóc cây"]'::jsonb, 'Cách lau lá cây kiểng lá đúng cách, có nên dùng chất làm bóng lá, cắt tỉa lá già, lá vàng ở đâu và những điều cần tránh để cây đẹp lâu.', 28),
('nhan-giong-cay-canh-tai-nha', 'cham-soc', 'Nhân giống cây cảnh tại nhà: giâm cành, tách bụi, giâm lá cho người mới', 'Từ một chậu cây khỏe, bạn có thể có thêm vài chậu nhỏ để tặng hoặc trồng góc khác. Bài này hướng dẫn ba cách nhân giống dễ nhất — tách bụi, giâm cành, giâm lá — và cây nào hợp với cách nào.', '[{"type": "p", "text": "Nhân giống cây cảnh tại nhà không khó như nhiều người nghĩ. Phần lớn cây kiểng lá phổ biến đều có thể tách bụi hoặc giâm cành, chỉ cần chọn đúng mùa và giữ cây con ẩm vừa phải."}, {"type": "h2", "text": "Chọn thời điểm"}, {"type": "p", "text": "Nên nhân giống khi cây mẹ đang khỏe và đang ra lá mới. Ở miền Tây, mùa mưa (khoảng tháng 5 đến tháng 10) không khí ẩm nên cành giâm dễ ra rễ. Tránh làm khi cây mẹ đang bệnh hoặc vừa thay chậu."}, {"type": "h2", "text": "Cách 1: Tách bụi — dễ nhất, cây con lớn nhanh"}, {"type": "p", "text": "Hợp với cây mọc thành bụi nhiều chồi từ gốc: [lan ý](/san-pham/lan-y), [lưỡi hổ](/san-pham/luoi-ho), [lan chi](/san-pham/lan-chi), [dương xỉ](/san-pham/duong-xi), đuôi công."}, {"type": "list", "items": ["Tưới ẩm cây trước 1 ngày, lấy cả bầu ra khỏi chậu.", "Gỡ nhẹ đất, tìm chỗ các chồi tách nhau tự nhiên. Mỗi phần tách ra nên có ít nhất 2–3 chồi và rễ riêng.", "Dùng tay tách hoặc dao sạch cắt dứt khoát. Cắt bỏ rễ hư.", "Trồng mỗi phần vào chậu vừa cỡ, đất tơi, tưới đẫm, để chỗ râm 7–10 ngày."], "ordered": true}, {"type": "h2", "text": "Cách 2: Giâm cành (giâm ngọn) — hợp cây thân leo, thân đốt"}, {"type": "p", "text": "Hợp với trầu bà, [vạn niên thanh](/san-pham/van-nien-thanh), cây thân bụi như hoa hồng, mai địa thảo."}, {"type": "list", "items": ["Chọn đoạn cành khỏe dài 10–15cm, có ít nhất 2 mắt (đốt). Với trầu bà, mỗi đoạn cần có rễ khí hoặc mắt ở thân.", "Cắt chéo ngay dưới một mắt bằng kéo sạch. Tỉa bớt lá dưới, giữ 1–2 lá trên.", "Cắm vào ly nước sạch (thay nước 3–4 ngày/lần) hoặc vào đất tơi ẩm. Nước dễ quan sát rễ hơn.", "Rễ dài 3–5cm (thường sau 2–4 tuần) thì chuyển ra chậu đất."], "ordered": true}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/TQ30QBDKB4.jpg", "caption": "Cành giâm trong ly nước — thay nước định kỳ, rễ trắng dài vài cm là trồng ra đất được."}, {"type": "h2", "text": "Cách 3: Giâm lá — cho cây mọng nước"}, {"type": "p", "text": "[Ngọc bích](/san-pham/ngoc-bich), sen đá và lưỡi hổ có thể giâm từ lá:"}, {"type": "list", "items": ["Ngọc bích, sen đá: bẻ nguyên lá, để khô vết cắt 2–3 ngày, đặt lên mặt đất cát khô, phun ẩm nhẹ khi đất khô hẳn. Vài tuần sau rễ và cây con mọc từ cuống lá.", "Lưỡi hổ: cắt lá thành từng khúc 8–10cm, nhớ chiều trên dưới, để khô vết cắt rồi cắm phần dưới xuống cát ẩm. Cách này lâu (1–3 tháng) và cây con lưỡi hổ viền vàng thường mất viền vàng — muốn giữ màu thì nên tách bụi."], "ordered": false}, {"type": "h2", "text": "Chăm sóc cây con"}, {"type": "list", "items": ["Đặt chỗ sáng tán xạ, tránh nắng trực tiếp.", "Giữ đất hơi ẩm, không sũng nước. Cây con chưa có nhiều rễ nên rất dễ thối khi úng.", "Chưa bón phân trong tháng đầu. Khi cây ra 2–3 lá mới mới bón loãng.", "Cành giâm úa vàng, thâm đen ở gốc: bỏ ngay để không lây cho cành khác."], "ordered": false}, {"type": "note", "title": "Cây đang được bảo hộ giống", "text": "Một số giống cây lai mới có đăng ký bảo hộ giống cây trồng. Nhân giống để trồng trong nhà, tặng người quen thì không sao; nhân hàng loạt để bán thì nên tìm hiểu trước."}, {"type": "products", "title": "Cây dễ nhân giống cho người mới", "slugs": ["lan-y", "luoi-ho", "lan-chi", "duong-xi", "ngoc-bich", "van-nien-thanh"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/LVFO7CARHB.jpg', 3, '[]'::jsonb, '["nhân giống", "giâm cành", "tách bụi", "cây con"]'::jsonb, 'Hướng dẫn nhân giống cây cảnh tại nhà: tách bụi lan ý, lưỡi hổ; giâm cành trầu bà; giâm lá cây mọng nước. Thời điểm, cách làm và chăm cây con.', 35),
('cham-soc-cay-moi-mua-ve', 'cham-soc', 'Cây mới mua về: chăm thế nào trong 7 ngày đầu để cây không sốc, rụng lá', 'Cây ở vườn quen nắng gió, độ ẩm và lịch tưới khác hẳn trong nhà bạn. Vài ngày đầu cây rũ, vàng một hai lá là chuyện thường. Đây là việc nên làm và không nên làm trong tuần đầu để cây quen chỗ mới.', '[{"type": "p", "text": "Từ vườn ươm đến nhà bạn, cây đã trải qua đóng gói, vận chuyển, đổi nắng đổi gió. Cây khỏe đến đâu cũng cần vài ngày để thích nghi. Chăm đúng trong tuần đầu giúp cây ổn định nhanh, ra lá mới sớm."}, {"type": "h2", "text": "Ngày đầu: kiểm tra cây"}, {"type": "list", "items": ["Mở bao bì ngay khi nhận, để cây đứng thẳng nơi thoáng mát.", "Xem kỹ lá, thân, mặt dưới lá và gốc. Gãy cành, dập lá khi vận chuyển thì cắt bỏ phần dập.", "Sờ đất: khô 3–4cm thì tưới một lần vừa phải, còn ẩm thì chưa tưới.", "Chụp vài tấm ảnh cây lúc nhận. Nếu sau đó cây có vấn đề, ảnh này giúp shop xem lại tình trạng ban đầu khi bạn gửi [yêu cầu bảo hành](/tai-khoan/bao-hanh)."], "ordered": true}, {"type": "p", "text": "Xem thêm [cách chọn cây khỏe khi mua](/goc-cham-cay/cach-chon-cay-khoe-khi-mua) để biết cần nhìn chỗ nào."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/MBP7GJDWJJ.jpg", "caption": "Tuần đầu nên đặt cây mới ở chỗ sáng nhẹ, thoáng mát và ít di chuyển để cây quen dần với chỗ mới."}, {"type": "h2", "text": "Ngày 2–7: cho cây quen chỗ mới"}, {"type": "list", "items": ["**Chọn chỗ sáng nhẹ:** dù là cây ưa nắng, tuần đầu nên đặt chỗ sáng nhẹ hoặc nắng sớm, rồi mới đưa dần ra chỗ nắng hơn.", "**Không đổi chỗ liên tục:** mỗi lần đổi chỗ cây lại phải thích nghi lại.", "**Tưới khi đất khô mặt:** không tưới theo lịch cũ ở vườn. Trong nhà mát, cây hút nước chậm hơn ngoài vườn nhiều.", "**Tránh gió máy lạnh, quạt thổi thẳng.**"], "ordered": false}, {"type": "h2", "text": "Không nên làm trong tuần đầu"}, {"type": "list", "items": ["**Thay chậu ngay:** trừ khi chậu vỡ hoặc đất úng nặng. Đợi 1–2 tuần cho cây ổn định rồi mới [thay chậu](/goc-cham-cay/thay-chau-cay-canh-dung-cach).", "**Bón phân:** cây đang thích nghi, rễ chưa hút mạnh, bón lúc này dễ cháy rễ.", "**Tưới thật nhiều vì thấy cây rũ:** cây rũ do sốc thường không phải do khát. Tưới thêm vào đất còn ướt làm rễ úng.", "**Đặt sát cây cũ đang bệnh:** cách ly cây mới khoảng 1–2 tuần để chắc không mang theo rệp, nhện."], "ordered": true}, {"type": "h2", "text": "Cây rụng vài lá, vàng lá có sao không?"}, {"type": "p", "text": "Vàng 1–2 lá già ở gốc, rũ nhẹ trong 2–5 ngày đầu là phản ứng bình thường khi đổi môi trường. Cây thường hồi lại sau 1–2 tuần. Đáng lo khi:"}, {"type": "list", "items": ["Lá non, ngọn non héo, đen.", "Gốc mềm nhũn, đất có mùi hôi.", "Lá rụng hàng loạt dù đất vẫn ẩm vừa."], "ordered": false}, {"type": "p", "text": "Khi đó đọc bài [rụng lá do sốc môi trường](/benh-cay/rung-la-soc-moi-truong), và nếu là cây sống mua tại shop trong 7 ngày thì gửi ảnh qua mục Bảo hành để kỹ sư xem."}, {"type": "note", "title": "Bảo hành cây sống", "text": "Cây sống mua tại Cây Cảnh Miền Tây được bảo hành 7 ngày kể từ khi nhận. Xem điều kiện ở trang [Chính sách bảo hành cây](/chinh-sach/bao-hanh-cay)."}, {"type": "products", "title": "Cây dễ thích nghi khi mới về", "slugs": ["luoi-ho", "phu-quy", "lan-chi", "bach-ma-hoang-tu"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/KMGC56X3AO.jpg', 3, '["rung-la-soc-moi-truong"]'::jsonb, '["cây mới mua", "sốc môi trường", "chăm sóc cây"]'::jsonb, 'Cây cảnh mới mua về nên chăm thế nào: kiểm tra cây, chọn chỗ đặt, tưới nước, có nên thay chậu, bón phân ngay không. Cách giúp cây không bị sốc môi trường.', 41),
('cham-soc-lan-y-ra-hoa', 'cham-soc', 'Chăm lan ý ra hoa trắng đều: ánh sáng, tưới nước và lý do cây chỉ ra lá', 'Lan ý (Spathiphyllum) là cây văn phòng quen thuộc với lá xanh bóng và hoa trắng như cánh buồm. Cây dễ sống nhưng nhiều nhà chỉ thấy lá mà không thấy hoa. Đây là cách chăm để lan ý khỏe và ra hoa đều.', '[{"type": "p", "text": "[Lan ý](/san-pham/lan-y) là một trong số ít cây vừa chịu bóng, vừa ra hoa trong nhà. Lá cây mềm, xanh đậm, khi thiếu nước lá rũ xuống rất rõ — giống như \"báo\" cho chủ biết đã đến lúc tưới. Vì vậy lan ý rất hợp với người mới."}, {"type": "h2", "text": "Ánh sáng: đủ sáng mới ra hoa"}, {"type": "p", "text": "Lan ý sống được dưới đèn văn phòng, nhưng **muốn ra hoa đều cây cần sáng tán xạ khá**, ví dụ cách cửa sổ có rèm mỏng 1–2m. Cây đặt góc tối vẫn xanh nhưng thường chỉ ra lá. Ngược lại, nắng trực tiếp buổi trưa làm lá vàng úa, có mảng cháy."}, {"type": "h2", "text": "Tưới nước: để lá \"nói\""}, {"type": "list", "items": ["Giữ đất hơi ẩm, tưới khoảng 2–3 lần mỗi tuần tùy độ khô của phòng.", "Khi lá bắt đầu rũ nhẹ là lúc tưới đẫm; vài giờ sau lá sẽ dựng lại. Đừng để cây héo rũ hoàn toàn nhiều lần, mép lá sẽ khô nâu.", "Không để đọng nước dưới đĩa. Đất sũng lâu ngày là nguyên nhân chính gây [thối rễ](/benh-cay/thoi-re) ở lan ý."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/SpathiphyllumWallisii.jpg/960px-SpathiphyllumWallisii.jpg", "caption": "Hoa lan ý gồm một mo trắng ôm lấy bông hoa hình trụ ở giữa — mo trắng chuyển dần sang xanh khi hoa già."}, {"type": "h2", "text": "Bón phân"}, {"type": "p", "text": "Lan ý không cần nhiều phân. Mùa cây đang ra lá mới, bón phân hòa tan loãng (khoảng nửa liều ghi trên bao) mỗi tháng một lần, hoặc rắc phân tan chậm 2–3 tháng/lần. Bón quá nhiều làm mép lá cháy nâu, cây ra lá mà ít hoa. Xem thêm [cách bón phân cho cây kiểng lá trong nhà](/goc-cham-cay/bon-phan-cay-kieng-la-trong-nha)."}, {"type": "h2", "text": "Vì sao lan ý không ra hoa?"}, {"type": "list", "items": ["**Thiếu sáng** — lý do phổ biến nhất. Đưa cây ra chỗ sáng hơn vài tuần.", "**Cây còn nhỏ** — cây con mới tách bụi cần thời gian lớn.", "**Chậu quá chật, đất đã cạn dinh dưỡng** — cây đứng lá lâu, rễ trồi khỏi chậu.", "**Bón phân đạm quá nhiều** — cây mải ra lá."], "ordered": true}, {"type": "h2", "text": "Hoa chuyển xanh, lá vàng có sao không?"}, {"type": "p", "text": "Hoa lan ý nở được vài tuần rồi mo trắng chuyển xanh dần, sau đó nâu khô — đó là hoa già, không phải bệnh. Cắt sát gốc cuống hoa để cây dồn sức ra hoa mới. Lá già ở ngoài cùng vàng dần cũng là bình thường; nhiều lá cùng vàng một lúc thì kiểm tra lại việc tưới."}, {"type": "h2", "text": "Tách bụi khi cây quá dày"}, {"type": "p", "text": "Sau 1–2 năm, bụi lan ý dày chật chậu. Có thể tách thành 2–3 bụi nhỏ, mỗi bụi có vài chồi và rễ riêng. Xem cách làm ở bài [nhân giống cây cảnh tại nhà](/goc-cham-cay/nhan-giong-cay-canh-tai-nha)."}, {"type": "note", "title": "Lưu ý với trẻ nhỏ, thú cưng", "text": "Lá và hoa lan ý có tinh thể canxi oxalat, nhai phải gây ngứa, rát miệng. Nên đặt cây trên kệ cao, xa tầm với của trẻ nhỏ và chó mèo. Xem thêm [cây an toàn cho nhà có trẻ nhỏ, thú cưng](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung)."}, {"type": "products", "title": "Lan ý tại vườn", "slugs": ["lan-y", "lan-y-nu-hoang"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Spathiphyllum_wallisii_-_Botanischer_Garten_-_Heidelberg%2C_Germany_-_DSC01079.jpg/960px-Spathiphyllum_wallisii_-_Botanischer_Garten_-_Heidelberg%2C_Germany_-_DSC01079.jpg', 3, '["thoi-re", "chay-la-do-nang"]'::jsonb, '["lan ý", "cây văn phòng", "cây ra hoa", "chăm sóc cây"]'::jsonb, 'Cách chăm sóc cây lan ý ra hoa: ánh sáng phù hợp, tưới nước khi lá rũ, bón phân, tách bụi, xử lý lá vàng, hoa xanh và lưu ý an toàn với thú cưng.', 46),
('trong-hoa-hong-chau-ban-cong', 'cham-soc', 'Trồng hoa hồng chậu ở ban công: nắng, tưới, cắt tỉa để hoa ra đều quanh năm', 'Hoa hồng không khó trồng như lời đồn nếu có đủ nắng và chậu thoát nước tốt. Bài này hướng dẫn chọn chỗ đặt, tưới, bón phân và cắt tỉa sau mỗi đợt hoa để hồng chậu ở ban công nở đều.', '[{"type": "p", "text": "[Hoa hồng](/san-pham/hoa-hong) là cây ra hoa được yêu thích nhất, và cũng hay bị cho là \"khó\". Thật ra phần lớn chậu hồng yếu là do thiếu nắng, tưới lên lá vào buổi tối và không cắt tỉa sau hoa. Sửa ba điều này, hồng chậu sẽ khỏe lên rõ rệt."}, {"type": "h2", "text": "Nắng là điều kiện số một"}, {"type": "p", "text": "Hoa hồng cần **ít nhất 6 giờ nắng trực tiếp mỗi ngày**. Ban công hướng Đông (nắng sáng) là lý tưởng; hướng Nam, Tây cũng được nhưng trưa hè nên có lưới che mỏng. Ban công chỉ có nắng 2–3 giờ thì hồng sẽ ít hoa, lá dễ nấm bệnh — khi đó nên chọn cây chịu bóng hơn như [mai địa thảo](/san-pham/mai-dia-thao)."}, {"type": "h2", "text": "Chậu và đất"}, {"type": "list", "items": ["Chậu đường kính từ 25–30cm trở lên cho một gốc hồng, có lỗ thoát nước to.", "Đất tơi, giàu mùn: đất thịt nhẹ trộn với phân trùn quế hoặc phân bò hoai, thêm tro trấu cho thoát nước.", "Lót sỏi hoặc đặt chậu lên kệ để đáy chậu không đọng nước sau mưa."], "ordered": false}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/VWLM7UWJUU.jpg", "caption": "Hồng đủ nắng, được cắt tỉa sau mỗi đợt hoa sẽ ra hoa nối tiếp thành từng chùm."}, {"type": "h2", "text": "Tưới nước: tưới gốc, tưới sáng"}, {"type": "list", "items": ["Tưới vào gốc mỗi sáng trong mùa nắng; mùa mưa thì xem đất, khô mặt mới tưới.", "**Tránh tưới lên lá và hoa, nhất là buổi chiều tối.** Lá ướt qua đêm là điều kiện để nấm [đốm đen](/benh-cay/dom-la-nam) và [phấn trắng](/benh-cay/phan-trang) phát triển.", "Không để chậu khô kiệt rồi mới tưới ngập; hồng thích ẩm đều."], "ordered": false}, {"type": "h2", "text": "Bón phân"}, {"type": "p", "text": "Hồng ra hoa liên tục nên cần phân đều đặn hơn cây kiểng lá:"}, {"type": "list", "items": ["Mỗi tháng một lần rắc phân hữu cơ (phân trùn quế, phân bò hoai) quanh mép chậu, xới nhẹ.", "Giữa các lần, có thể tưới phân hòa tan loãng có tỉ lệ lân, kali cao hơn đạm khi cây ra nụ. Đọc thêm [cách đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."], "ordered": false}, {"type": "h2", "text": "Cắt tỉa sau mỗi đợt hoa"}, {"type": "list", "items": ["Hoa tàn thì cắt cả cành hoa, vết cắt ở trên một lá có 5 lá chét, hướng mắt ngủ ra ngoài.", "Cắt bỏ cành khô, cành nhỏ yếu mọc vào trong tán để tán thoáng.", "Sau 3–4 tuần, mắt ngủ sẽ bật cành mới và ra đợt hoa tiếp."], "ordered": true}, {"type": "h2", "text": "Sâu bệnh hay gặp ở hồng chậu"}, {"type": "list", "items": ["**Đốm đen, vàng rụng lá:** nấm, gặp nhiều mùa mưa — ngắt lá bệnh, tránh tưới lá.", "**Phấn trắng:** lớp bột trắng trên lá non, hay gặp khi trời nóng ẩm, thiếu thoáng.", "**Rệp, bọ trĩ:** bám đọt non và nụ, làm nụ teo, hoa méo. Xem [rệp muội](/benh-cay/rep-muoi), [bọ trĩ](/benh-cay/bo-tri)."], "ordered": false}, {"type": "p", "text": "Khi bệnh nặng phải dùng thuốc, chọn loại có đăng ký cho hoa cây cảnh và đọc kỹ nhãn. Xem [Hướng dẫn dùng thuốc BVTV an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Ban công thường gần cửa sổ, chỗ phơi đồ và gần hàng xóm. Nếu phải phun thuốc, phun lúc lặng gió, đóng cửa sổ, cất đồ phơi và đeo găng tay, khẩu trang; đọc kỹ nhãn về liều và thời gian cách ly."}, {"type": "products", "title": "Cây ra hoa cho ban công", "slugs": ["hoa-hong", "mai-dia-thao", "tulip-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Rose_flower_plants.JPG/960px-Rose_flower_plants.JPG', 3, '["dom-la-nam", "phan-trang", "rep-muoi", "bo-tri"]'::jsonb, '["hoa hồng", "ban công", "cây ra hoa", "cắt tỉa"]'::jsonb, 'Cách trồng và chăm hoa hồng chậu ở ban công: chọn chỗ đủ 6 giờ nắng, đất, tưới gốc buổi sáng, bón phân, cắt tỉa sau hoa và phòng bệnh đốm lá, phấn trắng.', 48),
('cham-cay-cong-trinh-moi-trong', 'cham-soc', 'Chăm cây công trình mới trồng: tưới, chống đỡ, bón phân trong 3 tháng đầu', 'Cây bóng mát, cây đường phố mới trồng chết phần lớn trong 1–3 tháng đầu vì thiếu nước, gió lay gốc hoặc hố trồng úng. Đây là quy trình chăm cơ bản cho bằng lăng, kèn hồng, giáng hương, dầu rái… để cây bén rễ chắc.', '[{"type": "p", "text": "Cây công trình thường được trồng với bầu đất đã bó gọn, rễ bị cắt bớt khi bứng ở vườn. Ba tháng đầu cây sống chủ yếu nhờ bộ rễ trong bầu và nước ta tưới. Chăm kỹ giai đoạn này quyết định cây sống hay chết."}, {"type": "h2", "text": "Tưới nước — việc quan trọng nhất"}, {"type": "list", "items": ["**1–2 tháng đầu:** tưới đẫm 1 lần mỗi ngày (mùa khô có thể 2 lần với cây lớn), nước phải ngấm sâu tới đáy bầu, không chỉ ướt mặt.", "**Tháng thứ 3 trở đi:** giảm dần, 2–3 ngày một lần tùy thời tiết khi thấy cây ra lá non.", "Mùa mưa vẫn kiểm tra: mưa rào ngắn có khi không đủ ngấm tới bầu rễ; ngược lại mưa dầm thì phải xem hố có đọng nước không.", "Làm bồn tưới (gờ đất vòng quanh gốc) để nước không chảy tràn đi."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Caged_and_Painted_Fruit_Tree_%28c14c049a-e7d9-48af-a433-09788f7de487%29.jpg/960px-Caged_and_Painted_Fruit_Tree_%28c14c049a-e7d9-48af-a433-09788f7de487%29.jpg", "caption": "Cây non mới trồng được buộc vào cọc chống và có lồng bảo vệ thân — gió không lay được bầu rễ."}, {"type": "h2", "text": "Cọc chống — giữ bầu rễ không lay"}, {"type": "p", "text": "Gió lay thân cây làm bầu đất xoay trong hố, rễ non vừa mọc lại bị đứt. Dùng 3 cọc chống hình chân kiềng hoặc cọc đôi, buộc dây mềm (cao su, vải) quanh thân, có lót đệm để không cứa vỏ. Kiểm tra dây buộc mỗi tháng, nới ra khi thân to lên. Tháo cọc khi cây đã bén rễ chắc (thường 6–12 tháng)."}, {"type": "h2", "text": "Vun gốc và phủ gốc"}, {"type": "list", "items": ["Giữ mặt bầu ngang hoặc hơi cao hơn mặt đất xung quanh — trồng sâu quá dễ thối cổ rễ.", "Phủ gốc bằng rơm, lá khô, vỏ cây băm dày 5–7cm, chừa khoảng hở quanh thân. Lớp phủ giữ ẩm, giảm cỏ dại."], "ordered": false}, {"type": "h2", "text": "Bón phân: chờ cây bén rễ"}, {"type": "p", "text": "Không bón phân hóa học nồng vào hố ngay khi trồng. Có thể trộn phân hữu cơ hoai vào đất lấp hố. Khi cây đã ra 1–2 đợt lá mới (khoảng 1–2 tháng), bón thêm phân hữu cơ quanh mép bồn, sau đó bón NPK liều nhẹ 2–3 tháng/lần."}, {"type": "h2", "text": "Tỉa cành"}, {"type": "p", "text": "Sau khi trồng có thể tỉa bớt cành nhỏ, cành gãy để giảm mất nước qua lá, nhưng giữ cành chính tạo tán. Không tỉa trụi lá."}, {"type": "h2", "text": "Dấu hiệu cây không bén rễ"}, {"type": "list", "items": ["Lá héo rũ cả ngày dù vẫn tưới đủ.", "Lá vàng rụng hàng loạt, cành nhỏ khô từ ngọn xuống.", "Cạo nhẹ vỏ cành thấy lớp dưới vỏ nâu khô thay vì xanh."], "ordered": false}, {"type": "p", "text": "Nếu hố trồng úng nước, cần khơi rãnh thoát. Nếu đất khô sâu trong bầu dù mặt đất ướt, có thể bầu đất quá chặt khiến nước không thấm vào — cần xăm lỗ quanh bầu và tưới chậm."}, {"type": "p", "text": "Muốn chọn đúng loài cho từng vị trí, xem thêm [chọn cây công trình cho đường phố, sân trường](/goc-cham-cay/chon-cay-cong-trinh-duong-pho-san-truong). Đơn vị thi công cần số lượng lớn có thể gửi danh sách ở trang [báo giá sỉ](/bao-gia-si)."}, {"type": "products", "title": "Cây công trình tại vườn", "slugs": ["bang-lang", "ken-hong", "giang-huong", "dau-rai", "phuong-vi", "bang-dai-loan"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Joe_uses_white_paint_to_protect_the_tender_bark_of_the_young_tree_from_sun_damage%2C_cracking%2C_and_rodents._%28fb65245e-e617-4829-aa00-b942d3cbf77a%29.JPG/960px-Joe_uses_white_paint_to_protect_the_tender_bark_of_the_young_tree_from_sun_damage%2C_cracking%2C_and_rodents._%28fb65245e-e617-4829-aa00-b942d3cbf77a%29.JPG', 3, '["heo-thieu-nuoc"]'::jsonb, '["cây công trình", "cây bóng mát", "trồng cây", "chăm sóc cây"]'::jsonb, 'Cách chăm sóc cây công trình, cây bóng mát mới trồng: tưới nước 3 tháng đầu, cọc chống, vun gốc, bón phân, tỉa cành và dấu hiệu cây không bén rễ.', 49),
('la-cay-bi-vang-nguyen-nhan', 'bat-benh', 'Lá cây cảnh bị vàng: 8 nguyên nhân thường gặp và cách đoán đúng trước khi xử lý', 'Vàng lá là dấu hiệu chung của rất nhiều vấn đề: tưới nhiều, tưới ít, thiếu sáng, thiếu phân, rễ thối hay chỉ đơn giản là lá già. Nhìn vị trí lá vàng, kiểu vàng và tình trạng đất, bạn có thể đoán đúng nguyên nhân trong vài phút.', '[{"type": "p", "text": "Khi thấy lá vàng, phản xạ của nhiều người là tưới thêm nước hoặc bón thêm phân. Nhưng nếu nguyên nhân là úng rễ thì tưới thêm chỉ làm cây yếu hơn. Trước khi làm gì, hãy trả lời ba câu hỏi: **lá nào vàng** (già hay non), **vàng kiểu gì** (cả lá, giữa gân, có đốm), và **đất đang khô hay ướt**."}, {"type": "h2", "text": "Bảng tra nhanh"}, {"type": "table", "rows": [["Bạn thấy gì", "Nguyên nhân hay gặp"], ["1–2 lá già nhất ở gốc vàng dần rồi khô, cây vẫn ra lá mới", "Lá già tự nhiên — không cần lo"], ["Nhiều lá vàng mềm, đất ẩm lâu, gốc có mùi", "Tưới quá nhiều, úng rễ"], ["Lá vàng khô giòn, mép quăn, đất khô cứng", "Thiếu nước"], ["Lá vàng nhạt đều, bắt đầu từ lá già lan dần lên", "Thiếu đạm"], ["Lá non vàng nhưng gân lá vẫn xanh", "Thiếu sắt hoặc vi lượng"], ["Lá vàng lấm tấm li ti, mặt dưới có tơ mảnh", "Nhện đỏ"], ["Lá vàng hàng loạt ngay sau khi đổi chỗ, thay chậu", "Sốc môi trường"], ["Cây vươn dài, lá dưới vàng rụng, lá mới nhỏ", "Thiếu sáng"]]}, {"type": "h2", "text": "1. Tưới quá nhiều — nguyên nhân số một ở cây trong nhà"}, {"type": "p", "text": "Đất ướt liên tục làm rễ thiếu khí, rễ non chết dần, cây không hút được nước nên lá lại vàng như thiếu nước. Dấu hiệu: lá vàng mềm, không giòn; đất lâu khô, đôi khi có nấm trắng trên mặt; gốc thâm. Ngưng tưới đến khi đất khô 3–4cm, đổ nước đọng ở đĩa. Nếu gốc mềm, rễ nâu đen thì xem bài [thối rễ](/benh-cay/thoi-re)."}, {"type": "h2", "text": "2. Thiếu nước"}, {"type": "p", "text": "Lá vàng khô, giòn từ mép vào, lá rũ rồi quăn. Đất co lại tách khỏi thành chậu. Tưới đẫm từ từ cho nước thấm hết bầu; nếu đất quá khô không thấm, ngâm cả chậu vào thau nước 15–20 phút. Xem thêm [héo do thiếu nước](/benh-cay/heo-thieu-nuoc)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Chlorosis_12848.JPG/960px-Chlorosis_12848.JPG", "caption": "Lá vàng nhưng gân còn xanh — kiểu vàng này hay gặp khi thiếu sắt, vi lượng, khác với vàng nhạt đều do thiếu đạm."}, {"type": "h2", "text": "3. Thiếu đạm (N)"}, {"type": "p", "text": "Cây trồng lâu không thay đất, không bón phân sẽ cạn đạm. Đạm di chuyển được trong cây nên cây lấy đạm từ lá già nuôi lá non: lá già vàng nhạt đều trước. Bón phân có đạm liều nhẹ, hoặc thay đất mới. Chi tiết ở [vàng lá do thiếu đạm](/benh-cay/vang-la-thieu-dam)."}, {"type": "h2", "text": "4. Thiếu sắt, vi lượng"}, {"type": "p", "text": "Ngược với thiếu đạm, thiếu sắt thể hiện ở **lá non**: phiến lá vàng, gân xanh rõ như mạng lưới. Hay gặp khi đất bị kiềm (tưới nước nhiều vôi, dùng tro chưa xả) hoặc rễ yếu. Xem [vàng lá gân xanh do thiếu sắt](/benh-cay/vang-la-thieu-sat)."}, {"type": "h2", "text": "5. Thiếu sáng"}, {"type": "p", "text": "Cây không đủ sáng sẽ \"bỏ\" bớt lá dưới để nuôi ngọn. Lá dưới vàng rụng dần, thân vươn dài. Dời cây ra chỗ sáng hơn từ từ. Tham khảo [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."}, {"type": "h2", "text": "6. Nhện đỏ và côn trùng chích hút"}, {"type": "p", "text": "Lá vàng không đều mà lấm tấm từng chấm nhỏ, nhìn kỹ mặt dưới lá thấy chấm li ti di chuyển, có tơ. Hay bùng phát mùa khô, phòng máy lạnh. Đọc bài [nhện đỏ mùa khô](/goc-cham-cay/nhen-do-mua-kho-cay-canh)."}, {"type": "h2", "text": "7. Sốc môi trường"}, {"type": "p", "text": "Cây vừa mua về, vừa thay chậu, vừa dời từ ngoài nắng vào trong nhà thường vàng vài lá trong 1–2 tuần. Giữ cây ổn định một chỗ, tưới vừa phải, không bón phân. Xem [cây mới mua về chăm thế nào](/goc-cham-cay/cham-soc-cay-moi-mua-ve)."}, {"type": "h2", "text": "8. Bón phân quá liều"}, {"type": "p", "text": "Bón nhiều, bón lúc đất khô làm rễ cháy: lá vàng rồi khô mép nhanh, mặt đất có lớp muối trắng. Tưới xả nhiều nước sạch cho phân trôi ra đáy chậu, ngưng bón 1–2 tháng. Xem [cháy rễ do bón phân quá liều](/benh-cay/chay-re-do-phan)."}, {"type": "h2", "text": "Khi nào nên nhờ kỹ sư xem?"}, {"type": "p", "text": "Khi lá vàng kèm thối nhũn thân, đốm lan nhanh, hoặc bạn đã sửa cách tưới mà cây vẫn tiếp tục vàng sau 2 tuần. Bạn có thể mang lá bệnh đến [cửa hàng](/he-thong-cua-hang) để được khám lá miễn phí, hoặc tra thêm ở [thư viện bệnh cây](/benh-cay)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Đừng phun thuốc khi chưa rõ nguyên nhân: phần lớn ca vàng lá ở cây trong nhà là do nước, sáng và phân, thuốc không giúp được mà còn làm cây yếu thêm. Khi cần dùng thuốc BVTV, chọn loại có đăng ký và làm đúng hướng dẫn trên nhãn."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Leaves_yellowing_in_symmetry.jpg/960px-Leaves_yellowing_in_symmetry.jpg', 4, '["vang-la-thieu-dam", "vang-la-thieu-sat", "thoi-re", "nhen-do", "heo-thieu-nuoc"]'::jsonb, '["vàng lá", "bệnh cây", "chẩn đoán", "kiểng lá"]'::jsonb, 'Vì sao lá cây cảnh bị vàng? Phân biệt vàng lá do tưới nhiều, thiếu nước, thiếu sáng, thiếu đạm, thiếu sắt, thối rễ, nhện đỏ và cách khắc phục.', 1),
('tri-rep-sap-cay-kieng-la', 'bat-benh', 'Rệp sáp trên cây kiểng lá: nhận biết sớm và xử lý từ cách đơn giản đến dùng thuốc', 'Những cục bông trắng nhỏ ở nách lá, kẽ cuống là rệp sáp — loài chích hút làm cây vàng lá, chậm lớn và kéo theo nấm muội đen. Phát hiện sớm thì chỉ cần tăm bông và cồn; để lâu mới phải dùng thuốc.', '[{"type": "p", "text": "Rệp sáp là côn trùng nhỏ, thân phủ lớp sáp trắng như bông. Chúng thích núp ở nơi kín: nách lá, kẽ cuống, mặt dưới lá, thậm chí dưới đất bám vào rễ. Rệp chích hút nhựa, tiết ra chất mật dính làm lá bóng nhớt, sau đó nấm [muội đen](/benh-cay/muoi-den) mọc phủ lên."}, {"type": "h2", "text": "Dấu hiệu nhận biết"}, {"type": "list", "items": ["Cục trắng như bông gòn ở nách lá, dọc gân lá, quanh mắt chồi.", "Lá dính, có lớp bóng nhớt; kiến bò lên xuống cây nhiều.", "Lá non xoăn, vàng, cây chậm ra lá mới.", "Khi thay chậu thấy bụi trắng bám quanh rễ: rệp sáp rễ."], "ordered": false}, {"type": "p", "text": "Cây hay bị: sen đá, xương rồng, lưỡi hổ, trầu bà, cây có nhiều kẽ lá. Rệp thường đi theo cây mới mua về hoặc lây từ chậu bên cạnh."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Soursop_%28Annona_muricata%29-_Ants_with_nest_tending_mealybugs_on_fruit.jpg/960px-Soursop_%28Annona_muricata%29-_Ants_with_nest_tending_mealybugs_on_fruit.jpg", "caption": "Rệp sáp phủ trắng thành đám trên quả mãng cầu xiêm, kiến bò quanh — kiến thường đi cùng rệp để lấy mật."}, {"type": "h2", "text": "Bước 1: Cách ly cây"}, {"type": "p", "text": "Ngay khi thấy rệp, dời cây ra xa các chậu khác ít nhất 1–2 tuần. Kiểm tra luôn các cây đứng gần."}, {"type": "h2", "text": "Bước 2: Loại bỏ bằng tay — hiệu quả khi mới có ít rệp"}, {"type": "list", "items": ["Dùng tăm bông nhúng cồn y tế 70 độ chấm thẳng vào từng ổ rệp, rệp chết và lớp sáp tan.", "Lau sạch lá bằng khăn ẩm, lau cả mặt dưới và kẽ lá.", "Cây lá dày (lưỡi hổ, trầu bà) có thể xịt nước mạnh cho rệp rơi ra, che mặt đất trước.", "Cắt bỏ phần lá, cành bị nặng.", "Lặp lại mỗi 3–5 ngày trong 2–3 tuần, vì trứng nở ra lứa mới."], "ordered": true}, {"type": "p", "text": "Thử cồn trên một lá trước — lá mỏng, lá có lông có thể bị cháy."}, {"type": "h2", "text": "Bước 3: Xà phòng kali, dầu khoáng"}, {"type": "p", "text": "Khi rệp nhiều hơn, có thể xịt dung dịch xà phòng kali (xà phòng diệt côn trùng) hoặc dầu khoáng nông nghiệp theo đúng liều trên nhãn. Hai loại này tác động khi tiếp xúc trực tiếp, nên phải xịt ướt đều cả mặt dưới lá, kẽ lá. Không xịt khi nắng gắt; thử trước trên vài lá."}, {"type": "h2", "text": "Bước 4: Khi cần dùng thuốc BVTV"}, {"type": "p", "text": "Khi rệp lan rộng nhiều cây hoặc có rệp ở rễ, có thể cần thuốc trừ rệp có đăng ký dùng cho cây cảnh. Đọc kỹ nhãn về hoạt chất, liều pha và cách dùng; với rệp sáp rễ thường phải thay đất, rửa rễ. Không tự ý tăng liều, không pha trộn nhiều loại. Xem [Hướng dẫn dùng thuốc BVTV an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "h2", "text": "Phòng rệp quay lại"}, {"type": "list", "items": ["Kiểm tra mặt dưới lá, nách lá mỗi lần tưới.", "Cách ly cây mới mua 1–2 tuần trước khi đặt chung.", "Không bón quá nhiều đạm: đọt non mềm mọng thu hút rệp.", "Diệt kiến quanh chậu, vì kiến \"chăn nuôi\" rệp để lấy mật."], "ordered": false}, {"type": "p", "text": "Tra cứu thêm ở bài [rệp sáp](/benh-cay/rep-sap) trong thư viện bệnh cây."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Cồn, xà phòng kali, dầu khoáng tuy nhẹ hơn thuốc hóa học nhưng vẫn có thể làm cháy lá non. Khi dùng thuốc BVTV, đeo găng tay, khẩu trang, phun nơi thoáng gió, xa trẻ nhỏ, thú cưng và thức ăn; rửa tay sau khi phun."}, {"type": "products", "title": "Cây lá dày dễ lau, dễ xử lý rệp", "slugs": ["luoi-ho", "trau-ba-de-vuong-xanh", "bach-ma-hoang-tu", "ngoc-bich"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Kutu_putih_%28Phenacoccus_manihoti%29_dan_semut_merah_%28Solenopsis%29_pada_batang_daun_Pepaya_%28Carica_Papaya_L%29.jpg/960px-Kutu_putih_%28Phenacoccus_manihoti%29_dan_semut_merah_%28Solenopsis%29_pada_batang_daun_Pepaya_%28Carica_Papaya_L%29.jpg', 3, '["rep-sap", "muoi-den"]'::jsonb, '["rệp sáp", "sâu bệnh", "kiểng lá", "côn trùng hại cây"]'::jsonb, 'Cách nhận biết và trị rệp sáp trên cây kiểng lá, sen đá, cây văn phòng: lau cồn, xịt nước, xà phòng kali, cách ly cây và khi nào cần dùng thuốc BVTV.', 8),
('nhen-do-mua-kho-cay-canh', 'bat-benh', 'Nhện đỏ mùa khô: vì sao cây trong phòng máy lạnh hay bị và cách trị dứt điểm', 'Lá lấm tấm chấm vàng nhạt, mặt dưới có tơ mảnh, cây xỉn màu dần — đó là nhện đỏ. Chúng bùng phát khi trời khô nóng hoặc trong phòng máy lạnh. Nhện không phải côn trùng, nên nhiều loại thuốc trừ sâu thông thường không trị được.', '[{"type": "p", "text": "Nhện đỏ rất nhỏ, mắt thường chỉ thấy như hạt bụi li ti màu đỏ, nâu hoặc vàng nhạt. Chúng sống thành đàn ở mặt dưới lá, chích hút dịch lá làm mặt lá lấm tấm chấm nhạt màu. Mật độ cao thì kéo tơ mảnh như mạng nhện giữa lá và cuống."}, {"type": "h2", "text": "Vì sao mùa khô và phòng máy lạnh hay bị?"}, {"type": "p", "text": "Nhện đỏ thích không khí khô và nóng. Ở miền Tây, cuối mùa khô (khoảng tháng 2–4) là lúc nhện phát mạnh trên cây ngoài trời. Còn trong nhà, máy lạnh chạy cả ngày làm độ ẩm giảm sâu — điều kiện lý tưởng cho nhện quanh năm. Cây hay bị: [đuôi công](/san-pham/duoi-cong-xanh), [tùng thơm](/san-pham/tung-thom), [hoa hồng](/san-pham/hoa-hong), trầu bà, cây lá mỏng."}, {"type": "h2", "text": "Kiểm tra trong 30 giây"}, {"type": "p", "text": "Lấy tờ giấy trắng đặt dưới một cành, gõ nhẹ cành vài cái. Nếu thấy những chấm nhỏ li ti bò trên giấy, quẹt ra vệt đỏ nâu — đó là nhện. Hoặc lật mặt dưới lá, soi đèn pin điện thoại."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Tetranychus_urticae_15284.JPG/960px-Tetranychus_urticae_15284.JPG", "caption": "Lá bị nhện đỏ hại có những chấm nhỏ nhạt màu chi chít, nặng thì lá xỉn bạc và có tơ mảnh."}, {"type": "h2", "text": "Xử lý theo mức độ"}, {"type": "h3", "text": "Mới chớm (vài lá)"}, {"type": "list", "items": ["Cách ly cây ngay.", "Cắt bỏ lá bị nặng, cho vào túi kín.", "Xịt nước mạnh vào **mặt dưới lá** mỗi 2–3 ngày, liên tục 2 tuần. Nước làm nhện trôi đi và phá tơ.", "Tăng độ ẩm quanh cây: đặt khay sỏi có nước dưới chậu, gom cây lại, không đặt trước luồng gió máy lạnh."], "ordered": true}, {"type": "h3", "text": "Nhiều lá, đã có tơ"}, {"type": "list", "items": ["Xịt xà phòng kali hoặc dầu khoáng nông nghiệp theo liều ghi trên nhãn, ướt đều mặt dưới lá, nhắc lại sau 5–7 ngày.", "Khi vẫn không giảm, dùng **thuốc trừ nhện** (thuốc chuyên trị nhện) có đăng ký cho cây cảnh. Thuốc trừ sâu thông thường nhiều khi không diệt được nhện, thậm chí diệt luôn thiên địch làm nhện bùng mạnh hơn.", "Nhện nhanh quen thuốc: không dùng mãi một loại hoạt chất, làm đúng số lần và khoảng cách ghi trên nhãn."], "ordered": false}, {"type": "h2", "text": "Phòng nhện đỏ quay lại"}, {"type": "list", "items": ["Định kỳ [lau lá](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la), xịt rửa mặt dưới lá, nhất là mùa khô.", "Không để cây khát nước lâu: cây thiếu nước dễ bị nhện tấn công.", "Phòng máy lạnh: không đặt cây sát dàn lạnh; có thể dùng máy tạo ẩm.", "Cây mới mua cách ly 1–2 tuần."], "ordered": false}, {"type": "p", "text": "Tra cứu thêm ở bài [nhện đỏ](/benh-cay/nhen-do)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Khi phải phun thuốc trừ nhện trong nhà, nên đem cây ra ngoài nơi thoáng, phun xong để lá khô hẳn mới đem vào. Đeo găng tay, khẩu trang; tránh xa trẻ nhỏ, thú cưng, bể cá. Làm đúng liều và thời gian cách ly trên nhãn."}, {"type": "products", "title": "Cây lá dày ít bị nhện đỏ", "slugs": ["luoi-ho", "phu-quy", "van-loc", "bach-ma-hoang-tu"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Tetranychus_urticae_45631339.jpg/960px-Tetranychus_urticae_45631339.jpg', 3, '["nhen-do"]'::jsonb, '["nhện đỏ", "mùa khô", "sâu bệnh", "cây trong nhà"]'::jsonb, 'Cách nhận biết và trị nhện đỏ trên cây cảnh mùa khô, cây trong phòng máy lạnh: tăng ẩm, xịt nước mặt dưới lá, cách ly và chọn thuốc trừ nhện đúng loại.', 15),
('la-chay-mep-kho-dau-la', 'bat-benh', 'Lá cháy mép, khô đầu lá: do nắng, do nước hay do phân? Cách phân biệt và sửa', 'Đầu lá và mép lá khô nâu là chuyện rất hay gặp ở lan ý, đuôi công, cau, trầu bà. Đây ít khi là bệnh lây lan mà thường do nắng gắt, tưới thất thường, không khí khô hoặc muối phân tích tụ. Biết nguyên nhân thì sửa rất dễ.', '[{"type": "p", "text": "Mép lá là phần xa rễ nhất, nước và chất khoáng đi đến sau cùng. Vì vậy khi cây gặp bất kỳ \"căng thẳng\" nào về nước, mép và đầu lá là chỗ khô trước. Phần lá đã khô không xanh lại được, nhưng nếu sửa đúng nguyên nhân, lá mới ra sẽ lành lặn."}, {"type": "h2", "text": "Năm nguyên nhân thường gặp"}, {"type": "table", "rows": [["Dấu hiệu", "Nguyên nhân hay gặp"], ["Mảng cháy trắng bạc hoặc nâu ở phần lá hứng nắng", "Nắng gắt chiếu thẳng, đổi chỗ đột ngột"], ["Đầu lá khô nâu giòn, cây hay bị rũ rồi mới tưới", "Tưới thất thường, để đất khô kiệt"], ["Mép lá khô ở cây đặt gần máy lạnh, quạt", "Không khí khô, gió thổi trực tiếp"], ["Mép lá khô, mặt đất hoặc thành chậu có lớp trắng", "Tích tụ muối do phân bón, nước nhiều khoáng"], ["Viền vàng quanh vết nâu, vết lan nhanh, úng nước", "Có thể do vi khuẩn, nấm — cần xem kỹ"]]}, {"type": "h2", "text": "1. Nắng gắt"}, {"type": "p", "text": "Cây ưa bóng như [đuôi công](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea), lan ý, môn đặt chỗ nắng chiều sẽ cháy thành mảng. Cây ưa nắng mà đem từ trong nhà ra nắng ngay cũng cháy. Dời cây vào chỗ sáng tán xạ, hoặc tập nắng dần trong 1–2 tuần. Xem [cháy lá do nắng gắt](/benh-cay/chay-la-do-nang)."}, {"type": "h2", "text": "2. Tưới thất thường"}, {"type": "p", "text": "Để đất khô kiệt rồi tưới ngập, lặp lại nhiều lần làm đầu lá khô dần. Hãy tưới khi mặt đất khô 2–3cm, đều đặn hơn là tưới theo ngày cố định. Cây ưa ẩm như lan ý, dương xỉ không nên để héo rũ thường xuyên."}, {"type": "h2", "text": "3. Không khí khô, máy lạnh"}, {"type": "p", "text": "Phòng máy lạnh độ ẩm thấp, cây lá mỏng mất nước qua lá nhanh hơn rễ hút. Dời cây khỏi luồng gió, gom cây lại, đặt khay sỏi có nước dưới chậu. Phun sương chỉ giúp được trong thời gian ngắn."}, {"type": "h2", "text": "4. Muối phân, nước máy"}, {"type": "p", "text": "Bón phân hòa tan thường xuyên, tưới ít mỗi lần làm muối tích lại trong đất, rễ bị \"rát\", mép lá cháy. Cứ 1–2 tháng tưới xả một lần: tưới thật nhiều nước sạch cho nước chảy ra đáy chậu vài lần. Giảm liều phân. Với cây nhạy cảm như đuôi công, dùng nước để lắng qua đêm hoặc nước mưa. Xem thêm [cháy rễ do bón phân quá liều](/benh-cay/chay-re-do-phan)."}, {"type": "h2", "text": "5. Khi nào là bệnh?"}, {"type": "p", "text": "Vết cháy có viền vàng hoặc vòng úng nước, lan nhanh trong vài ngày, xuất hiện cả giữa lá chứ không chỉ ở mép — có thể là [cháy lá, đốm lá vi khuẩn](/benh-cay/chay-la-vi-khuan) hoặc nấm. Cắt bỏ lá bệnh, ngừng tưới lên lá, để cây thoáng, và mang lá đến [cửa hàng](/he-thong-cua-hang) để được xem."}, {"type": "h2", "text": "Có nên cắt phần lá khô?"}, {"type": "p", "text": "Được. Dùng kéo sạch cắt theo dáng lá, chừa một viền khô mỏng để không cắt vào phần xanh. Lá khô quá nửa thì cắt cả lá."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Cháy mép lá do môi trường không cần phun thuốc. Chỉ dùng thuốc BVTV khi đã xác định là nấm hoặc vi khuẩn, chọn thuốc có đăng ký và làm đúng hướng dẫn trên nhãn."}, {"type": "products", "title": "Cây chịu khô, ít cháy mép", "slugs": ["luoi-ho", "phu-quy", "ngoc-ngan", "bach-ma-hoang-tu"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/CalatheaMakoyana.jpg/960px-CalatheaMakoyana.jpg', 3, '["chay-la-do-nang", "chay-re-do-phan", "heo-thieu-nuoc", "chay-la-vi-khuan"]'::jsonb, '["cháy lá", "khô đầu lá", "chăm sóc cây", "kiểng lá"]'::jsonb, 'Vì sao lá cây cảnh cháy mép, khô đầu lá? Phân biệt do nắng gắt, thiếu nước, máy lạnh, muối phân, nước máy và cách khắc phục từng trường hợp.', 22),
('dom-la-nam-mua-mua', 'bat-benh', 'Đốm lá do nấm mùa mưa: nhận biết, cắt tỉa và phòng bệnh cho cây cảnh miền Tây', 'Mùa mưa miền Tây ẩm kéo dài là lúc nấm đốm lá, thán thư phát mạnh trên cây cảnh. Vết bệnh tròn, có viền, lan dần thành mảng. Bài này hướng dẫn phân biệt đốm nấm với cháy nắng và cách hạn chế bệnh lây lan.', '[{"type": "p", "text": "Từ khoảng tháng 5 đến tháng 11, miền Tây có những đợt mưa dầm, độ ẩm không khí rất cao. Lá ướt lâu, tán cây không thoáng là điều kiện để bào tử nấm nảy mầm. Bệnh đốm lá không làm cây chết nhanh, nhưng lá rụng nhiều, cây xấu đi và yếu dần."}, {"type": "h2", "text": "Nhận biết đốm lá do nấm"}, {"type": "list", "items": ["Vết đốm tròn hoặc bầu dục, thường có **viền rõ** màu nâu đậm, vàng hoặc tím quanh tâm nhạt màu.", "Vết lan to dần, nhiều vết liền lại thành mảng; lá vàng rồi rụng.", "Bệnh nặng ở lá già, lá phía dưới và phía trong tán, nơi ẩm lâu khô.", "Quan sát kỹ có thể thấy chấm đen li ti (ổ bào tử) trên vết bệnh."], "ordered": false}, {"type": "p", "text": "**Thán thư** là một dạng nặng hơn: vết lõm, khô, có vòng đồng tâm, có thể hại cả thân, quả. Xem [thán thư](/benh-cay/than-thu)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Tomato_septoria_leaf_spot_3006.jpg/960px-Tomato_septoria_leaf_spot_3006.jpg", "caption": "Đốm lá do nấm có viền rõ quanh vết bệnh và lan dần thành mảng khi trời ẩm kéo dài."}, {"type": "h2", "text": "Phân biệt với cháy nắng và vi khuẩn"}, {"type": "table", "rows": [["Đặc điểm", "Nấm đốm lá", "Cháy nắng", "Vi khuẩn"], ["Vị trí", "Rải rác khắp lá, lá già nhiều hơn", "Phần lá hứng nắng", "Rải rác, hay ở mép"], ["Viền", "Viền màu rõ, có vòng", "Không viền, mảng bạc", "Viền vàng, quầng úng nước"], ["Tiến triển", "Lan dần khi ẩm", "Không lan sau khi che nắng", "Lan nhanh, có thể nhũn"]]}, {"type": "h2", "text": "Xử lý"}, {"type": "list", "items": ["**Cắt bỏ lá bệnh** bằng kéo sạch, gom lá rụng quanh gốc, bỏ vào túi kín. Không ủ lá bệnh làm phân.", "**Ngưng tưới lên lá**, tưới gốc vào buổi sáng để lá khô trước tối.", "**Làm tán thoáng**: tỉa bớt lá trong, kê các chậu cách nhau, đưa cây ra chỗ có gió nhẹ.", "Cây ngoài trời mùa mưa nên có mái che mưa dầm nếu được.", "Khi bệnh lan nhanh, có thể dùng thuốc trừ nấm có đăng ký cho cây cảnh (ví dụ nhóm thuốc gốc đồng), phun theo liều trên nhãn, ướt đều hai mặt lá, phun lặp lại theo khoảng cách hướng dẫn."], "ordered": true}, {"type": "h2", "text": "Phòng bệnh cho cả mùa mưa"}, {"type": "list", "items": ["Đầu mùa mưa, dọn sạch lá già, lá vàng ở gốc.", "Bón phân cân đối, không bón quá nhiều đạm làm lá mềm, dễ bệnh.", "Kê chậu cao, khơi rãnh để không đọng nước. Xem thêm [chăm cây mùa mưa miền Tây](/goc-cham-cay/cham-cay-mua-mua-mien-tay).", "Sau mưa lớn, kiểm tra lá trong tán và lá sát đất."], "ordered": false}, {"type": "p", "text": "Tra thêm ở bài [đốm lá do nấm](/benh-cay/dom-la-nam)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Thuốc trừ nấm là thuốc BVTV: đọc kỹ nhãn, đúng liều, đeo găng tay và khẩu trang khi pha, phun. Không phun lúc trời sắp mưa hoặc gió to; giữ xa trẻ nhỏ, vật nuôi, ao cá."}, {"type": "products", "title": "Cây cảnh ngoài trời mùa mưa", "slugs": ["hoa-hong", "tac-cam-thach-thai", "mai-dia-thao", "cay-so-ri"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Cercospora_Leaf_Spot_on_Eggplant.jpg/960px-Cercospora_Leaf_Spot_on_Eggplant.jpg', 3, '["dom-la-nam", "than-thu", "chay-la-vi-khuan"]'::jsonb, '["đốm lá", "nấm bệnh", "mùa mưa", "thán thư"]'::jsonb, 'Cách nhận biết bệnh đốm lá do nấm, thán thư trên cây cảnh mùa mưa; cách cắt tỉa, tưới nước, thông thoáng và dùng thuốc trừ nấm đúng cách để hạn chế lây lan.', 29),
('thoi-nhun-cu-mon-alocasia', 'bat-benh', 'Thối nhũn củ, gốc ở cây môn (Alocasia): vì sao xảy ra và cách cứu cây kịp lúc', 'Môn quan âm, môn melo đẹp nhưng rất sợ úng: gốc thâm, mềm nhũn, có mùi hôi là dấu hiệu củ đang thối. Phát hiện sớm vẫn có thể cắt bỏ phần hư, hong khô và trồng lại để cứu cây.', '[{"type": "p", "text": "Cây môn (chi Alocasia) có củ dưới gốc để trữ nước và dinh dưỡng. Củ giúp cây vượt qua lúc khô hạn, nhưng cũng khiến cây rất nhạy với úng. Khi đất ướt lâu, củ và rễ thiếu khí, vi khuẩn và nấm vào làm thối nhũn từ dưới lên."}, {"type": "h2", "text": "Dấu hiệu sớm"}, {"type": "list", "items": ["Lá vàng nhanh, nhất là lá già; lá non ra yếu, nhỏ.", "Cuống lá sát gốc thâm, sũng nước, dễ gãy gục.", "Gốc mềm khi bóp nhẹ, có mùi hôi chua.", "Đất lâu khô dù đã giảm tưới."], "ordered": false}, {"type": "p", "text": "Lưu ý: môn quan âm vào mùa khô hoặc khi lạnh có thể **ngủ nghỉ**, rụng bớt lá, chỉ còn củ. Củ ngủ thì cứng, khô sạch; củ thối thì mềm, nhũn, hôi."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Alocasia_mortfontanensis_at_Taman_Rekreasi_Taman_Sutera%2C_Kajang_20230708_170622.jpg/960px-Alocasia_mortfontanensis_at_Taman_Rekreasi_Taman_Sutera%2C_Kajang_20230708_170622.jpg", "caption": "Một loài môn lai lá mũi tên gân trắng, cùng nhóm với môn quan âm — cây đẹp nhưng củ rất sợ đất ướt lâu."}, {"type": "h2", "text": "Cứu cây từng bước"}, {"type": "list", "items": ["Lấy cây ra khỏi chậu, gỡ hết đất cũ, rửa nhẹ rễ và củ bằng nước sạch.", "Kiểm tra: rễ khỏe màu trắng hoặc kem, chắc; rễ thối nâu đen, tuột vỏ. Củ khỏe cứng; phần thối mềm, đổi màu.", "Dùng dao sạch, sắc cắt bỏ hết phần thối, cắt rộng vào phần lành một chút. Lau dao bằng cồn giữa các lần cắt.", "Để củ và rễ hong khô nơi thoáng mát, không nắng, từ nửa ngày đến 1 ngày cho vết cắt se lại.", "Trồng lại vào chậu sạch, nhỏ vừa với bộ rễ còn lại, đất rất thoát nước (nhiều đá perlite, vỏ thông). Xem [công thức trộn đất cho cây môn](/goc-cham-cay/tron-dat-trong-cay-kieng-la).", "Chỉ tưới nhẹ sau vài ngày, giữ đất hơi ẩm chứ không ướt. Đặt chỗ sáng tán xạ, ấm."], "ordered": true}, {"type": "p", "text": "Nếu chỉ còn củ không rễ, có thể đặt củ trên đất ẩm (không vùi sâu) hoặc rêu ẩm để củ ra rễ lại; cách này mất vài tuần."}, {"type": "h2", "text": "Phòng thối nhũn"}, {"type": "list", "items": ["Chậu nhỏ vừa bộ rễ, có lỗ thoát nước to. Không trồng môn trong chậu quá lớn.", "Đất tơi, thoát nhanh; không dùng đất vườn nguyên chất.", "Tưới khi mặt đất khô 2–3cm; mùa mưa, trời âm u thì giãn ra.", "Không để nước đọng ở đáy chậu bọc."], "ordered": false}, {"type": "p", "text": "Xem thêm [cách chăm môn quan âm và môn melo](/goc-cham-cay/mon-quan-am-va-mon-melo) và tra [thối nhũn vi khuẩn](/benh-cay/thoi-nhun)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Thối nhũn do vi khuẩn không chữa được bằng phun thuốc lên lá; quan trọng nhất là cắt sạch phần thối và sửa cách tưới. Nhựa cây môn gây ngứa, nên đeo găng tay khi cắt củ. Nếu dùng thuốc BVTV xử lý vết cắt, chọn loại có đăng ký và làm đúng nhãn."}, {"type": "products", "title": "Môn tại vườn", "slugs": ["mon-quan-am", "mon-melo"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Alocasia_amazonica.jpg/960px-Alocasia_amazonica.jpg', 3, '["thoi-nhun", "thoi-re"]'::jsonb, '["môn quan âm", "môn melo", "thối nhũn", "Alocasia"]'::jsonb, 'Cây môn quan âm, môn melo bị thối nhũn củ, gốc: nguyên nhân do úng nước, đất bí, vi khuẩn; cách kiểm tra, cắt phần thối, hong khô và trồng lại để cứu cây.', 36),
('benh-thuong-gap-hoa-hong', 'bat-benh', 'Hoa hồng hay bị bệnh gì? Đốm đen, phấn trắng, rệp, bọ trĩ, nhện đỏ và cách xử lý', 'Hồng là cây đẹp nhưng nhiều sâu bệnh, nhất là khi trồng chậu ở ban công thiếu nắng, mưa ẩm. Bài này điểm 6 vấn đề hay gặp nhất trên hoa hồng, cách nhận biết qua lá, nụ, đọt và việc nên làm cho từng loại.', '[{"type": "p", "text": "Một chậu [hoa hồng](/san-pham/hoa-hong) khỏe cần nắng, nước, phân và sự quan sát thường xuyên. Phần lớn bệnh trên hồng xử lý dễ nếu thấy sớm; để lâu, cây trụi lá, mất cả đợt hoa."}, {"type": "h2", "text": "1. Đốm đen"}, {"type": "p", "text": "Lá có đốm đen tròn, mép đốm lan như tua, xung quanh vàng, sau đó lá rụng từ dưới lên. Bệnh do nấm, phát mạnh khi lá ướt lâu, mùa mưa. Ngắt bỏ lá bệnh và lá rụng, tưới gốc buổi sáng, tỉa tán thoáng. Xem thêm [đốm lá do nấm](/benh-cay/dom-la-nam)."}, {"type": "h2", "text": "2. Phấn trắng"}, {"type": "p", "text": "Lớp bột trắng như rắc bột mì trên lá non, đọt, nụ; lá non xoăn, nụ không nở. Hay gặp khi ngày nóng đêm mát, ẩm, cây đặt chỗ bí gió. Cắt bỏ đọt bệnh, đưa cây ra chỗ thoáng, nhiều nắng hơn. Xem [phấn trắng](/benh-cay/phan-trang)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Diplocarpon_rosae_224338009.jpg/960px-Diplocarpon_rosae_224338009.jpg", "caption": "Lá hồng bị bệnh nấm: vết đốm lan rộng, lá vàng dần rồi rụng — cần ngắt bỏ sớm để không lây sang lá khác."}, {"type": "h2", "text": "3. Rệp muội"}, {"type": "p", "text": "Rệp nhỏ màu xanh, đen bám dày đặc ở đọt non và cuống nụ, làm đọt xoăn, nụ teo. Xịt nước mạnh cho rệp rơi, ngắt đọt bị nặng, hoặc xịt xà phòng kali theo nhãn. Xem [rệp muội](/benh-cay/rep-muoi)."}, {"type": "h2", "text": "4. Bọ trĩ"}, {"type": "p", "text": "Rất nhỏ, chui vào trong nụ và hoa, làm cánh hoa có vệt nâu, méo mó, nụ khô. Ngắt bỏ hoa, nụ bị hại; bẫy dính màu vàng/xanh giúp theo dõi mật độ. Xem [bọ trĩ](/benh-cay/bo-tri)."}, {"type": "h2", "text": "5. Nhện đỏ"}, {"type": "p", "text": "Mùa khô, lá hồng lấm tấm chấm vàng, mặt dưới có tơ. Xịt nước mặt dưới lá, tăng ẩm, và đọc kỹ cách trị ở bài [nhện đỏ mùa khô](/goc-cham-cay/nhen-do-mua-kho-cay-canh)."}, {"type": "h2", "text": "6. Sâu ăn lá"}, {"type": "p", "text": "Lá bị khuyết, thủng lỗ, có phân sâu đen. Bắt sâu bằng tay buổi sáng sớm, kiểm tra mặt dưới lá tìm trứng. Xem [sâu ăn lá](/benh-cay/sau-an-la)."}, {"type": "h2", "text": "Phòng bệnh tổng hợp cho hồng chậu"}, {"type": "list", "items": ["Đủ nắng ít nhất 6 giờ mỗi ngày — cây khỏe ít bệnh hẳn.", "Tưới gốc, tưới sáng, không tưới lên hoa, lá lúc chiều tối.", "Cắt tỉa sau mỗi đợt hoa, bỏ cành yếu, cành mọc vào trong.", "Bón phân cân đối, đừng bón quá nhiều đạm.", "Kiểm tra cây 2–3 lần mỗi tuần: lật lá, nhìn đọt, nhìn nụ."], "ordered": false}, {"type": "p", "text": "Cách trồng và cắt tỉa chi tiết có ở bài [trồng hoa hồng chậu ở ban công](/goc-cham-cay/trong-hoa-hong-chau-ban-cong)."}, {"type": "h2", "text": "Khi nào cần dùng thuốc?"}, {"type": "p", "text": "Khi bệnh lan nhanh dù đã cắt tỉa, đổi cách tưới. Chọn đúng loại: thuốc trừ nấm cho đốm đen, phấn trắng; thuốc trừ sâu cho rệp, bọ trĩ, sâu; thuốc trừ nhện cho nhện đỏ — dùng sai loại thì không hiệu quả. Chọn thuốc có đăng ký cho hoa, cây cảnh và làm đúng nhãn."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Phun thuốc BVTV cho hồng ban công: phun lúc sáng sớm hoặc chiều mát, lặng gió; đóng cửa sổ, cất đồ phơi; đeo găng tay, khẩu trang; giữ trẻ nhỏ, thú cưng tránh xa đến khi lá khô. Không dùng hoa vừa phun để ướp trà, làm thức ăn."}, {"type": "products", "title": "Hoa hồng và cây ra hoa ban công", "slugs": ["hoa-hong", "mai-dia-thao", "tulip-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Diplocarpon_rosae_55296055.jpg/960px-Diplocarpon_rosae_55296055.jpg', 3, '["dom-la-nam", "phan-trang", "rep-muoi", "bo-tri", "nhen-do", "sau-an-la"]'::jsonb, '["hoa hồng", "sâu bệnh", "đốm đen", "phấn trắng"]'::jsonb, 'Các bệnh và sâu hại thường gặp trên hoa hồng: đốm đen, phấn trắng, rệp, bọ trĩ, nhện đỏ, sâu ăn lá; cách nhận biết, phòng ngừa và xử lý an toàn cho hồng chậu.', 42),
('oc-sen-an-la-ban-cong', 'bat-benh', 'Ốc sên, sên nhớt ăn lá cây ban công mùa mưa: bắt, chặn và phòng thế nào cho an toàn', 'Sáng ra thấy lá non thủng lỗ, đọt rau bị gặm trụi, có vệt nhớt bóng trên chậu — thủ phạm là ốc sên, sên nhớt. Chúng hoạt động ban đêm và sau mưa. Có nhiều cách bắt, chặn đơn giản trước khi nghĩ tới bả diệt ốc.', '[{"type": "p", "text": "Ốc sên và sên nhớt (sên trần, không vỏ) ưa ẩm, trốn nắng ban ngày dưới đáy chậu, kẽ gạch, lớp lá mục; đêm xuống hoặc sau cơn mưa mới bò ra ăn. Chúng thích lá non, mầm rau, cánh hoa, đặc biệt là rau cải, húng quế, mai địa thảo, lá cây môn."}, {"type": "h2", "text": "Nhận biết"}, {"type": "list", "items": ["Lá có lỗ thủng không đều, ăn từ mép vào, lá non bị gặm trụi qua đêm.", "Vệt nhớt khô, bóng như bạc trên lá, chậu, nền gạch.", "Đêm hoặc sáng sớm soi đèn thấy ốc, sên đang bò."], "ordered": false}, {"type": "h2", "text": "Cách 1: Bắt bằng tay — đơn giản và hiệu quả nhất"}, {"type": "p", "text": "Đi một vòng với đèn pin khoảng 1–2 giờ sau khi trời tối, hoặc sáng sớm sau mưa. Đeo găng tay, nhặt bỏ vào xô nước muối. Làm liên tục 5–7 đêm, số ốc giảm rõ."}, {"type": "h2", "text": "Cách 2: Bẫy"}, {"type": "list", "items": ["**Bẫy trú ẩn:** đặt miếng ván, vỏ dưa hấu úp ngược, chậu úp có kê hở trên nền đất. Sáng ra lật lên bắt ốc nấp bên dưới.", "**Bẫy bia:** chôn một ly nhựa ngang mặt đất, đổ bia vào nửa ly. Ốc bò vào uống rồi chết đuối. Thay mỗi 2–3 ngày."], "ordered": false}, {"type": "h2", "text": "Cách 3: Rào chặn"}, {"type": "list", "items": ["Rắc lớp vỏ trứng nghiền thô, cát thô, tro trấu khô quanh gốc hoặc quanh chân kệ — ốc ngại bò qua lớp nhám, khô (mất tác dụng khi ướt, phải rắc lại sau mưa).", "Dán băng đồng quanh thành chậu: ốc thường tránh bò qua.", "Kê chậu lên kệ, chân kệ cách tường."], "ordered": false}, {"type": "h2", "text": "Cách 4: Dọn chỗ trú"}, {"type": "list", "items": ["Gom lá rụng, lá mục, cỏ dại quanh chậu.", "Không để chậu, thùng xốp đặt sát nền ẩm lâu ngày; kê cao để nền thoáng.", "Tưới buổi sáng thay vì chiều tối, để nền khô ráo lúc đêm."], "ordered": false}, {"type": "h2", "text": "Khi nào dùng bả diệt ốc?"}, {"type": "p", "text": "Khi ốc quá nhiều ở sân vườn lớn, bắt tay không xuể. Bả diệt ốc là thuốc BVTV, có loại rất độc với chó mèo, chim và cá. Nếu dùng, chỉ rải ít ở chỗ ốc hay đi, xa rau ăn, che kín để vật nuôi không ăn được, đọc kỹ nhãn về hoạt chất và cách dùng."}, {"type": "p", "text": "Tra thêm ở bài [ốc sên, sên nhớt ăn lá](/benh-cay/oc-sen). Nếu bạn trồng rau, xem thêm các bài trong mục [Rau sạch tại nhà](/goc-cham-cay/trong-rau-muong-thung-xop)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Nhà có chó mèo, trẻ nhỏ thì nên ưu tiên bắt tay, bẫy và rào chặn. Bả diệt ốc dạng viên nhìn giống thức ăn hạt — nhiều vật nuôi bị ngộ độc vì ăn phải. Đeo găng tay khi bắt ốc và rửa tay sạch sau đó."}, {"type": "products", "title": "Cây ban công dễ trồng", "slugs": ["mai-dia-thao", "hoa-hong", "tulip-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Eating_slug.jpg/960px-Eating_slug.jpg', 3, '["oc-sen"]'::jsonb, '["ốc sên", "sên nhớt", "ban công", "mùa mưa"]'::jsonb, 'Cách trị ốc sên, sên nhớt ăn lá cây cảnh, rau ban công mùa mưa: bắt bằng tay ban đêm, bẫy, rào chặn, dọn chỗ trú và lưu ý an toàn khi dùng bả diệt ốc.', 47),
('doc-chi-so-npk-tren-bao-phan', 'thuoc-phan-bon', 'Đọc chỉ số NPK trên bao phân: 20-20-15, 30-10-10, 10-30-10 khác nhau thế nào?', 'Ba con số trên bao phân cho biết tỉ lệ đạm, lân, kali — mỗi chất giúp cây một việc khác nhau. Hiểu ba con số này, bạn chọn đúng phân cho cây kiểng lá, cây ra hoa, cây ăn trái mà không phải đoán.', '[{"type": "p", "text": "Trên bao phân hóa học thường in ba con số như 20-20-15 hoặc 30-10-10. Đó là phần trăm khối lượng của ba chất dinh dưỡng chính: **N (đạm)**, **P (lân, tính theo P₂O₅)** và **K (kali, tính theo K₂O)**. Ví dụ bao 1kg phân 20-20-15 có khoảng 200g đạm, 200g lân và 150g kali; phần còn lại là chất mang và các thành phần khác."}, {"type": "h2", "text": "Mỗi chất làm gì cho cây?"}, {"type": "table", "rows": [["Chất", "Vai trò chính", "Thiếu thì sao"], ["N – Đạm", "Ra lá, ra đọt, lá xanh", "Lá già vàng nhạt đều, cây còi"], ["P – Lân", "Ra rễ, phân hóa mầm hoa, ra hoa", "Rễ yếu, cây chậm, ít hoa; lá có thể sẫm tím"], ["K – Kali", "Cứng cây, chịu hạn, hoa bền màu, trái chắc", "Mép lá vàng cháy, thân mềm yếu"]]}, {"type": "p", "text": "Nhớ ngắn gọn: **đạm nuôi lá, lân nuôi rễ và hoa, kali làm cây cứng cáp**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Inorganic_fertilizer_2.jpg/960px-Inorganic_fertilizer_2.jpg", "caption": "Phân hạt đổ thành đống trên đất — với cây chậu, nên rắc đều quanh mép chậu, cách gốc vài cm thay vì dồn một chỗ."}, {"type": "h2", "text": "Các loại NPK hay gặp và dùng cho cây gì"}, {"type": "h3", "text": "Đạm cao (ví dụ 30-10-10)"}, {"type": "p", "text": "Hợp với cây kiểng lá trong giai đoạn ra lá mạnh: trầu bà, vạn lộc, môn, dương xỉ. Dùng lâu dài cho cây ra hoa thì cây sẽ \"mải ra lá\", ít hoa."}, {"type": "h3", "text": "Cân đối (ví dụ 20-20-15, 16-16-8)"}, {"type": "p", "text": "Dùng được cho đa số cây, bón nuôi cây quanh năm. Đây là lựa chọn an toàn nếu bạn chỉ muốn mua một loại."}, {"type": "h3", "text": "Lân cao (ví dụ 10-30-10, 10-60-10)"}, {"type": "p", "text": "Dùng giai đoạn trước khi cây ra hoa, hoặc kích rễ cho cây mới trồng, mới thay chậu khi rễ đã ổn định. Hay dùng cho lan, hoa hồng, mai trước Tết."}, {"type": "h3", "text": "Kali cao (ví dụ 15-5-30)"}, {"type": "p", "text": "Dùng khi cây đã có nụ, đang nuôi hoa, nuôi trái: hoa bền màu hơn, trái chắc, cây cứng cáp đón mùa mưa gió."}, {"type": "h2", "text": "Chữ TE, vi lượng, Mg, Ca nghĩa là gì?"}, {"type": "p", "text": "\"+TE\" là phân có thêm **vi lượng** (sắt, kẽm, đồng, mangan, bo…). Cây cần rất ít nhưng thiếu thì có triệu chứng rõ, ví dụ thiếu sắt làm lá non vàng gân xanh. Một số bao còn ghi Mg (magie), Ca (canxi), S (lưu huỳnh) — trung lượng. Cây trồng chậu lâu năm, đất đã cạn, nên chọn phân có TE."}, {"type": "h2", "text": "Bón bao nhiêu là đủ?"}, {"type": "list", "items": ["Luôn đọc liều trên bao và **bắt đầu ít hơn**: cây trong nhà chỉ cần khoảng nửa liều ghi cho cây ngoài trời.", "Phân hạt rắc đều quanh mép chậu, cách gốc vài cm, xới nhẹ, rồi tưới. Không rắc dồn vào gốc.", "Không bón khi đất khô kiệt, cây đang héo, vừa thay chậu hoặc đang bệnh nặng.", "Bón quá liều làm [cháy rễ](/benh-cay/chay-re-do-phan): lá vàng khô mép nhanh, mặt đất có lớp muối trắng."], "ordered": false}, {"type": "p", "text": "Phân hòa tan, phân tan chậm và phân hữu cơ có cách dùng khác nhau — xem [phân tan chậm hay phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan) và [phân hữu cơ cho cây cảnh](/goc-cham-cay/phan-huu-co-cho-cay-canh)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Cất phân bón xa tầm tay trẻ nhỏ và thú cưng; nhiều loại phân hạt trông như kẹo hoặc thức ăn hạt. Đeo găng tay khi bốc phân, rửa tay sau khi bón, không đựng phân trong chai lọ đựng thức ăn."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Calcium_Ammonium_Nitrate_Pellets.png/960px-Calcium_Ammonium_Nitrate_Pellets.png', 3, '["vang-la-thieu-dam", "chay-re-do-phan"]'::jsonb, '["phân bón", "NPK", "đạm lân kali", "bón phân"]'::jsonb, 'Cách đọc chỉ số NPK trên bao phân: đạm, lân, kali là gì; phân 20-20-15, 30-10-10, 10-30-10 dùng cho cây gì; TE vi lượng và cách chọn phân.', 2),
('phan-tan-cham-va-phan-hoa-tan', 'thuoc-phan-bon', 'Phân tan chậm hay phân hòa tan: chọn loại nào cho cây cảnh trồng chậu?', 'Phân hòa tan cho cây ăn ngay, tác dụng nhanh nhưng phải bón thường xuyên; phân tan chậm rắc một lần nuôi cây vài tháng. Mỗi loại hợp với một kiểu người trồng và một kiểu cây. Đây là cách chọn và dùng cho đúng.', '[{"type": "p", "text": "Cây trồng chậu chỉ có một lượng đất nhỏ, dinh dưỡng cạn nhanh sau mỗi lần tưới. Vì vậy hầu hết cây chậu cần được bón bổ sung. Hai dạng phân phổ biến nhất cho cây cảnh là phân hòa tan (pha nước tưới) và phân tan chậm (viên bọc rắc lên mặt chậu)."}, {"type": "h2", "text": "Phân hòa tan"}, {"type": "p", "text": "Dạng bột hoặc dung dịch, pha với nước rồi tưới vào gốc hoặc phun lên lá (với loại dùng được cho lá)."}, {"type": "p", "text": "**Ưu điểm**"}, {"type": "list", "items": ["Cây hấp thu nhanh, thấy hiệu quả sau vài ngày.", "Dễ điều chỉnh: muốn giảm thì pha loãng hơn, ngưng là hết.", "Hợp khi cây đang cần \"tiếp sức\": ra đọt mạnh, sắp ra hoa."], "ordered": false}, {"type": "p", "text": "**Nhược điểm**"}, {"type": "list", "items": ["Phải bón đều đặn, thường 1–2 tuần một lần trong mùa sinh trưởng.", "Pha đặc hoặc bón khi đất khô dễ cháy rễ.", "Muối phân tích tụ nếu bón thường mà ít tưới xả."], "ordered": false}, {"type": "h2", "text": "Phân tan chậm (phân viên bọc)"}, {"type": "p", "text": "Hạt phân được bọc một lớp vỏ, mỗi lần tưới phân thấm ra từ từ. Tùy loại, một lần rắc nuôi cây khoảng 3–6 tháng (có loại lâu hơn); trời càng nóng phân ra càng nhanh."}, {"type": "p", "text": "**Ưu điểm**"}, {"type": "list", "items": ["Rắc một lần, đỡ phải nhớ lịch bón — hợp người bận rộn, cây văn phòng.", "Phân ra đều, ít nguy cơ \"sốc\" phân.", "Hợp với cây kiểng lá trong nhà, cây chậu lâu năm."], "ordered": false}, {"type": "p", "text": "**Nhược điểm**"}, {"type": "list", "items": ["Giá cao hơn tính trên cùng lượng dinh dưỡng.", "Không điều chỉnh nhanh được: rắc nhiều quá thì phải gỡ bớt hạt ra.", "Ở miền Tây nóng quanh năm, phân có thể hết sớm hơn thời gian ghi trên bao."], "ordered": false}, {"type": "h2", "text": "Nên chọn loại nào?"}, {"type": "table", "rows": [["Trường hợp", "Nên dùng"], ["Cây kiểng lá trong nhà, văn phòng", "Phân tan chậm, bổ sung phân hòa tan loãng khi cây ra lá mạnh"], ["Cây ra hoa liên tục (hoa hồng, mai địa thảo)", "Phân hòa tan định kỳ + phân hữu cơ nền"], ["Cây mới thay chậu", "Chờ 3–4 tuần rồi mới bón, ưu tiên phân tan chậm liều nhẹ"], ["Người hay quên bón", "Phân tan chậm"], ["Muốn cây ra hoa đúng dịp (Tết)", "Phân hòa tan để điều chỉnh theo từng giai đoạn"]]}, {"type": "h2", "text": "Cách dùng cho đúng"}, {"type": "list", "items": ["**Phân hòa tan:** pha đúng hoặc loãng hơn liều trên bao, tưới khi đất còn hơi ẩm (không tưới phân lúc đất khô kiệt). Mỗi 1–2 tháng tưới xả nước sạch một lần.", "**Phân tan chậm:** rắc đều quanh mặt chậu, tránh sát gốc; xới nhẹ hoặc phủ một lớp đất mỏng. Ghi ngày bón lên chậu hoặc vào điện thoại để biết khi nào bón lại.", "Cây trong nhà ít sáng, mọc chậm: giảm lượng phân so với hướng dẫn cho cây ngoài trời.", "Không dùng cả hai loại liều cao cùng lúc."], "ordered": true}, {"type": "p", "text": "Xem thêm [cách đọc chỉ số NPK](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan) để chọn đúng công thức, và [lịch bón phân cho kiểng lá trong nhà](/goc-cham-cay/bon-phan-cay-kieng-la-trong-nha)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Pha phân trong bình riêng, không dùng chung với bình nước uống. Đeo găng tay khi pha, cất phân nơi khô ráo, đậy kín, xa tầm tay trẻ nhỏ và vật nuôi."}, {"type": "products", "title": "Cây chậu lâu năm hợp phân tan chậm", "slugs": ["trau-ba-de-vuong-xanh", "phu-quy", "van-loc", "bach-ma-hoang-tu", "lan-y"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Liquid_fertilizer_Effect._Voskresensk_museum.jpg/960px-Liquid_fertilizer_Effect._Voskresensk_museum.jpg', 3, '["chay-re-do-phan"]'::jsonb, '["phân tan chậm", "phân hòa tan", "bón phân", "cây chậu"]'::jsonb, 'So sánh phân tan chậm (phân viên bọc) và phân hòa tan cho cây cảnh trồng chậu: ưu nhược điểm, cách dùng, liều lượng, bao lâu bón một lần và lưu ý tránh cháy rễ.', 9),
('phan-huu-co-cho-cay-canh', 'thuoc-phan-bon', 'Phân hữu cơ cho cây cảnh: trùn quế, phân bò hoai, phân gà — dùng sao cho không thối rễ, không hôi', 'Phân hữu cơ giúp đất tơi, giữ ẩm và nuôi cây bền, nhưng dùng sai thì đất nóng, bốc mùi, rễ thối. Bài này so sánh phân trùn quế, phân bò, phân gà, phân dơi và cách dùng an toàn cho cây chậu trong nhà lẫn ngoài vườn.', '[{"type": "p", "text": "Phân hữu cơ làm từ chất thải động vật, xác thực vật đã được ủ hoai. Ngoài dinh dưỡng, phân hữu cơ còn cải thiện đất: đất tơi xốp hơn, giữ ẩm tốt hơn, nuôi vi sinh vật có ích. Đổi lại, dinh dưỡng trong phân hữu cơ thường thấp và ra chậm hơn phân hóa học."}, {"type": "h2", "text": "Phân hoai và phân tươi — khác biệt quan trọng nhất"}, {"type": "p", "text": "**Phân tươi** (phân bò, phân gà mới lấy) khi gặp nước sẽ tiếp tục phân hủy, sinh nhiệt và khí, làm cháy rễ, đất bốc mùi, thu hút ruồi nhặng, và có thể mang mầm bệnh, hạt cỏ. **Phân hoai** đã ủ đủ thời gian: tơi, màu nâu sẫm, mùi đất, không còn nóng và không hôi."}, {"type": "p", "text": "**Chỉ dùng phân đã hoai cho cây cảnh**, nhất là cây chậu."}, {"type": "h2", "text": "So sánh các loại phổ biến"}, {"type": "table", "rows": [["Loại phân", "Đặc điểm", "Hợp với"], ["Phân trùn quế", "Tơi mịn, mùi đất, rất an toàn cho rễ, dinh dưỡng nhẹ", "Mọi cây chậu, cây trong nhà, rau, cây con"], ["Phân bò hoai", "Nhiều mùn, cải tạo đất tốt, dinh dưỡng vừa", "Trộn đất trồng, bón cây sân vườn"], ["Phân gà hoai", "Đạm và lân cao hơn phân bò, mạnh hơn", "Cây ngoài vườn, cây ăn trái; dùng ít"], ["Phân dơi", "Giàu lân, hay dùng kích hoa", "Hoa, cây ăn trái; dùng ít"], ["Phân hữu cơ vi sinh đóng bao", "Đã xử lý, có thêm vi sinh vật", "Cây chậu, sân vườn; theo liều trên bao"]]}, {"type": "h2", "text": "Dùng cho cây chậu trong nhà"}, {"type": "list", "items": ["Ưu tiên **phân trùn quế** hoặc phân hữu cơ vi sinh không mùi.", "Trộn vào đất khi trồng mới: khoảng 1 phần phân trên 9–10 phần đất trộn. Xem [công thức trộn đất kiểng lá](/goc-cham-cay/tron-dat-trong-cay-kieng-la).", "Bón thúc: rắc một lớp mỏng 1–2 muỗng canh trên mặt chậu nhỏ, 2–3 tháng một lần, xới nhẹ rồi tưới.", "Tránh phân gà, phân dơi trong nhà vì dễ có mùi và thu hút côn trùng."], "ordered": false}, {"type": "h2", "text": "Dùng cho cây sân vườn, cây ăn trái"}, {"type": "list", "items": ["Bón phân bò, phân gà hoai quanh tán cây (chỗ rìa tán là nơi nhiều rễ hút), không đổ dồn vào gốc.", "Đào rãnh nông quanh tán, rải phân, lấp đất, tưới nước.", "Mỗi năm 2–3 lần, nhất là đầu và cuối mùa mưa."], "ordered": false}, {"type": "h2", "text": "Tự ủ phân từ rác bếp"}, {"type": "p", "text": "Vỏ rau củ, bã trà, bã cà phê, lá khô có thể ủ thành phân hữu cơ. Không cho thịt, cá, dầu mỡ, sữa vào thùng ủ để tránh mùi và ruồi. Xem chi tiết ở bài [ủ phân từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}, {"type": "h2", "text": "Những lỗi hay gặp"}, {"type": "list", "items": ["Dùng phân tươi hoặc ủ chưa đủ — cây vàng lá, rễ thối.", "Bón quá dày lên mặt chậu, đất bí, không khô.", "Nghĩ phân hữu cơ \"lành\" nên bón bao nhiêu cũng được — vẫn có thể [cháy rễ](/benh-cay/chay-re-do-phan) nếu quá nhiều.", "Chỉ dùng phân hữu cơ cho cây ra hoa liên tục: có thể thiếu kali, cần bổ sung thêm."], "ordered": true}, {"type": "note", "title": "Lưu ý an toàn", "text": "Phân chuồng có thể mang vi khuẩn gây bệnh. Đeo găng tay khi bón, rửa tay kỹ sau đó; với rau ăn sống, chỉ dùng phân đã hoai hoàn toàn và không bón sát ngày thu hoạch."}, {"type": "products", "title": "Cây sân vườn hợp phân hữu cơ", "slugs": ["tac-cam-thach-thai", "cay-so-ri", "hoa-hong", "mai-dia-thao"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Worms_just_added.jpg/960px-Worms_just_added.jpg', 3, '["chay-re-do-phan", "thoi-re"]'::jsonb, '["phân hữu cơ", "phân trùn quế", "phân bò", "cải tạo đất"]'::jsonb, 'Cách dùng phân hữu cơ cho cây cảnh: phân trùn quế, phân bò, phân gà hoai; phân biệt phân hoai và phân tươi, liều cho cây chậu, tránh thối rễ.', 16),
('bon-phan-cay-kieng-la-trong-nha', 'thuoc-phan-bon', 'Bón phân cho cây kiểng lá trong nhà: bao lâu một lần, liều bao nhiêu để lá xanh mà không cháy rễ', 'Cây kiểng lá trong nhà mọc chậm hơn cây ngoài trời nên cần ít phân hơn nhiều người nghĩ. Bón đúng lúc, đúng liều giúp lá xanh bóng, ra đọt đều; bón dư là nguyên nhân hay gặp của cháy mép lá, vàng lá.', '[{"type": "p", "text": "Cây trong nhà nhận ít ánh sáng nên quang hợp ít, mọc chậm, nhu cầu dinh dưỡng thấp. Nếu bón theo liều dành cho cây ngoài trời, phần phân cây không dùng hết sẽ tích lại trong đất và làm hại rễ. Nguyên tắc chung: **ít mà đều tốt hơn nhiều mà dồn**."}, {"type": "h2", "text": "Bón khi nào?"}, {"type": "list", "items": ["**Bón khi cây đang ra lá mới**: thấy đọt non, lá mới nhú là lúc cây cần dinh dưỡng.", "**Giảm hoặc ngưng khi cây đứng**: cây không ra lá mới nhiều tuần, trời âm u kéo dài, cây đặt chỗ rất tối.", "**Không bón** khi cây vừa mua về (1–2 tuần đầu), vừa thay chậu (3–4 tuần), đang bệnh nặng, thối rễ, hoặc đất đang khô kiệt."], "ordered": false}, {"type": "h2", "text": "Lịch gợi ý"}, {"type": "table", "rows": [["Loại phân", "Liều", "Bao lâu một lần"], ["Phân hòa tan NPK cân đối hoặc đạm cao", "Nửa liều ghi trên bao", "2–4 tuần, chỉ khi cây đang ra lá"], ["Phân tan chậm", "Theo bao, cây trong nhà dùng mức thấp", "3–6 tháng"], ["Phân trùn quế", "1–2 muỗng canh / chậu 15–20cm", "2–3 tháng"]]}, {"type": "p", "text": "Chọn một cách chính rồi bổ sung nhẹ, đừng dùng cả ba ở liều đầy đủ cùng lúc. Chi tiết từng loại phân xem ở [phân tan chậm hay phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan)."}, {"type": "h2", "text": "Cây nào cần ít, cây nào cần nhiều hơn?"}, {"type": "list", "items": ["**Cần ít phân:** [lưỡi hổ](/san-pham/luoi-ho), [ngọc bích](/san-pham/ngoc-bich), cây mọng nước — 2–3 lần mỗi năm là đủ.", "**Trung bình:** [phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc), [ngọc ngân](/san-pham/ngoc-ngan), [bạch mã](/san-pham/bach-ma-hoang-tu) — nhóm Aglaonema mọc chậm, bón loãng.", "**Cần đều hơn:** [trầu bà đế vương](/san-pham/trau-ba-de-vuong-xanh), [lan ý](/san-pham/lan-y), môn, dương xỉ — mọc nhanh khi đủ sáng.", "**Nhạy cảm với muối phân:** đuôi công (Calathea) — chỉ dùng phân rất loãng, tưới xả định kỳ."], "ordered": false}, {"type": "h2", "text": "Dấu hiệu bón thừa"}, {"type": "list", "items": ["Mép lá, đầu lá khô nâu dù tưới đều.", "Lớp muối trắng trên mặt đất, quanh lỗ thoát nước, thành chậu đất nung.", "Lá vàng, rụng, rễ nâu khô."], "ordered": false}, {"type": "p", "text": "Xử lý: ngưng bón, tưới xả nhiều nước sạch cho chảy qua đáy chậu vài lần, cạo bỏ lớp đất mặt có muối. Nặng thì thay đất. Xem thêm [cháy rễ do bón phân quá liều](/benh-cay/chay-re-do-phan)."}, {"type": "h2", "text": "Dấu hiệu thiếu phân"}, {"type": "list", "items": ["Lá già vàng nhạt đều, cây còi dù đủ sáng, đủ nước.", "Lá mới nhỏ, nhạt màu hơn lá cũ.", "Cây trồng 1–2 năm chưa thay đất, chưa bón."], "ordered": false}, {"type": "p", "text": "Xem [vàng lá do thiếu đạm](/benh-cay/vang-la-thieu-dam)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Trong nhà có trẻ nhỏ, thú cưng: rắc phân xong nên xới vùi hoặc phủ một lớp đất mỏng, cất bao phân kín. Pha phân trong bình riêng có ghi chữ, không dùng chai nước uống."}, {"type": "products", "title": "Kiểng lá trong nhà", "slugs": ["trau-ba-de-vuong-xanh", "phu-quy", "van-loc", "ngoc-ngan", "lan-y", "luoi-ho"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Chlorophytum_comosum_-_Botanischer_Garten_-_Heidelberg%2C_Germany_-_DSC01199.jpg/960px-Chlorophytum_comosum_-_Botanischer_Garten_-_Heidelberg%2C_Germany_-_DSC01199.jpg', 3, '["vang-la-thieu-dam", "chay-re-do-phan"]'::jsonb, '["bón phân", "kiểng lá", "cây trong nhà", "cây văn phòng"]'::jsonb, 'Lịch bón phân cho cây kiểng lá trong nhà, văn phòng: loại phân nên dùng, liều lượng, bao lâu bón một lần, khi nào không nên bón và dấu hiệu bón thừa, bón thiếu.', 23),
('doc-nhan-thuoc-bvtv-truoc-khi-dung', 'thuoc-phan-bon', 'Đọc nhãn thuốc BVTV trước khi dùng: 7 thông tin phải xem để dùng đúng và an toàn', 'Nhãn chai thuốc bảo vệ thực vật chứa gần như mọi điều bạn cần biết: thuốc trị gì, pha bao nhiêu, phun lúc nào, bao lâu mới được thu hoạch và cần đề phòng gì. Bài này hướng dẫn đọc nhãn từng phần cho người trồng cây tại nhà.', '[{"type": "p", "text": "Thuốc bảo vệ thực vật (BVTV) là công cụ cần thiết khi sâu bệnh bùng phát, nhưng dùng sai có thể hại người, vật nuôi và chính cây trồng. Trước khi mở nắp chai, hãy dành 5 phút đọc nhãn. Ở Việt Nam, nhãn thuốc phải ghi bằng tiếng Việt các thông tin chính dưới đây."}, {"type": "h2", "text": "1. Tên thương phẩm và tên hoạt chất"}, {"type": "p", "text": "Tên thương phẩm là tên hãng đặt, mỗi hãng một tên. Quan trọng hơn là **tên hoạt chất** (chất có tác dụng) và **hàm lượng**. Hai chai tên khác nhau có thể cùng một hoạt chất; ngược lại, cùng tên quen có thể khác hàm lượng. Khi hỏi tư vấn, hãy đọc tên hoạt chất."}, {"type": "h2", "text": "2. Dạng thuốc"}, {"type": "p", "text": "Ký hiệu sau hàm lượng cho biết dạng thuốc, ảnh hưởng tới cách pha:"}, {"type": "table", "rows": [["Ký hiệu", "Dạng", "Ghi chú khi pha"], ["EC", "Nhũ dầu", "Pha vào nước thành dung dịch trắng đục"], ["SC", "Huyền phù đậm đặc", "Lắc kỹ chai trước khi đong"], ["WP", "Bột thấm nước", "Hòa bột với ít nước trước rồi mới thêm nước"], ["WG / WDG", "Hạt phân tán trong nước", "Ít bụi hơn dạng bột"], ["SL", "Dung dịch", "Tan hoàn toàn trong nước"], ["GR", "Hạt", "Rải trực tiếp, không pha"]]}, {"type": "h2", "text": "3. Số đăng ký"}, {"type": "p", "text": "Thuốc được phép sử dụng phải có trong danh mục thuốc BVTV được phép sử dụng tại Việt Nam. Không mua thuốc không nhãn, nhãn nước ngoài không có tiếng Việt, hoặc thuốc sang chiết vào chai không rõ nguồn gốc."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Field_Sprayer_Display_on_Ground_20121006.jpg/960px-Field_Sprayer_Display_on_Ground_20121006.jpg", "caption": "Bình phun thuốc đeo vai — trước khi pha, đọc kỹ nhãn về liều lượng, đối tượng phòng trừ và thời gian cách ly."}, {"type": "h2", "text": "4. Công dụng: trị gì, trên cây gì"}, {"type": "p", "text": "Nhãn ghi rõ thuốc dùng cho cây trồng nào, trị đối tượng nào (ví dụ rệp sáp, nhện đỏ, đốm lá). Chỉ dùng đúng đối tượng ghi trên nhãn. Thuốc trừ sâu không trị được nấm; thuốc trừ nấm không trị được rệp; nhện đỏ thường cần thuốc trừ nhện riêng."}, {"type": "h2", "text": "5. Liều lượng và cách pha"}, {"type": "p", "text": "Thường ghi theo dạng \"ml (hoặc g) thuốc / bình 8 lít\" hoặc \"/ 1 lít nước\". Đong bằng dụng cụ có vạch, không ước chừng. **Không tự tăng liều** vì nghĩ sẽ hiệu quả hơn — dễ cháy lá và nguy hiểm cho người phun. Pha vừa đủ dùng một lần."}, {"type": "h2", "text": "6. Thời gian cách ly"}, {"type": "p", "text": "Là số ngày tối thiểu từ lần phun cuối đến khi được thu hoạch (rau, trái). Với rau sạch tại nhà, đây là con số phải tôn trọng tuyệt đối. Với cây cảnh trong nhà, nên để cây ngoài trời đến khi lá khô hẳn và hết mùi mới đem vào."}, {"type": "h2", "text": "7. Cảnh báo độc và sơ cứu"}, {"type": "p", "text": "Nhãn có hình cảnh báo, từ cảnh báo và mục hướng dẫn sơ cứu, cách bảo quản, cách xử lý bao bì. Đọc trước khi dùng để biết cần đồ bảo hộ gì và phải làm gì nếu bị dính thuốc."}, {"type": "h2", "text": "Thói quen an toàn khi dùng thuốc tại nhà"}, {"type": "list", "items": ["Mua lượng nhỏ, đủ dùng; cất trong chai gốc có nhãn, nơi khóa được, xa thức ăn.", "Đeo găng tay, khẩu trang, kính, áo dài tay khi pha và phun.", "Phun lúc sáng sớm hoặc chiều mát, lặng gió; không phun gần bể cá, ao, chuồng vật nuôi.", "Không ăn uống, hút thuốc khi đang phun; tắm rửa, giặt đồ sau khi phun.", "Bao bì rỗng không dùng lại để đựng gì khác."], "ordered": false}, {"type": "p", "text": "Đọc thêm [Hướng dẫn dùng thuốc BVTV an toàn](/chinh-sach/thuoc-bvtv-an-toan) và thử các cách không dùng thuốc trước, như ở bài [trị rệp sáp](/goc-cham-cay/tri-rep-sap-cay-kieng-la)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Khi bị ngộ độc thuốc BVTV (chóng mặt, buồn nôn, khó thở sau khi phun hoặc nuốt phải), đưa người bệnh ra chỗ thoáng, cởi bỏ quần áo dính thuốc, gọi cấp cứu 115 và mang theo nhãn hoặc chai thuốc để bác sĩ biết hoạt chất."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/ENVIRONMENTAL_PROTECTION_AGENCY_INSPECTOR_CHECKS_A_LABEL_ON_A_PESTICIDE_CONTAINER_DURING_A_ROUTINE_INSPECTION_AT_THE..._-_NARA_-_555238.jpg/960px-ENVIRONMENTAL_PROTECTION_AGENCY_INSPECTOR_CHECKS_A_LABEL_ON_A_PESTICIDE_CONTAINER_DURING_A_ROUTINE_INSPECTION_AT_THE..._-_NARA_-_555238.jpg', 4, '[]'::jsonb, '["thuốc BVTV", "đọc nhãn thuốc", "an toàn", "thời gian cách ly"]'::jsonb, 'Hướng dẫn đọc nhãn thuốc BVTV: hoạt chất, hàm lượng, dạng thuốc EC WP SC, số đăng ký, liều pha, thời gian cách ly, cảnh báo và sơ cứu.', 30),
('trichoderma-che-pham-sinh-hoc', 'thuoc-phan-bon', 'Chế phẩm Trichoderma: nấm có ích giúp phòng thối rễ — dùng thế nào cho đúng?', 'Trichoderma là một nhóm nấm có ích sống trong đất, cạnh tranh và kìm hãm nhiều loại nấm gây thối rễ, thối gốc. Chế phẩm Trichoderma được bà con miền Tây dùng nhiều để ủ phân và trộn đất. Đây là cách dùng hợp với cây cảnh.', '[{"type": "p", "text": "Trong đất có rất nhiều loại nấm. Có loại gây bệnh cho cây như nấm gây thối rễ, thối gốc; nhưng cũng có loại có ích. Trichoderma là nhóm nấm có ích được nghiên cứu và sử dụng rộng rãi: chúng phát triển nhanh quanh rễ, cạnh tranh chỗ sống và chất dinh dưỡng, đồng thời tiết ra chất kìm hãm một số nấm gây bệnh."}, {"type": "h2", "text": "Trichoderma giúp được gì?"}, {"type": "list", "items": ["**Phòng** thối rễ, thối gốc do nấm, nhất là mùa mưa đất ẩm lâu.", "**Tăng tốc ủ phân hữu cơ**: phân chuồng, rơm rạ, lá cây hoai nhanh hơn, ít mùi hơn.", "Giúp đất \"sống\" hơn khi dùng cùng phân hữu cơ."], "ordered": false}, {"type": "p", "text": "Điều cần hiểu đúng: Trichoderma là biện pháp **phòng và hỗ trợ**, phát huy tác dụng khi dùng sớm và đều. Cây đã thối rễ nặng thì vẫn phải cắt bỏ phần thối, thay đất, sửa cách tưới — xem [thối rễ](/benh-cay/thoi-re)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Conidial_mass_of_Trichoderma_spp._under_400x_magnification.jpg/960px-Conidial_mass_of_Trichoderma_spp._under_400x_magnification.jpg", "caption": "Trichoderma là nấm có ích sống trong đất — dùng phòng bệnh và ủ phân, không phải \"thuốc chữa\" cho cây đã thối nặng."}, {"type": "h2", "text": "Cách dùng phổ biến"}, {"type": "h3", "text": "1. Ủ phân chuồng, phân hữu cơ"}, {"type": "p", "text": "Trộn chế phẩm Trichoderma theo liều trên bao vào đống phân chuồng, rơm, lá. Giữ ẩm (nắm chặt thấy rỉ nước nhẹ), che kín, đảo trộn định kỳ. Phân ủ có Trichoderma vừa hoai nhanh vừa mang sẵn nấm có ích vào đất."}, {"type": "h3", "text": "2. Trộn vào đất khi trồng, thay chậu"}, {"type": "p", "text": "Trộn một lượng nhỏ chế phẩm vào đất trồng hoặc giá thể, theo hướng dẫn trên bao. Hợp với cây dễ thối rễ như môn, lan ý, trầu bà, cây kiểng lá mùa mưa."}, {"type": "h3", "text": "3. Pha nước tưới gốc"}, {"type": "p", "text": "Một số chế phẩm dạng bột mịn hoặc dạng lỏng có thể pha nước tưới vào gốc, định kỳ trong mùa mưa. Làm theo liều trên bao."}, {"type": "h2", "text": "Những điều nên tránh"}, {"type": "list", "items": ["**Không trộn chung với thuốc trừ nấm hóa học**: thuốc trừ nấm cũng diệt luôn Trichoderma. Nếu đã dùng thuốc trừ nấm, chờ một thời gian (theo hướng dẫn của chế phẩm) mới dùng Trichoderma.", "Không trộn với vôi bột hoặc phân hóa học nồng độ cao cùng lúc.", "Không để chế phẩm nơi nắng nóng; đọc hạn dùng — nấm là sinh vật sống, quá hạn hoặc bảo quản sai sẽ mất tác dụng.", "Đất quá khô thì nấm không phát triển; giữ đất ẩm vừa sau khi dùng."], "ordered": true}, {"type": "h2", "text": "Chọn chế phẩm thế nào?"}, {"type": "p", "text": "Chọn sản phẩm có nhãn tiếng Việt, ghi rõ thành phần, mật độ bào tử, hạn dùng và số đăng ký (là thuốc BVTV sinh học hoặc phân bón vi sinh). Mua lượng vừa dùng, bảo quản nơi khô mát."}, {"type": "p", "text": "Nếu bạn tự ủ phân tại nhà, xem thêm [ủ phân hữu cơ từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Chế phẩm sinh học an toàn hơn thuốc hóa học nhưng vẫn là bụi bào tử: đeo khẩu trang, găng tay khi trộn, tránh hít bụi, rửa tay sau khi dùng; người có bệnh hô hấp, dị ứng nên nhờ người khác làm."}, {"type": "products", "title": "Cây dễ thối rễ mùa mưa", "slugs": ["mon-quan-am", "mon-melo", "lan-y", "trau-ba-de-vuong-xanh"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Trichoderma_viride_187018154.jpg/960px-Trichoderma_viride_187018154.jpg', 3, '["thoi-re", "thoi-goc-nam-hach"]'::jsonb, '["Trichoderma", "chế phẩm sinh học", "thối rễ", "ủ phân"]'::jsonb, 'Trichoderma là gì, giúp gì cho cây cảnh; cách dùng chế phẩm Trichoderma ủ phân, trộn đất, tưới gốc phòng thối rễ và những điều cần tránh.', 37),
('phan-bon-la-va-phan-bon-goc', 'thuoc-phan-bon', 'Phân bón lá và phân bón gốc: khi nào nên phun, khi nào nên bón gốc cho cây cảnh?', 'Phun phân lên lá cho hiệu quả nhanh trong vài ngày, bón gốc nuôi cây bền lâu. Hai cách không thay thế nhau mà bổ sung cho nhau. Bài này giúp bạn chọn đúng lúc, pha đúng liều và tránh làm cháy lá.', '[{"type": "p", "text": "Rễ là nơi cây hút phần lớn nước và dinh dưỡng. Nhưng lá cũng có thể hấp thu một lượng nhỏ chất dinh dưỡng qua bề mặt, nhất là các chất vi lượng. Đó là cơ sở của phân bón lá."}, {"type": "h2", "text": "Bón gốc — nền tảng nuôi cây"}, {"type": "p", "text": "Bón gốc (phân hạt, phân tan chậm, phân hữu cơ, phân hòa tan tưới gốc) cung cấp phần lớn dinh dưỡng cây cần. Với cây cảnh trồng chậu, bón gốc đúng cách là đủ cho hầu hết thời gian. Xem [lịch bón phân cho kiểng lá trong nhà](/goc-cham-cay/bon-phan-cay-kieng-la-trong-nha)."}, {"type": "h2", "text": "Phân bón lá — \"tiếp sức\" khi cần"}, {"type": "p", "text": "Phân bón lá thường được dùng khi:"}, {"type": "list", "items": ["Cây thiếu vi lượng rõ (ví dụ lá non vàng gân xanh do [thiếu sắt](/benh-cay/vang-la-thieu-sat)) — phun giúp lá xanh lại nhanh hơn chờ rễ hút.", "Rễ đang yếu, vừa phục hồi sau úng, sau thay chậu — cây hút qua rễ kém.", "Giai đoạn cây cần nhanh như trước khi ra hoa, nuôi hoa."], "ordered": false}, {"type": "p", "text": "Phân bón lá **không thay được bón gốc**: lượng cây hấp thu qua lá ít, tác dụng ngắn."}, {"type": "h2", "text": "Cách phun cho đúng"}, {"type": "list", "items": ["Chọn loại ghi rõ là **phân bón lá**, pha đúng hoặc loãng hơn liều trên bao. Phun đặc dễ cháy lá.", "Phun vào sáng sớm hoặc chiều mát. Nắng gắt làm nước bốc hơi nhanh, phân đọng lại thành vệt cháy.", "Phun đều cả **mặt dưới lá** — nhiều cây có nhiều lỗ khí ở mặt dưới.", "Không phun khi trời sắp mưa (trôi hết) hoặc gió to.", "Khoảng cách giữa các lần phun theo hướng dẫn trên bao, thường 7–15 ngày."], "ordered": true}, {"type": "h2", "text": "Cây nào nên hạn chế phun lên lá?"}, {"type": "list", "items": ["Cây lá có lông tơ, lá mỏng nhạy cảm như đuôi công, dương xỉ: dễ để lại vết, cháy lá.", "Cây trong nhà, ít gió: lá ướt lâu dễ nấm bệnh. Nếu phun, nên đem ra chỗ thoáng.", "Hoa đang nở: phân đọng trên cánh hoa làm hoa thâm.", "Cây mọng nước (lưỡi hổ, ngọc bích): lá có lớp sáp, hấp thu kém, ít lợi."], "ordered": false}, {"type": "h2", "text": "So sánh nhanh"}, {"type": "table", "rows": [["Tiêu chí", "Bón gốc", "Phân bón lá"], ["Lượng dinh dưỡng", "Nhiều, là nguồn chính", "Ít, bổ sung"], ["Tốc độ", "Chậm hơn", "Nhanh, vài ngày"], ["Thời gian tác dụng", "Lâu", "Ngắn"], ["Hợp khi", "Nuôi cây thường xuyên", "Thiếu vi lượng, rễ yếu, cần tiếp sức"], ["Nguy cơ", "Cháy rễ nếu quá liều", "Cháy lá nếu pha đặc, phun nắng"]]}, {"type": "p", "text": "Chọn công thức phân theo nhu cầu của cây ở bài [đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Bình phun phân bón lá nên dùng riêng, không dùng chung với bình đã phun thuốc BVTV (hoặc phải rửa thật kỹ nhiều lần). Đeo găng tay, khẩu trang khi pha và phun; không phun gần thức ăn, vật nuôi."}, {"type": "products", "title": "Cây ra hoa, cây ăn trái hợp bón lá", "slugs": ["hoa-hong", "tac-cam-thach-thai", "mai-dia-thao", "cay-so-ri"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/369D8C305A.jpg', 3, '["vang-la-thieu-sat", "chay-re-do-phan"]'::jsonb, '["phân bón lá", "bón gốc", "bón phân", "cây cảnh"]'::jsonb, 'Phân bón lá và phân bón gốc khác nhau thế nào, khi nào nên phun phân bón lá cho cây cảnh, cách pha, giờ phun và lưu ý tránh cháy lá.', 43),
('trong-rau-cai-thung-xop', 'rau-sach', 'Trồng rau cải thùng xốp ở ban công: khoảng 30 ngày có rau ăn, không cần thuốc', 'Cải ngọt, cải xanh là loại rau dễ trồng nhất cho người mới: hạt nảy mầm nhanh, ít bệnh, trồng được trong thùng xốp ở ban công, sân thượng. Đây là cách làm từ chọn thùng, trộn đất, gieo hạt đến thu hoạch.', '[{"type": "p", "text": "Rau cải (cải ngọt, cải xanh, cải bẹ) mọc nhanh, cần ít công chăm và có thể thu hoạch sau khoảng 25–35 ngày tùy giống. Chỉ cần một chỗ có nắng 4–6 giờ mỗi ngày và vài thùng xốp, gia đình bạn đã có rau sạch ăn đều."}, {"type": "h2", "text": "Chuẩn bị thùng"}, {"type": "list", "items": ["Thùng xốp loại đựng trái cây, sâu khoảng 20–25cm là đủ cho rau cải.", "Đục 6–8 lỗ thoát nước ở đáy (đường kính khoảng 1cm), có thể đục thêm lỗ ở thành gần đáy.", "Kê thùng lên gạch hoặc kệ cho đáy thoáng, nước thoát được."], "ordered": false}, {"type": "h2", "text": "Trộn đất"}, {"type": "p", "text": "Đất trồng rau cần tơi, giàu mùn, thoát nước tốt. Công thức đơn giản theo thể tích:"}, {"type": "list", "items": ["5 phần đất thịt hoặc đất phù sa đã phơi khô, đập nhỏ", "3 phần phân hữu cơ hoai (phân trùn quế hoặc phân bò hoai)", "2 phần tro trấu hoặc xơ dừa đã xả chát"], "ordered": false}, {"type": "p", "text": "Trộn đều, cho vào thùng cách miệng 3–5cm, tưới ẩm và để 2–3 ngày trước khi gieo. Xem thêm [phân hữu cơ dùng thế nào cho đúng](/goc-cham-cay/phan-huu-co-cho-cay-canh)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Pak-ch.jpg/960px-Pak-ch.jpg", "caption": "Cây cải đủ nắng, đất tơi mọc nhanh, bẹ trắng mập, lá xanh mướt."}, {"type": "h2", "text": "Gieo hạt"}, {"type": "list", "items": ["Ngâm hạt trong nước ấm (2 sôi 3 lạnh) khoảng 2–3 giờ, vớt ra để ráo.", "Trộn hạt với ít cát khô hoặc tro cho dễ rải đều.", "Rải đều trên mặt đất, phủ một lớp đất mỏng hoặc tro trấu khoảng 0,5cm.", "Tưới phun sương nhẹ để không trôi hạt. Che lưới hoặc lá chuối 1–2 ngày cho hạt nảy mầm."], "ordered": true}, {"type": "p", "text": "Hạt thường mọc sau 2–4 ngày."}, {"type": "h2", "text": "Tỉa cây"}, {"type": "p", "text": "Khi cây có 2–3 lá thật, tỉa bớt cây mọc dày, cây yếu, để mỗi cây cách nhau khoảng 7–10cm. Cây tỉa ra làm rau mầm ăn luôn được. Rau mọc quá dày sẽ còi, dễ bệnh."}, {"type": "h2", "text": "Tưới nước và bón phân"}, {"type": "list", "items": ["Tưới 1–2 lần mỗi ngày tùy nắng, tốt nhất sáng sớm và chiều mát. Tưới nhẹ, đều, không để đất khô nứt hay úng.", "Sau khi tỉa khoảng 1 tuần, tưới thêm nước phân trùn quế ngâm loãng hoặc rắc một lớp mỏng phân trùn quế, 7–10 ngày một lần.", "Không cần thuốc: rau cải mọc nhanh, thu hoạch sớm trước khi sâu bệnh kịp phát nhiều."], "ordered": false}, {"type": "h2", "text": "Sâu, ốc thì sao?"}, {"type": "list", "items": ["**Sâu ăn lá, bọ nhảy:** kiểm tra mặt dưới lá buổi sáng, bắt bằng tay. Che lưới mùng mỏng phủ thùng rau từ khi gieo giúp hạn chế bướm đẻ trứng. Xem [sâu ăn lá](/benh-cay/sau-an-la).", "**Ốc sên:** mùa mưa ốc bò lên ăn rau non ban đêm. Xem [cách bắt, chặn ốc sên an toàn](/goc-cham-cay/oc-sen-an-la-ban-cong)."], "ordered": false}, {"type": "h2", "text": "Thu hoạch"}, {"type": "p", "text": "Sau khoảng 25–35 ngày, cây cao 20–25cm là ăn được. Có thể nhổ cả cây, hoặc cắt lá ngoài để cây ra tiếp vài lứa. Sau 2–3 lứa, xới đất, bổ sung phân hữu cơ rồi gieo đợt mới. Trồng gối 2–3 thùng cách nhau 10 ngày để lúc nào cũng có rau."}, {"type": "note", "title": "Lưu ý", "text": "Tưới rau ăn bằng nước sạch. Nếu thật sự phải dùng thuốc trị sâu cho rau, chỉ dùng thuốc có đăng ký cho rau, làm đúng liều và chờ đủ thời gian cách ly ghi trên nhãn mới được hái ăn."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Fruits_and_Vegetables_%2820210202-BO-NRCS-045%29.jpg/960px-Fruits_and_Vegetables_%2820210202-BO-NRCS-045%29.jpg', 3, '["sau-an-la", "oc-sen"]'::jsonb, '["rau cải", "thùng xốp", "rau sạch", "ban công"]'::jsonb, 'Cách trồng rau cải thùng xốp ở ban công: chuẩn bị thùng, đất, gieo hạt, tỉa cây, tưới, bón phân hữu cơ và thu hoạch sau khoảng 30 ngày.', 3),
('trong-hanh-la-tai-nha', 'rau-sach', 'Trồng hành lá tại nhà từ gốc hành mua chợ: 2–3 tuần là có hành cắt', 'Đừng vứt phần gốc trắng có rễ của bó hành lá mua ở chợ. Chỉ cần một chậu đất nhỏ hoặc một ly nước, gốc hành sẽ mọc lại lá mới để bạn cắt dùng nhiều lần. Đây là cách trồng hành lá dễ nhất cho người ở chung cư.', '[{"type": "p", "text": "Hành lá (hành hoa) là rau gia vị nhà nào cũng cần mỗi ngày. Trồng hành từ gốc mua ở chợ vừa tiết kiệm vừa có hành tươi để cắt ngay khi nấu. Hành mọc nhanh, ít bệnh, hợp với ban công nhỏ, bậu cửa sổ có nắng."}, {"type": "h2", "text": "Chọn gốc hành"}, {"type": "list", "items": ["Chọn bó hành tươi, gốc trắng chắc, còn rễ.", "Cắt lấy phần gốc trắng dài khoảng 4–5cm tính từ rễ lên. Phần lá xanh dùng nấu ăn.", "Bỏ những gốc bị dập, thối, có mùi."], "ordered": false}, {"type": "h2", "text": "Cách 1: Trồng trong ly nước — nhanh nhất"}, {"type": "list", "items": ["Đặt các gốc hành đứng trong ly hoặc hũ thủy tinh, đổ nước ngập phần rễ, **không ngập hết thân trắng**.", "Để chỗ sáng gần cửa sổ.", "Thay nước 1–2 ngày một lần để nước không hôi.", "Sau vài ngày lá mới mọc lên, khoảng 1–2 tuần là cắt được."], "ordered": true}, {"type": "p", "text": "Cách này chỉ cho vài lứa vì nước không có dinh dưỡng. Muốn trồng lâu, nên chuyển ra đất."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Beijing_scallions.jpg/960px-Beijing_scallions.jpg", "caption": "Bó hành lá còn nguyên gốc trắng và rễ — phần gốc dài 4–5cm này trồng lại được."}, {"type": "h2", "text": "Cách 2: Trồng trong chậu đất — cắt được nhiều lứa"}, {"type": "list", "items": ["Chậu hoặc thùng xốp sâu 15–20cm, có lỗ thoát nước.", "Đất tơi trộn phân hữu cơ hoai (như đất trồng rau cải ở bài [rau cải thùng xốp](/goc-cham-cay/trong-rau-cai-thung-xop)).", "Cắm gốc hành sâu khoảng 3–4cm, cách nhau 5–7cm, mỗi hốc 2–3 gốc.", "Tưới ẩm, để chỗ râm 2–3 ngày rồi đưa ra chỗ có nắng 4–6 giờ."], "ordered": true}, {"type": "h2", "text": "Chăm sóc"}, {"type": "list", "items": ["Tưới khi mặt đất khô, khoảng 1 lần mỗi ngày mùa nắng. Hành sợ úng: đất sũng nước làm gốc thối nhũn.", "Sau mỗi lần cắt, rắc một ít phân trùn quế hoặc tưới nước phân loãng để cây ra lá mới khỏe.", "Hành ra hoa (ngồng tròn trên ngọn) thì ngắt bỏ để cây tập trung ra lá."], "ordered": false}, {"type": "h2", "text": "Thu hoạch đúng cách"}, {"type": "p", "text": "Cắt lá cách gốc khoảng 3–4cm, đừng cắt sát gốc. Mỗi lứa cách nhau khoảng 2–3 tuần. Sau 3–4 lứa, cây yếu dần thì nhổ lên, thay gốc mới."}, {"type": "h2", "text": "Lỗi hay gặp"}, {"type": "list", "items": ["Ngâm ngập cả gốc trong nước — gốc thối, nước hôi.", "Đặt nơi quá tối — lá mọc dài, mảnh, nhạt màu, ít mùi.", "Cắt sát gốc — cây ra lá lại rất chậm hoặc chết.", "Đất bí, tưới nhiều — thối rễ, vàng lá. Xem thêm [thối rễ](/benh-cay/thoi-re)."], "ordered": true}, {"type": "note", "title": "Mẹo nhỏ", "text": "Cùng cách này có thể trồng lại gốc sả, gốc rau ngò gai, củ tỏi mọc mầm. Mỗi loại một chậu riêng để dễ tưới theo nhu cầu."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Allium_fistulosum_-_Copenhagen_Botanical_Garden_-_DSC07943.JPG/960px-Allium_fistulosum_-_Copenhagen_Botanical_Garden_-_DSC07943.JPG', 2, '["thoi-re"]'::jsonb, '["hành lá", "rau sạch", "trồng rau chung cư", "rau gia vị"]'::jsonb, 'Cách trồng hành lá tại nhà từ gốc hành mua chợ bằng chậu đất hoặc ly nước: chọn gốc, cắt, trồng, tưới, bón phân và cắt hành nhiều lứa trên ban công, cửa sổ.', 10),
('trong-rau-thom-ban-cong', 'rau-sach', 'Trồng rau thơm ở ban công: húng quế, tía tô, rau răm, ngò — loại nào dễ, chăm ra sao', 'Vài chậu rau thơm ở ban công đủ cho bữa cơm gia đình: hái vài cọng húng, lá tía tô, rau răm ngay trước khi ăn. Mỗi loại rau thơm có nhu cầu nắng, nước khác nhau — trồng đúng thì cây sống lâu, ra lá liên tục.', '[{"type": "p", "text": "Rau thơm là nhóm rau rất hợp trồng tại nhà: dùng mỗi lần một ít, hái xong lại ra lá mới. Nhiều loại có thể trồng từ cành mua ở chợ, không cần hạt giống."}, {"type": "h2", "text": "Bảng tóm tắt"}, {"type": "table", "rows": [["Loại rau", "Nắng", "Nước", "Cách trồng dễ nhất"], ["Húng quế", "4–6 giờ nắng", "Đất ẩm vừa, không úng", "Gieo hạt hoặc giâm ngọn"], ["Tía tô", "Nắng nhẹ đến nắng vừa", "Ẩm đều", "Gieo hạt hoặc giâm cành"], ["Rau răm", "Chịu bóng, nắng nhẹ", "Thích ẩm nhiều", "Giâm cành mua chợ"], ["Húng lủi (bạc hà)", "Nắng nhẹ", "Ẩm đều", "Giâm cành, mọc lan nhanh"], ["Ngò rí (rau mùi)", "Nắng nhẹ, thích mát", "Ẩm vừa", "Gieo hạt, mùa mát dễ hơn"]]}, {"type": "h2", "text": "Húng quế"}, {"type": "p", "text": "Húng quế ưa nắng, sợ úng. Gieo hạt trên đất tơi hoặc giâm ngọn dài 10cm vào ly nước cho ra rễ rồi trồng. **Ngắt ngọn** khi cây cao 15–20cm để cây đâm nhiều nhánh. Thấy bông hoa nhú ra thì ngắt ngay — cây ra hoa sẽ ít lá, lá cứng và đắng hơn."}, {"type": "h2", "text": "Tía tô"}, {"type": "p", "text": "Tía tô mọc khỏe, lá tím mặt dưới. Gieo hạt hoặc giâm cành. Ngắt ngọn để cây bụi; cuối mùa cây ra hoa, giữ lại vài cây cho hạt rụng tự mọc lứa sau."}, {"type": "h2", "text": "Rau răm"}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Laksa-bush.jpg/960px-Laksa-bush.jpg", "caption": "Rau răm lá thuôn dài, có vệt sẫm giữa lá — thích ẩm, giâm cành mua chợ rất dễ ra rễ."}, {"type": "p", "text": "Rau răm rất dễ: mua một bó ở chợ, cắm phần thân có đốt vào ly nước vài ngày là ra rễ. Rau răm thích ẩm, có thể đặt chậu trong khay nước nông, chịu được chỗ ít nắng hơn húng quế. Cây bò lan nên chọn chậu rộng."}, {"type": "h2", "text": "Húng lủi (bạc hà)"}, {"type": "p", "text": "Mọc lan rất mạnh bằng thân ngầm, nên trồng chậu riêng để không lấn rau khác. Cắt bớt thường xuyên để cây ra ngọn non."}, {"type": "h2", "text": "Ngò rí"}, {"type": "p", "text": "Ngò rí thích trời mát; mùa nắng nóng cây nhanh trổ ngồng. Ở miền Tây nên gieo vào những tháng mát cuối năm, đặt chỗ nắng nhẹ buổi sáng. Gieo thưa, tỉa cây cách nhau vài cm."}, {"type": "h2", "text": "Chăm chung cho rau thơm"}, {"type": "list", "items": ["Chậu sâu 15–20cm, đất tơi trộn phân trùn quế, có lỗ thoát nước.", "Tưới sáng sớm, kiểm tra đất mỗi ngày — chậu nhỏ khô rất nhanh dưới nắng.", "Hái thường xuyên là cách chăm tốt nhất: cây được kích thích ra nhánh mới.", "Bón phân trùn quế 2–3 tuần một lần, lượng ít."], "ordered": false}, {"type": "h2", "text": "Sâu bệnh"}, {"type": "p", "text": "Rau thơm có mùi nên ít sâu hơn rau cải, nhưng vẫn có [rệp muội](/benh-cay/rep-muoi) bám ngọn non và [sâu ăn lá](/benh-cay/sau-an-la). Bắt tay, xịt nước mạnh, ngắt bỏ ngọn bị nặng. Rau ăn sống nên hạn chế tối đa thuốc."}, {"type": "note", "title": "Lưu ý", "text": "Rau thơm thường ăn sống, nên tưới bằng nước sạch và rửa kỹ trước khi ăn. Không trồng rau ăn ở chỗ gần cây cảnh vừa được phun thuốc."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/BNOT7LSS8O.jpg', 3, '["rep-muoi", "sau-an-la"]'::jsonb, '["rau thơm", "húng quế", "tía tô", "rau răm", "ban công"]'::jsonb, 'Cách trồng rau thơm ở ban công chung cư: húng quế, tía tô, rau răm, húng lủi, ngò rí; chọn chậu, nắng, tưới nước, ngắt ngọn, ngắt hoa để rau ra lá liên tục.', 17),
('trong-ca-chua-chau', 'rau-sach', 'Trồng cà chua trong chậu ở sân thượng: chọn giống, làm giàn, tưới đều để trái không nứt', 'Cà chua trồng chậu cho trái chín đỏ ngay trên sân thượng nếu đủ nắng và chậu đủ lớn. Bài này hướng dẫn từ chọn giống, chậu, đất, làm giàn, tỉa nhánh đến cách tưới để trái không nứt, không thối đít.', '[{"type": "p", "text": "Cà chua là cây ăn trái dễ trồng nhất trong chậu, nhất là cà chua bi (cherry). Cây cần nhiều nắng, chậu đủ lớn và tưới đều. Đổi lại, sau khoảng 2–3 tháng bạn sẽ có trái chín hái dần."}, {"type": "h2", "text": "Chọn giống"}, {"type": "list", "items": ["**Cà chua bi:** trái nhỏ, cây sai trái, chịu nóng khá, hợp chậu nhất.", "**Cà chua thường:** trái to hơn, cần chậu lớn và giàn chắc hơn."], "ordered": false}, {"type": "p", "text": "Ưu tiên hạt giống có nhãn mác rõ ràng, ghi chịu nóng hoặc phù hợp trồng ở miền Nam."}, {"type": "h2", "text": "Chậu, đất, vị trí"}, {"type": "list", "items": ["Chậu hoặc thùng chứa **từ 20 lít trở lên** cho một cây (thùng xốp lớn, bao trồng cây, chậu nhựa sâu 30cm).", "Đất tơi giàu mùn: đất thịt + phân hữu cơ hoai + tro trấu, có thể thêm một ít vôi bột trộn trước vài ngày để bổ sung canxi.", "**Nắng 6–8 giờ mỗi ngày.** Thiếu nắng cây vươn dài, ít hoa, rụng hoa."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Cherry_tomatoes_-_Arlington%2C_MA_-_DSC03760.jpg/960px-Cherry_tomatoes_-_Arlington%2C_MA_-_DSC03760.jpg", "caption": "Chùm cà chua bi trên cây có cọc đỡ — trái chín dần, chuyển từ xanh sang vàng, cam rồi đỏ."}, {"type": "h2", "text": "Gieo và trồng"}, {"type": "list", "items": ["Gieo hạt vào khay ươm hoặc ly nhỏ, giữ ẩm. Khoảng 2–3 tuần cây có 4–5 lá thật thì đem trồng.", "Trồng sâu hơn bầu một chút (thân cà chua ra rễ ở phần vùi), tưới ẩm, che nắng 2–3 ngày đầu.", "Cắm cọc ngay khi trồng để không đâm vào rễ sau này."], "ordered": true}, {"type": "h2", "text": "Làm giàn và tỉa nhánh"}, {"type": "list", "items": ["Buộc thân vào cọc bằng dây mềm, buộc lỏng hình số 8.", "Tỉa bớt **chồi nách** (chồi mọc ở giữa thân và cành lá) để cây tập trung nuôi trái, giữ 1–2 thân chính.", "Tỉa lá già sát đất để gốc thoáng, giảm nấm bệnh."], "ordered": false}, {"type": "h2", "text": "Tưới và bón phân"}, {"type": "list", "items": ["Tưới **đều đặn mỗi ngày**, sáng sớm, tưới vào gốc. Đất lúc khô lúc ướt làm trái nứt và gây **thối đít trái** (đáy trái thâm đen, lõm) — liên quan đến thiếu canxi do hút nước không đều.", "Phủ gốc bằng rơm, lá khô để giữ ẩm.", "Bón phân hữu cơ định kỳ; khi cây ra hoa, đậu trái thì bổ sung phân có kali cao hơn. Xem [đọc chỉ số NPK](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."], "ordered": false}, {"type": "h2", "text": "Bệnh hay gặp"}, {"type": "list", "items": ["**Héo xanh:** cây đang xanh bỗng héo rũ nhanh, không hồi lại — do vi khuẩn trong đất. Nhổ bỏ cây, không trồng cà chua lại trên đất đó. Xem [héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan).", "**Đốm lá:** lá dưới có đốm nâu, vàng rụng — tỉa lá bệnh, tránh tưới lá.", "**Xoăn lá do virus:** lá non xoăn, vàng, cây lùn — thường do bọ phấn truyền; nhổ bỏ cây bệnh. Xem [vàng xoăn lá](/benh-cay/xoan-la-virus)."], "ordered": false}, {"type": "h2", "text": "Thu hoạch"}, {"type": "p", "text": "Hái khi trái chuyển màu (hồng, đỏ) — có thể hái lúc trái mới ửng rồi để chín trong nhà để tránh chim, chuột. Cây cà chua bi cho trái kéo dài nhiều tuần nếu được chăm đều."}, {"type": "note", "title": "Lưu ý", "text": "Cà chua ăn tươi nên ưu tiên biện pháp không dùng thuốc. Nếu bắt buộc phải dùng thuốc BVTV, chọn thuốc có đăng ký cho cà chua, đúng liều và chờ đủ thời gian cách ly trước khi hái."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Tomato_plants_%28black_cherry_and_others%29.jpg/960px-Tomato_plants_%28black_cherry_and_others%29.jpg', 3, '["heo-xanh-vi-khuan", "dom-la-nam", "xoan-la-virus"]'::jsonb, '["cà chua", "rau sạch", "sân thượng", "trồng chậu"]'::jsonb, 'Cách trồng cà chua chậu ở sân thượng: chọn giống cà chua bi, chậu bao nhiêu lít, đất, làm giàn, tỉa nhánh, tưới đều và xử lý thối đít trái.', 24),
('trong-ot-chau', 'rau-sach', 'Trồng ớt chậu tại nhà: cây sai trái quanh năm, vừa làm gia vị vừa làm cảnh', 'Một chậu ớt ở ban công vừa cho trái để nêm nếm, vừa đẹp mắt khi trái chín đỏ. Ớt chịu nóng tốt, hợp khí hậu miền Tây. Bài này hướng dẫn gieo hạt, trồng chậu, tưới, bón và xử lý khi cây rụng hoa, xoăn lá.', '[{"type": "p", "text": "Cây ớt sống được vài năm nếu chăm tốt, cho trái nhiều đợt. Ớt chỉ thiên trái nhỏ, cay, cây gọn hợp chậu; ớt sừng trái to cần chậu lớn hơn. Đây là cây hợp với người mới trồng rau."}, {"type": "h2", "text": "Gieo hạt"}, {"type": "list", "items": ["Lấy hạt từ trái ớt chín đỏ, già trên cây khỏe, hoặc mua hạt giống.", "Phơi hạt nơi râm cho khô, ngâm nước ấm vài giờ trước khi gieo.", "Gieo vào khay hoặc ly nhỏ, phủ đất mỏng, giữ ẩm. Hạt mọc sau khoảng 7–10 ngày.", "Cây cao 10–15cm, có 4–6 lá thật thì trồng ra chậu."], "ordered": false}, {"type": "h2", "text": "Chậu và đất"}, {"type": "list", "items": ["Chậu đường kính 25–30cm (khoảng 10–15 lít) cho một cây ớt chỉ thiên.", "Đất tơi, trộn phân hữu cơ hoai, thoát nước tốt; lót đáy chậu bằng xơ dừa hoặc sỏi nhẹ.", "Nắng ít nhất 6 giờ mỗi ngày."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Capsicum_frutescens_Capsicum_annuum_Pj_DSC_1076.jpg/960px-Capsicum_frutescens_Capsicum_annuum_Pj_DSC_1076.jpg", "caption": "Cây ớt con trồng trong bầu, chậu nhỏ — khi có 4–6 lá thật thì chuyển ra chậu lớn hơn."}, {"type": "h2", "text": "Tưới và bón"}, {"type": "list", "items": ["Tưới đều mỗi ngày mùa nắng, giữ đất ẩm vừa; không để úng.", "Ngắt bỏ vài lứa hoa đầu tiên khi cây còn nhỏ để cây lớn khỏe rồi mới cho trái.", "Bón phân hữu cơ mỗi tháng; khi cây ra hoa nhiều, bổ sung phân có lân, kali cao hơn đạm."], "ordered": false}, {"type": "h2", "text": "Vì sao ớt rụng hoa, không đậu trái?"}, {"type": "list", "items": ["**Thiếu nắng** — đưa cây ra chỗ nắng hơn.", "**Tưới thất thường** — đất lúc khô lúc úng.", "**Bón quá nhiều đạm** — cây tốt lá, ít trái.", "**Nắng nóng gay gắt kéo dài** hoặc mưa dầm — hoa rụng, chờ thời tiết dịu.", "Thiếu côn trùng thụ phấn ở ban công cao tầng — lắc nhẹ cành khi hoa nở buổi sáng để giúp thụ phấn."], "ordered": true}, {"type": "h2", "text": "Sâu bệnh hay gặp"}, {"type": "list", "items": ["**Bọ trĩ, rệp:** lá non xoăn, quăn mép, ngọn chùn. Xịt nước mạnh, ngắt ngọn bị nặng. Xem [bọ trĩ](/benh-cay/bo-tri), [rệp muội](/benh-cay/rep-muoi).", "**Xoăn lá do virus:** lá xoăn vàng, cây lùn, không hồi — nhổ bỏ để không lây. Xem [vàng xoăn lá](/benh-cay/xoan-la-virus).", "**Thán thư trên trái:** vết lõm, thâm, có vòng trên trái ớt, hay gặp mùa mưa. Hái bỏ trái bệnh, tránh tưới lên trái. Xem [thán thư](/benh-cay/than-thu)."], "ordered": false}, {"type": "h2", "text": "Thu hoạch"}, {"type": "p", "text": "Hái trái khi đã chuyển màu đỏ (hoặc vàng tùy giống). Hái thường xuyên giúp cây ra hoa tiếp. Ớt dư có thể phơi khô hoặc ngâm giấm."}, {"type": "note", "title": "Lưu ý", "text": "Hạt và nhựa ớt cay có thể làm rát da, rát mắt. Đeo găng tay khi tách hạt, không dụi mắt; để chậu ớt xa tầm với của trẻ nhỏ. Nếu phải dùng thuốc BVTV cho ớt, chọn thuốc có đăng ký và chờ đủ thời gian cách ly trước khi hái."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Capsicum_frutescens_%28Siling_labuyo%29.jpg/960px-Capsicum_frutescens_%28Siling_labuyo%29.jpg', 3, '["than-thu", "xoan-la-virus", "bo-tri", "rep-muoi"]'::jsonb, '["ớt", "rau sạch", "trồng chậu", "ban công"]'::jsonb, 'Cách trồng ớt chậu tại nhà, ban công: gieo hạt ớt, chọn chậu, đất, nắng, tưới nước, bón phân, ngắt hoa đầu, xử lý rụng hoa, xoăn lá, thán thư trên trái ớt.', 31),
('u-phan-huu-co-tu-rac-bep', 'rau-sach', 'Ủ phân hữu cơ từ rác bếp tại nhà: không hôi, không ruồi, 2–3 tháng có phân bón rau', 'Vỏ rau củ, bã trà, bã cà phê, lá khô mỗi ngày có thể biến thành phân bón cho chậu rau, chậu cây. Ủ đúng cách thì không bốc mùi và không có ruồi. Đây là cách ủ đơn giản bằng thùng xốp hoặc thùng nhựa có nắp.', '[{"type": "p", "text": "Khoảng một nửa rác sinh hoạt hằng ngày là rác hữu cơ: vỏ rau củ, trái cây, bã trà, lá khô. Thay vì bỏ đi, bạn có thể ủ thành phân bón cho rau và cây cảnh. Phân ủ xong tơi, màu nâu đen, mùi đất ẩm."}, {"type": "h2", "text": "Rác nào ủ được, rác nào không"}, {"type": "table", "rows": [["Nên cho vào", "Không nên cho vào"], ["Vỏ rau, củ, trái cây", "Thịt, cá, xương"], ["Bã trà, bã cà phê", "Dầu mỡ, đồ chiên"], ["Vỏ trứng đập nhỏ", "Sữa, phô mai"], ["Lá khô, cỏ khô, giấy báo xé nhỏ, bìa các-tông", "Phân chó mèo"], ["Rơm, mùn cưa, tro trấu", "Cây bệnh, cỏ đã có hạt"]]}, {"type": "p", "text": "Thịt, cá, dầu mỡ là nguồn mùi hôi và ruồi nhặng chính."}, {"type": "h2", "text": "Bí quyết: cân bằng \"rác xanh\" và \"rác nâu\""}, {"type": "list", "items": ["**Rác xanh** (ướt, nhiều đạm): vỏ rau củ, bã trà, cỏ tươi.", "**Rác nâu** (khô, nhiều xơ): lá khô, giấy, bìa, rơm, mùn cưa, tro trấu."], "ordered": false}, {"type": "p", "text": "Tỉ lệ dễ nhớ: **mỗi lớp rác xanh phủ lên một lớp rác nâu dày gấp đôi**. Thiếu rác nâu thì đống ủ nhão, hôi; thiếu rác xanh thì ủ rất chậm."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Compost_pile.JPG/960px-Compost_pile.JPG", "caption": "Đống ủ có rác xanh và rác nâu xen lớp — giữ ẩm vừa, đảo trộn định kỳ để hoai đều, không bốc mùi."}, {"type": "h2", "text": "Cách ủ bằng thùng"}, {"type": "list", "items": ["Thùng nhựa hoặc thùng xốp có nắp, khoan vài lỗ nhỏ quanh thành để thoáng khí, đục lỗ đáy để nước rỉ ra (đặt khay hứng).", "Lót đáy một lớp lá khô hoặc giấy vụn dày 5–10cm.", "Mỗi lần có rác bếp: băm nhỏ, cho vào, phủ ngay một lớp rác nâu lên trên.", "Thỉnh thoảng rắc một nắm đất vườn hoặc phân trùn quế, hoặc chế phẩm vi sinh ủ phân (như [Trichoderma](/goc-cham-cay/trichoderma-che-pham-sinh-hoc)) để phân hủy nhanh hơn.", "Mỗi 1–2 tuần đảo trộn để có không khí.", "Giữ độ ẩm như miếng bọt biển vắt ráo: khô quá thì tưới ít nước, ướt quá thì thêm rác nâu."], "ordered": true}, {"type": "h2", "text": "Bao lâu thì dùng được?"}, {"type": "p", "text": "Khoảng 2–3 tháng (nhanh hơn khi trời nóng, băm nhỏ, đảo đều). Phân đạt khi: không còn nhận ra rác ban đầu, tơi, màu nâu đen, mùi đất, không nóng. Có thể sàng lọc phần chưa hoai cho vào thùng ủ tiếp."}, {"type": "h2", "text": "Xử lý sự cố"}, {"type": "list", "items": ["**Hôi, nhão:** quá nhiều rác xanh, quá ướt — thêm lá khô, giấy, đảo trộn.", "**Có ruồi giấm:** phủ kín rác xanh bằng rác nâu, đậy nắp, không bỏ trái cây chín nẫu nguyên miếng.", "**Không hoai:** quá khô hoặc thiếu rác xanh — thêm nước, thêm vỏ rau."], "ordered": false}, {"type": "h2", "text": "Dùng phân ủ"}, {"type": "list", "items": ["Trộn 2–3 phần phân ủ vào 10 phần đất khi trồng rau như ở bài [rau cải thùng xốp](/goc-cham-cay/trong-rau-cai-thung-xop).", "Rắc lớp mỏng lên mặt chậu cây cảnh, xới nhẹ. Xem thêm [phân hữu cơ cho cây cảnh](/goc-cham-cay/phan-huu-co-cho-cay-canh).", "Nước rỉ từ thùng ủ pha loãng 10–20 lần để tưới gốc."], "ordered": false}, {"type": "note", "title": "Lưu ý", "text": "Chỉ dùng phân ủ đã hoai hoàn toàn cho rau ăn lá. Đeo găng tay khi đảo trộn và rửa tay sau đó; đặt thùng ủ xa nơi nấu ăn."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Four_compost_bins.jpg/960px-Four_compost_bins.jpg', 3, '[]'::jsonb, '["ủ phân", "phân hữu cơ", "rác bếp", "rau sạch"]'::jsonb, 'Cách ủ phân hữu cơ từ rác bếp tại nhà: rác nào ủ được, tỉ lệ rác xanh và rác nâu, đảo trộn, giữ ẩm, khử mùi và dùng phân cho rau, cây cảnh.', 38),
('trong-rau-mam-tai-nha', 'rau-sach', 'Trồng rau mầm tại nhà: 5–7 ngày có rau, chỉ cần khay, giấy ẩm và hạt giống', 'Rau mầm là cách nhanh nhất để có rau xanh tại nhà, kể cả khi bạn không có ban công nắng. Chỉ cần khay nhựa, giá thể sạch và hạt giống rau mầm, khoảng một tuần là cắt ăn. Đây là cách làm từng bước và lưu ý vệ sinh.', '[{"type": "p", "text": "Rau mầm là cây rau non mới mọc 1–2 lá mầm, cắt ăn khi cao vài cm. Rau mầm cải, củ cải trắng, rau muống mầm, đậu Hà Lan mầm đều dễ làm. Rau mầm không cần nhiều nắng, hợp chung cư, phòng trọ."}, {"type": "h2", "text": "Chuẩn bị"}, {"type": "list", "items": ["**Hạt giống rau mầm:** mua loại ghi rõ dùng làm rau mầm, không qua xử lý thuốc. Không dùng hạt giống trồng rau thường (thường đã được xử lý thuốc).", "**Khay:** khay nhựa có lỗ thoát nước, kèm khay hứng bên dưới.", "**Giá thể:** xơ dừa đã xả chát và hấp/phơi sạch, hoặc giấy ăn, khăn giấy dày, vải mùng sạch.", "**Bình phun sương.**"], "ordered": false}, {"type": "h2", "text": "Các bước"}, {"type": "list", "items": ["**Ngâm hạt** trong nước ấm khoảng 4–8 giờ (hạt to như đậu Hà Lan ngâm lâu hơn), đãi bỏ hạt lép nổi lên.", "**Rải hạt** đều, dày vừa phải trên giá thể đã làm ẩm, hạt không chồng lên nhau.", "**Ủ tối 2–3 ngày:** đậy khay bằng khay khác hoặc tấm bìa, để nơi thoáng. Phun ẩm 2 lần mỗi ngày.", "**Đưa ra sáng:** khi mầm cao 2–3cm, mở nắp, đặt nơi có ánh sáng tán xạ (gần cửa sổ). Mầm sẽ chuyển xanh.", "**Tưới nhẹ** từ khay hứng hoặc phun sương, không để đọng nước trên mầm.", "**Thu hoạch** sau khoảng 5–7 ngày (tùy loại), khi mầm cao 6–10cm, cắt sát giá thể."], "ordered": true}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Liping_Kou_observes_microgreens.jpg/960px-Liping_Kou_observes_microgreens.jpg", "caption": "Các khay rau mầm gieo dày trên giá thể — mỗi khay một loại hạt để thu hoạch cùng lúc."}, {"type": "h2", "text": "Chống nấm mốc"}, {"type": "p", "text": "Nấm mốc là vấn đề thường gặp nhất khi làm rau mầm:"}, {"type": "list", "items": ["Rửa sạch khay, dụng cụ trước mỗi lần gieo.", "Không rải hạt quá dày; không để giá thể sũng nước.", "Để nơi thoáng gió, không đậy kín quá lâu sau khi hạt đã nảy mầm.", "Thấy mảng mốc trắng như bông (khác với lông rễ trắng mịn quanh rễ mầm) hoặc mùi chua thì bỏ cả khay."], "ordered": false}, {"type": "h2", "text": "Mẹo cho từng loại"}, {"type": "table", "rows": [["Loại", "Ngâm hạt", "Thu hoạch sau"], ["Cải mầm, củ cải mầm", "4–6 giờ", "5–7 ngày"], ["Rau muống mầm", "8–12 giờ", "6–8 ngày"], ["Đậu Hà Lan mầm", "8–12 giờ", "8–12 ngày"]]}, {"type": "h2", "text": "Ăn rau mầm an toàn"}, {"type": "p", "text": "Rửa sạch rau mầm trước khi ăn. Người có sức đề kháng yếu, phụ nữ mang thai, trẻ nhỏ nên ăn rau mầm đã chần hoặc nấu chín. Muốn trồng rau ăn lá lâu dài hơn, xem [trồng rau cải thùng xốp](/goc-cham-cay/trong-rau-cai-thung-xop) và [trồng rau muống thùng xốp](/goc-cham-cay/trong-rau-muong-thung-xop)."}, {"type": "note", "title": "Lưu ý", "text": "Chỉ dùng hạt giống ghi rõ để làm rau mầm. Hạt giống dùng để gieo trồng thông thường có thể đã được bao thuốc xử lý hạt, không được ăn mầm."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Red_Cabbage_Microgreens.jpg/960px-Red_Cabbage_Microgreens.jpg', 3, '[]'::jsonb, '["rau mầm", "rau sạch", "trồng rau chung cư"]'::jsonb, 'Cách trồng rau mầm tại nhà bằng khay: chọn hạt, ngâm hạt, giá thể, ủ tối, đưa ra sáng, tưới phun sương, thu hoạch sau 5–7 ngày, chống mốc.', 44),
('cay-phong-thuy-ban-lam-viec', 'phong-thuy', 'Đặt cây phong thủy trên bàn làm việc: chọn cây, vị trí và những điều nên tránh', 'Một chậu cây trên bàn làm việc được nhiều người chọn vì ý nghĩa may mắn, thăng tiến. Bài này tổng hợp các quan niệm dân gian phổ biến về chọn cây, đặt cây trên bàn làm việc — và những điều thực tế để cây luôn xanh tốt.', '[{"type": "p", "text": "Trong quan niệm dân gian, cây xanh tượng trưng cho sự sinh sôi, phát triển. Một chậu cây khỏe mạnh trên bàn làm việc được xem là mang lại sinh khí, may mắn trong công việc. Dù tin hay không, một chậu cây xanh tốt chắc chắn giúp góc làm việc dễ chịu hơn."}, {"type": "p", "text": "Bài viết dưới đây tổng hợp các quan niệm phổ biến, mang tính tham khảo."}, {"type": "h2", "text": "Chọn cây theo ý nghĩa"}, {"type": "table", "rows": [["Cây", "Ý nghĩa thường được gán"], ["[Phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc)", "Tài lộc, sung túc — tên gọi đã nói lên mong muốn"], ["[Ngọc ngân](/san-pham/ngoc-ngan)", "May mắn, bình an, hay dùng làm quà"], ["[Lưỡi hổ](/san-pham/luoi-ho)", "Mạnh mẽ, xua điều xấu, bền bỉ"], ["[Trầu bà đế vương](/san-pham/trau-ba-de-vuong-xanh)", "Vững vàng, thăng tiến"], ["[Lan chi](/san-pham/lan-chi)", "Tươi mới, thuận lợi, gắn kết"]]}, {"type": "h2", "text": "Chọn cây theo mệnh"}, {"type": "p", "text": "Dân gian thường chọn màu lá, màu chậu hợp với mệnh của người ngồi bàn. Ví dụ người mệnh Mộc, Hỏa hợp cây lá xanh; mệnh Hỏa, Thổ hợp lá đỏ hồng như phú quý; mệnh Kim, Thủy hợp lá xanh pha trắng bạc như ngọc ngân. Xem bảng chi tiết ở bài [chọn cây hợp mệnh Kim, Mộc, Thủy, Hỏa, Thổ](/goc-cham-cay/chon-cay-theo-menh-ngu-hanh)."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/NY0SW7KPUR.jpg", "caption": "Một chậu cây nhỏ gọn đặt ở góc bàn, không che màn hình và không vướng tay khi làm việc."}, {"type": "h2", "text": "Đặt cây ở đâu trên bàn?"}, {"type": "p", "text": "Theo một số quan niệm phong thủy phổ biến:"}, {"type": "list", "items": ["**Bên trái** bàn (khi ngồi nhìn ra) thường được khuyên đặt vật cao, cây xanh tốt; bên phải để thấp, gọn.", "Không đặt cây ngay giữa bàn hay chắn trước mặt — về thực tế cũng làm vướng tầm nhìn, vướng tay.", "Cây đặt gần nguồn sáng (cửa sổ) là tốt nhất — cây khỏe thì \"sinh khí\" mới vượng."], "ordered": false}, {"type": "h2", "text": "Số lượng chậu"}, {"type": "p", "text": "Thường chỉ cần một chậu chính trên bàn làm việc cá nhân. Nhiều người kiêng đặt số chậu kết thúc bằng số 4. Về thực tế, bàn làm việc nhỏ chỉ nên có 1–2 chậu để gọn gàng, dễ tưới."}, {"type": "h2", "text": "Những điều nên tránh"}, {"type": "list", "items": ["**Cây héo úa, lá vàng úa để lâu** — dân gian cho là mang khí xấu; thực tế cũng không đẹp. Cắt lá hỏng, chăm lại hoặc thay cây.", "**Cây có gai nhọn hướng về phía người ngồi** — nhiều người kiêng xương rồng trên bàn làm việc.", "**Hoa giả, cây giả bám bụi** — dân gian coi là thiếu sinh khí.", "**Cây quá to** so với bàn — chật chội, dễ đổ."], "ordered": true}, {"type": "h2", "text": "Chăm thế nào để cây luôn xanh?"}, {"type": "p", "text": "Đa số bàn làm việc thiếu sáng, có máy lạnh, cuối tuần không ai tưới. Chọn cây chịu bóng, chịu khô như lưỡi hổ, phú quý, vạn lộc. Đọc thêm [8 cây để bàn làm việc dễ chăm](/goc-cham-cay/cay-de-ban-lam-viec-de-cham) và [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."}, {"type": "note", "title": "Góc nhìn thực tế", "text": "Phong thủy là quan niệm dân gian, mỗi trường phái nói một khác. Điều chắc chắn nhất là một chậu cây khỏe, sạch sẽ giúp góc làm việc dễ chịu hơn — hãy chọn cây hợp với ánh sáng và thời gian chăm của bạn trước, rồi mới chọn theo ý nghĩa."}, {"type": "products", "title": "Cây phong thủy để bàn", "slugs": ["phu-quy", "van-loc", "ngoc-ngan", "luoi-ho", "lan-chi"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/CEXWHUSWIC.jpg', 3, '[]'::jsonb, '["phong thủy", "bàn làm việc", "cây văn phòng", "cây hợp mệnh"]'::jsonb, 'Cách chọn và đặt cây phong thủy trên bàn làm việc theo quan niệm dân gian: cây hợp mệnh, vị trí, số lượng, cây nên tránh và cách chăm.', 6),
('cay-phong-thuy-cua-hang-quay-thu-ngan', 'phong-thuy', 'Cây phong thủy cho cửa hàng, quầy thu ngân: chọn cây "tài lộc" vừa đẹp vừa dễ sống', 'Chủ cửa hàng, quán ăn, tiệm tóc thường đặt một chậu cây ở quầy thu ngân hoặc cửa ra vào với mong muốn buôn may bán đắt. Đây là những cây được chuộng nhất, ý nghĩa dân gian của từng cây và cách chọn cây hợp với điều kiện cửa hàng.', '[{"type": "p", "text": "Trong buôn bán, người Việt có nhiều tục lệ cầu may: mâm thần tài, cây tài lộc ở quầy, chậu cây hai bên cửa. Một chậu cây xanh tốt ở quầy thu ngân vừa mang ý nghĩa cầu may, vừa làm cửa hàng trông tươi tắn, sạch sẽ hơn trong mắt khách."}, {"type": "h2", "text": "Cây được chuộng ở quầy thu ngân"}, {"type": "list", "items": ["**[Phú quý](/san-pham/phu-quy):** lá đỏ hồng viền xanh, tên gọi gắn với giàu sang. Lá dày, chịu được ánh đèn cửa hàng.", "**[Vạn lộc](/san-pham/van-loc):** lá đỏ hồng nổi bật, ý nghĩa \"lộc đến muôn phần\".", "**[Kim cương hồng](/san-pham/kim-cuong-hong), [cung điện vàng](/san-pham/cung-dien-vang):** tên gọi sang trọng, hợp chậu đẹp ở quầy.", "**[Giữ tiền](/san-pham/giu-tien), [như ý](/san-pham/nhu-y):** tên gọi gắn với mong muốn giữ được tiền, mọi việc như ý.", "**[Lưỡi hổ](/san-pham/luoi-ho):** bền bỉ, chịu khô — hợp cửa hàng ít người chăm."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/2095Ornamental_plants_in_the_Philippines_26.jpg/960px-2095Ornamental_plants_in_the_Philippines_26.jpg", "caption": "Cây lá đỏ hồng nhóm Aglaonema bày ở vườn — loại cây hay được chọn đặt ở quầy thu ngân, cửa hàng."}, {"type": "h2", "text": "Đặt ở đâu?"}, {"type": "list", "items": ["**Quầy thu ngân:** một chậu cỡ vừa, đặt ở góc quầy, không che máy tính tiền và không vướng khách.", "**Hai bên cửa ra vào:** một cặp chậu cùng loại, cùng cỡ. Cửa ngoài trời nắng thì chọn cây chịu nắng; cửa trong trung tâm thương mại chọn cây chịu bóng.", "**Góc trong cùng cửa hàng:** dân gian gọi là \"góc tài lộc\" (góc chéo với cửa vào). Thực tế đây thường là góc tối — chọn cây chịu bóng như [bạch mã](/san-pham/bach-ma-hoang-tu), [vạn niên thanh](/san-pham/van-nien-thanh)."], "ordered": false}, {"type": "h2", "text": "Cây nên tránh trong cửa hàng"}, {"type": "list", "items": ["Cây héo, lá vàng úa, chậu bám bụi — dễ tạo cảm giác ế ẩm, thiếu chăm chút.", "Cây có nhựa gây ngứa đặt nơi trẻ nhỏ hay chạm vào (quán ăn gia đình, tiệm đồ chơi) — đặt cao hoặc chọn cây an toàn hơn. Xem [cây an toàn cho trẻ nhỏ, thú cưng](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung).", "Cây quá to chắn lối đi, che bảng hiệu."], "ordered": true}, {"type": "h2", "text": "Điều kiện cửa hàng và cách chăm"}, {"type": "table", "rows": [["Điều kiện", "Gợi ý"], ["Có cửa kính, nắng chiều", "Kéo rèm, đặt cây lùi vào trong 1–2m"], ["Chỉ có đèn, đóng cửa ban đêm", "Chọn cây chịu bóng; mỗi tháng đem ra chỗ sáng vài ngày"], ["Máy lạnh chạy cả ngày", "Không đặt cây trước luồng gió; tưới khi đất khô mặt"], ["Ít người chăm, nghỉ Tết dài", "Chọn cây chịu khô; xem [mẹo giữ cây khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang)"]]}, {"type": "h2", "text": "Mua làm quà khai trương"}, {"type": "p", "text": "Phú quý, vạn lộc, trầu bà đế vương, kim cương là những cây hay được chọn làm quà khai trương. Xem thêm [chọn cây làm quà khai trương, tân gia](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia). Cửa hàng cần số lượng lớn để trưng bày hoặc làm quà tặng khách có thể gửi danh sách ở trang [báo giá sỉ](/bao-gia-si)."}, {"type": "note", "title": "Góc nhìn thực tế", "text": "Cây không thay được hàng tốt và phục vụ tốt, nhưng một chậu cây xanh, sạch sẽ ở quầy là điểm cộng nhỏ cho ấn tượng của khách. Chọn cây hợp ánh sáng cửa hàng để cây luôn đẹp."}, {"type": "products", "title": "Cây tài lộc cho cửa hàng", "slugs": ["phu-quy", "van-loc", "kim-cuong-hong", "cung-dien-vang", "giu-tien", "luoi-ho"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Konya_Kelebekler_Vadisi_Aglaonema.jpg/960px-Konya_Kelebekler_Vadisi_Aglaonema.jpg', 3, '[]'::jsonb, '["phong thủy", "cửa hàng", "quầy thu ngân", "cây tài lộc"]'::jsonb, 'Chọn cây phong thủy cho cửa hàng, quầy thu ngân theo quan niệm dân gian: phú quý, vạn lộc, lưỡi hổ; vị trí đặt, cây nên tránh, cách chăm.', 13),
('y-nghia-ten-goi-cay-tai-loc', 'phong-thuy', 'Ý nghĩa tên gọi các cây "tài lộc": phú quý, vạn lộc, ngân hậu, như ý, giữ tiền, kim cương', 'Rất nhiều cây kiểng lá ở Việt Nam mang tên gọi đẹp gắn với tiền bạc, may mắn, bình an. Tên gọi này phần lớn do nhà vườn, người bán đặt để dễ nhớ, dễ làm quà. Bài này giải thích ý nghĩa thường được gán cho từng cây.', '[{"type": "p", "text": "Ở các chợ hoa, nhà vườn miền Tây, cùng một loài cây có thể mang vài tên khác nhau. Tên thương mại thường được chọn sao cho đẹp, dễ nhớ, gợi điều may mắn để khách mua làm quà. Hiểu ý nghĩa tên gọi giúp bạn chọn cây tặng đúng dịp."}, {"type": "h2", "text": "Nhóm tên gọi về tiền bạc, sung túc"}, {"type": "list", "items": ["**[Phú quý](/san-pham/phu-quy):** giàu sang, phú quý. Lá đỏ hồng viền xanh — màu đỏ trong quan niệm dân gian là màu may mắn.", "**[Vạn lộc](/san-pham/van-loc):** \"lộc\" đến muôn phần. Lá đỏ hồng, rất được chuộng làm quà Tết, khai trương.", "**[Ngân hậu](/san-pham/ngan-hau):** \"ngân\" là bạc, tiền; lá xanh bạc sang trọng.", "**[Ngọc ngân](/san-pham/ngoc-ngan):** ngọc và bạc, quý giá; lá đốm trắng như ngọc.", "**[Giữ tiền](/san-pham/giu-tien), [giữ tiền Thái](/san-pham/giu-tien-thai):** mong giữ được tiền, làm ăn tích lũy.", "**[Kim cương hồng](/san-pham/kim-cuong-hong), [cung điện vàng](/san-pham/cung-dien-vang):** sang trọng, quý phái."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/2095Ornamental_plants_in_the_Philippines_15.jpg/960px-2095Ornamental_plants_in_the_Philippines_15.jpg", "caption": "Nhóm cây lá đỏ hồng như phú quý, vạn lộc được chuộng làm quà vì màu đỏ gắn với may mắn trong quan niệm dân gian."}, {"type": "h2", "text": "Nhóm tên gọi về bình an, như ý"}, {"type": "list", "items": ["**[Như ý](/san-pham/nhu-y):** vạn sự như ý, mọi việc thuận lợi.", "**[Lan ý](/san-pham/lan-y):** hoa trắng thanh khiết, tượng trưng sự bình yên.", "**[Thanh xuân](/san-pham/thanh-xuan):** tươi trẻ, sức sống.", "**[Sao sáng](/san-pham/sao-sang):** tỏa sáng, nổi bật."], "ordered": false}, {"type": "h2", "text": "Nhóm tên gọi về sự vững vàng, thăng tiến"}, {"type": "list", "items": ["**[Trầu bà đế vương](/san-pham/trau-ba-de-vuong-xanh):** dáng lá to, bóng, đứng thẳng — gợi uy thế, vững vàng. Có các màu xanh, đỏ, vàng, nâu; xem [phân biệt trầu bà đế vương](/goc-cham-cay/phan-biet-cac-loai-trau-ba-de-vuong).", "**[Bạch mã hoàng tử](/san-pham/bach-ma-hoang-tu):** gân trắng nổi trên thân lá như ngựa trắng — gợi thành công, đỗ đạt.", "**[Lưỡi hổ](/san-pham/luoi-ho):** mạnh mẽ, xua điều xấu."], "ordered": false}, {"type": "h2", "text": "Cùng loài, khác tên — vì sao?"}, {"type": "p", "text": "Nhóm cây Aglaonema (phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã) có rất nhiều giống lai, mỗi giống được đặt một tên thương mại. Một số tên như giữ tiền, như ý, sao sáng là tên thương mại của nhà vườn, có thể khác nhau giữa các vùng. Khi mua, nên xem ảnh thật và thông số cây thay vì chỉ dựa vào tên. Xem thêm [phân biệt phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã](/goc-cham-cay/phan-biet-phu-quy-van-loc-ngoc-ngan-ngan-hau)."}, {"type": "h2", "text": "Chọn cây tặng theo dịp"}, {"type": "table", "rows": [["Dịp", "Cây hay được chọn"], ["Khai trương, mở cửa hàng", "Phú quý, vạn lộc, kim cương hồng, giữ tiền"], ["Tân gia", "Ngọc ngân, như ý, lan ý, trầu bà đế vương"], ["Thăng chức", "Bạch mã hoàng tử, trầu bà đế vương"], ["Tặng người lớn tuổi", "Như ý, lưỡi hổ (dễ chăm)"]]}, {"type": "p", "text": "Xem thêm [chọn cây làm quà](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia)."}, {"type": "note", "title": "Góc nhìn thực tế", "text": "Tên gọi đẹp là một phần niềm vui khi tặng cây. Nhưng món quà chỉ trọn vẹn khi cây sống khỏe ở nhà người nhận — hãy hỏi chỗ đặt cây có sáng không, người nhận có thời gian tưới không để chọn cây phù hợp."}, {"type": "products", "title": "Cây tên gọi may mắn", "slugs": ["phu-quy", "van-loc", "ngan-hau", "nhu-y", "giu-tien", "bach-ma-hoang-tu"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/2095Ornamental_plants_in_the_Philippines_25.jpg/960px-2095Ornamental_plants_in_the_Philippines_25.jpg', 3, '[]'::jsonb, '["phong thủy", "cây tài lộc", "ý nghĩa cây cảnh", "quà tặng"]'::jsonb, 'Ý nghĩa tên gọi các cây tài lộc: phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã hoàng tử, như ý, giữ tiền, kim cương và cách chọn làm quà.', 20),
('kieng-ky-khi-dat-cay-trong-nha', 'phong-thuy', 'Những điều dân gian kiêng khi đặt cây trong nhà — và nên hiểu thế nào cho thực tế', 'Không trồng cây to trước cửa, không để cây chết trong nhà, kiêng cây có gai trong phòng ngủ… Nhiều lời kiêng của ông bà thật ra có lý do rất thực tế. Bài này điểm lại các kiêng kỵ thường gặp và cách hiểu hợp lý.', '[{"type": "p", "text": "Trong dân gian có nhiều câu truyền miệng về việc trồng cây quanh nhà. Không phải lời kiêng nào cũng có cơ sở, nhưng nhiều điều xuất phát từ kinh nghiệm sống thực tế của ông bà: an toàn, sạch sẽ, thoáng khí. Hiểu đúng lý do giúp ta giữ được nét đẹp truyền thống mà không cực đoan."}, {"type": "h2", "text": "1. Không trồng cây to chắn ngay trước cửa chính"}, {"type": "p", "text": "**Quan niệm:** cây to trước cửa chắn tài lộc, chắn vượng khí vào nhà."}, {"type": "p", "text": "**Lý do thực tế:** cây to che ánh sáng, gió, làm nhà tối, ẩm; rễ cây lớn có thể làm nứt nền, móng; cành gãy khi mưa bão nguy hiểm cho người ra vào. Nếu muốn có cây ở cửa, đặt hai chậu cân đối hai bên, cây cỡ vừa."}, {"type": "h2", "text": "2. Không để cây héo, cây chết trong nhà"}, {"type": "p", "text": "**Quan niệm:** cây chết mang khí xấu, xui xẻo."}, {"type": "p", "text": "**Lý do thực tế:** cây chết, lá mục là nơi nấm mốc, côn trùng phát triển, gây mùi và mất vệ sinh. Cây héo nên chăm lại ngay hoặc thay cây mới."}, {"type": "h2", "text": "3. Kiêng cây có gai trong phòng ngủ, phòng khách"}, {"type": "p", "text": "**Quan niệm:** gai nhọn gây \"sát khí\", bất hòa."}, {"type": "p", "text": "**Lý do thực tế:** gai dễ làm trầy xước, nhất là nhà có trẻ nhỏ. Xương rồng, hoa hồng nên để ở ban công, sân."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Nature_-_Natura_%2814658158699%29.jpg/960px-Nature_-_Natura_%2814658158699%29.jpg", "caption": "Một chậu cây lá to xanh tốt đặt sát tường, gọn gàng — sạch sẽ, thoáng đãng cũng là tinh thần của nhiều lời kiêng xưa."}, {"type": "h2", "text": "4. Không đặt nhiều cây trong phòng ngủ"}, {"type": "p", "text": "**Quan niệm:** cây \"tranh\" khí của người ngủ."}, {"type": "p", "text": "**Lý do thực tế:** ban đêm cây hô hấp, nhưng lượng khí của vài chậu cây nhỏ là không đáng kể. Vấn đề thực tế hơn là đất ẩm, lá mục có thể sinh nấm mốc, côn trùng. Một vài chậu nhỏ, chăm sạch là không sao. Xem [nên đặt cây gì trong phòng ngủ](/goc-cham-cay/cay-dat-phong-ngu)."}, {"type": "h2", "text": "5. Kiêng cây leo bám kín tường nhà"}, {"type": "p", "text": "**Quan niệm:** cây leo bám tường làm nhà âm u, khó làm ăn."}, {"type": "p", "text": "**Lý do thực tế:** rễ bám của một số cây leo có thể làm hỏng lớp sơn, len vào khe nứt; tường giữ ẩm lâu, dễ thấm. Nếu thích cây leo, dùng giàn, lưới riêng cách tường."}, {"type": "h2", "text": "6. Kiêng cây có nhựa độc gần trẻ nhỏ"}, {"type": "p", "text": "Nhiều cây kiểng lá phổ biến (môn, trầu bà, vạn niên thanh, lan ý) có nhựa gây ngứa. Đặt cao, xa tầm với của trẻ nhỏ và thú cưng. Xem [cây an toàn cho trẻ nhỏ, chó mèo](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung)."}, {"type": "h2", "text": "7. Không trồng cây quá sát nhà, sát giếng, bể nước"}, {"type": "p", "text": "Lá rụng làm bẩn nguồn nước, rễ cây lớn làm nứt bể, cành cây chạm mái gây dột. Đây là kinh nghiệm hoàn toàn thực tế."}, {"type": "h2", "text": "Tóm lại"}, {"type": "p", "text": "Những lời kiêng về cây quanh nhà phần lớn hướng tới: **nhà thoáng sáng, sạch sẽ, an toàn**. Chọn cây hợp chỗ, giữ cây khỏe là đã làm đúng tinh thần đó. Muốn chọn cây theo màu lá, mệnh, xem [chọn cây hợp mệnh](/goc-cham-cay/chon-cay-theo-menh-ngu-hanh)."}, {"type": "note", "title": "Góc nhìn thực tế", "text": "Phong thủy là quan niệm dân gian, có nhiều trường phái khác nhau. Khi băn khoăn, hãy ưu tiên điều an toàn và thực tế: cây không che lối đi, không gây nguy hiểm, hợp với ánh sáng nơi đặt."}, {"type": "products", "title": "Cây nhỏ gọn, sạch sẽ cho trong nhà", "slugs": ["lan-chi", "luoi-ho", "phu-quy", "ngoc-ngan"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/ADXNRVTWGQ.jpg', 3, '[]'::jsonb, '["phong thủy", "kiêng kỵ", "cây trong nhà", "đặt cây"]'::jsonb, 'Những điều dân gian kiêng khi đặt cây trong nhà: cây trước cửa, cây héo, cây có gai, cây trong phòng ngủ, cây leo bám tường và lý do thực tế.', 27),
('cay-phong-thuy-phong-khach-loi-vao', 'phong-thuy', 'Đặt cây phong thủy ở phòng khách và lối vào nhà: chọn cây, vị trí, cặp chậu đối xứng', 'Phòng khách và lối vào là nơi khách nhìn thấy đầu tiên, cũng là nơi dân gian gửi gắm nhiều mong muốn về tài lộc, bình an. Đây là cách chọn cây, đặt cây ở phòng khách, hai bên cửa, góc tường theo quan niệm phổ biến mà vẫn hợp ánh sáng thực tế.', '[{"type": "p", "text": "Phòng khách là \"bộ mặt\" của ngôi nhà. Theo quan niệm dân gian, đây là nơi đón khí vào nhà nên cây đặt ở đây thường được chọn kỹ: lá xanh tốt, dáng đứng thẳng, tên gọi đẹp. Về thực tế, phòng khách thường là phòng sáng nhất nhà, rất hợp để trồng cây lớn."}, {"type": "h2", "text": "Lối vào và hai bên cửa chính"}, {"type": "list", "items": ["**Cặp chậu đối xứng** hai bên cửa là cách bày quen thuộc, tượng trưng sự cân bằng, đón khách. Chọn hai cây cùng loại, cùng cỡ, chậu giống nhau.", "Cửa có mái che, nắng nhẹ: [trầu bà đế vương](/san-pham/trau-ba-de-vuong-xanh), [phú quý](/san-pham/phu-quy).", "Cửa nắng trực tiếp: cây chịu nắng như [tắc cẩm thạch](/san-pham/tac-cam-thach-thai), [tùng thơm](/san-pham/tung-thom).", "Không để cây chắn lối đi, cành lá quẹt vào người ra vào."], "ordered": false}, {"type": "h2", "text": "Cây chủ đạo ở phòng khách"}, {"type": "p", "text": "Một cây lớn (cao 80cm–1,5m) đặt ở góc phòng tạo điểm nhấn:"}, {"type": "list", "items": ["**[Bạch mã hoàng tử](/san-pham/bach-ma-hoang-tu):** gân trắng nổi, ý nghĩa thành công.", "**[Vạn niên thanh](/san-pham/van-nien-thanh):** lá to, xanh quanh năm, ý nghĩa trường tồn.", "**[Trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do):** lá đỏ tía sang trọng.", "**[Lan ý nữ hoàng](/san-pham/lan-y-nu-hoang):** lá to, hoa trắng thanh lịch."], "ordered": false}, {"type": "h2", "text": "\"Góc tài lộc\""}, {"type": "p", "text": "Nhiều quan niệm cho rằng góc chéo đối diện cửa chính là góc tài lộc, nên đặt cây xanh tốt hoặc vật phẩm ý nghĩa. Góc này thường xa cửa sổ, ít sáng — chọn cây chịu bóng như [phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc), hoặc xoay vòng cây ra chỗ sáng định kỳ."}, {"type": "h2", "text": "Bàn trà, kệ tivi"}, {"type": "p", "text": "Cây nhỏ cao dưới 40cm: [ngọc ngân](/san-pham/ngoc-ngan), [lan chi](/san-pham/lan-chi), [môn quan âm](/san-pham/mon-quan-am). Tránh đặt cây sát tivi, loa, ổ điện vì nước tưới có thể rơi vào thiết bị."}, {"type": "h2", "text": "Nên tránh"}, {"type": "list", "items": ["Cây héo, cây giả bám bụi ở nơi khách nhìn thấy đầu tiên.", "Cây gai nhọn ở lối đi.", "Quá nhiều chậu nhỏ lộn xộn — chọn 1 cây chủ đạo và vài cây phụ là đủ."], "ordered": true}, {"type": "p", "text": "Cách phối cây chủ đạo, cây phụ cho phòng khách xem thêm ở bài [bố trí cây cho phòng khách, căn hộ](/goc-cham-cay/bo-tri-cay-phong-khach-can-ho)."}, {"type": "note", "title": "Góc nhìn thực tế", "text": "Chọn cây theo ánh sáng trước, ý nghĩa sau. Một cây \"đẹp ý nghĩa\" mà đặt sai chỗ, héo dần thì không còn đẹp nữa. Cây lớn nên chọn chậu nặng, vững để không đổ khi trẻ nhỏ chạy chơi."}, {"type": "products", "title": "Cây cho phòng khách và lối vào", "slugs": ["bach-ma-hoang-tu", "van-nien-thanh", "trau-ba-de-vuong-do", "lan-y-nu-hoang", "phu-quy", "tac-cam-thach-thai"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/MUNCW5ZFUZ.jpg', 2, '[]'::jsonb, '["phong thủy", "phòng khách", "lối vào", "cửa chính"]'::jsonb, 'Cách đặt cây phong thủy ở phòng khách, lối vào theo quan niệm dân gian: cây chủ đạo, cặp chậu hai bên cửa, góc tài lộc và cây nên tránh.', 34),
('trang-tri-ban-cong-chung-cu-nho', 'decor', 'Trang trí ban công chung cư nhỏ bằng cây xanh: 5 cách bố trí cho ban công dưới 3m²', 'Ban công chung cư thường hẹp, nắng gió mạnh và phải chừa chỗ phơi đồ. Chỉ cần bố trí theo chiều đứng, chọn cây hợp hướng nắng và chậu nhẹ, ban công 2–3m² vẫn thành góc xanh để ngồi uống cà phê.', '[{"type": "p", "text": "Ban công chung cư là khoảng không gian quý giá để mang thiên nhiên vào nhà. Nhưng diện tích nhỏ, gió mạnh ở tầng cao và nắng chiếu gắt khiến nhiều người trồng mãi cây vẫn không lên. Bí quyết là bố trí thông minh và chọn đúng cây."}, {"type": "h2", "text": "Bước 1: Xem hướng nắng"}, {"type": "table", "rows": [["Hướng ban công", "Nắng", "Cây hợp"], ["Đông", "Nắng sáng dịu", "Hầu hết cây hoa, rau thơm, hoa hồng"], ["Nam", "Nắng nhiều trong ngày", "Cây chịu nắng, cây ra hoa"], ["Tây", "Nắng chiều gắt", "Cây chịu nắng nóng; cần lưới che, rèm tre"], ["Bắc", "Ít nắng trực tiếp", "Kiểng lá chịu bóng"]]}, {"type": "p", "text": "Chi tiết về ban công nắng gắt có ở bài [cây ban công hướng Tây](/goc-cham-cay/cay-ban-cong-nang-gat)."}, {"type": "h2", "text": "5 cách bố trí cho ban công nhỏ"}, {"type": "h3", "text": "1. Tận dụng chiều đứng"}, {"type": "p", "text": "Kệ bậc thang 3–4 tầng đặt sát tường: cây cao ở dưới, cây nhỏ ở trên, chiếm chưa tới 0,5m² sàn mà chứa được 8–10 chậu."}, {"type": "h3", "text": "2. Chậu treo lan can"}, {"type": "p", "text": "Chậu dài, chậu móc treo phía trong lan can — đừng treo ra ngoài vì nguy hiểm cho người bên dưới khi gió to. Hợp với [mai địa thảo](/san-pham/mai-dia-thao), rau thơm, cây rủ."}, {"type": "h3", "text": "3. Một cây điểm nhấn ở góc"}, {"type": "p", "text": "Một chậu cây cỡ vừa ở góc ban công (ví dụ [tắc cẩm thạch](/san-pham/tac-cam-thach-thai), [tùng thơm](/san-pham/tung-thom)) đủ tạo cảm giác \"có vườn\"."}, {"type": "h3", "text": "4. Chừa lối đi và chỗ phơi đồ"}, {"type": "p", "text": "Bố trí cây dọc một bên tường, bên còn lại để đi lại và phơi đồ. Đừng để chậu chiếm hết lối ra."}, {"type": "h3", "text": "5. Ghế gấp và thảm cỏ nhân tạo"}, {"type": "p", "text": "Ban công đủ chỗ cho một ghế gấp nhỏ là đã có góc thư giãn. Thảm, sàn gỗ ghép giúp sàn mát chân và dễ vệ sinh."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/NPPTA6CQTM.jpg", "caption": "Kệ treo tường nhiều chậu nhỏ — tận dụng chiều đứng, gần như không chiếm diện tích sàn."}, {"type": "h2", "text": "Lưu ý an toàn"}, {"type": "list", "items": ["**Chậu nhẹ:** dùng chậu nhựa, chậu composite thay vì chậu sứ to; đất trộn nhẹ (xơ dừa, tro trấu). Sàn ban công có giới hạn chịu tải.", "**Chống gió:** tầng cao gió mạnh — không để chậu cao, nhẹ trên lan can; buộc cây cao vào cọc.", "**Thoát nước:** đặt đĩa hứng dưới chậu, không để nước tràn xuống ban công nhà dưới.", "Kiểm tra quy định của tòa nhà về treo đồ ngoài lan can."], "ordered": false}, {"type": "h2", "text": "Chăm ban công nắng gió"}, {"type": "p", "text": "Ban công khô nhanh hơn trong nhà rất nhiều. Mùa nắng tưới mỗi sáng, có khi thêm buổi chiều; phủ mặt chậu bằng xơ dừa, vỏ thông để giữ ẩm. Cây mới đưa ra ban công phải tập nắng dần để tránh [cháy lá](/benh-cay/chay-la-do-nang)."}, {"type": "products", "title": "Cây hợp ban công", "slugs": ["hoa-hong", "mai-dia-thao", "tulip-thai", "tac-cam-thach-thai", "tung-thom"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Red_rose_from_my_balcony_garden.jpg/960px-Red_rose_from_my_balcony_garden.jpg', 2, '["chay-la-do-nang"]'::jsonb, '["ban công", "chung cư", "trang trí", "decor"]'::jsonb, 'Ý tưởng trang trí ban công chung cư nhỏ bằng cây xanh: tận dụng chiều cao, chậu treo lan can, chọn cây theo hướng nắng, chậu nhẹ, an toàn gió.', 5),
('goc-xanh-ban-lam-viec-tai-nha', 'decor', 'Tạo góc xanh cho bàn làm việc tại nhà: chọn cây, sắp xếp và giữ cây đẹp khi làm việc cả ngày', 'Làm việc ở nhà cả ngày trước màn hình dễ mỏi mắt, bí bách. Vài chậu cây đặt đúng chỗ làm góc làm việc dịu hơn hẳn. Đây là cách chọn cây theo bàn và ánh sáng, sắp xếp gọn gàng, không vướng tay, không làm bẩn bàn.', '[{"type": "p", "text": "Một góc làm việc tại nhà dễ chịu không cần nhiều tiền: một chiếc bàn gọn, ánh sáng tốt và vài chậu cây. Cây xanh không thay được những lần đứng dậy nghỉ mắt, nhưng nhìn thấy màu xanh trong tầm mắt giúp góc làm việc bớt khô khan."}, {"type": "h2", "text": "Ba lớp cây cho góc làm việc"}, {"type": "h3", "text": "Lớp 1: Một chậu nhỏ trên bàn"}, {"type": "p", "text": "Cao dưới 30–40cm, đặt góc bàn phía cửa sổ, không chắn màn hình. Gợi ý: [ngọc ngân](/san-pham/ngoc-ngan), [lan chi](/san-pham/lan-chi), [môn melo](/san-pham/mon-melo), [đuôi công tím](/san-pham/duoi-cong-tim)."}, {"type": "h3", "text": "Lớp 2: Một cây đứng cạnh bàn"}, {"type": "p", "text": "Cây cao 60cm–1m đặt dưới sàn bên cạnh bàn, tán lá ngang tầm mắt khi ngồi. Gợi ý: [trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh), [bạch mã](/san-pham/bach-ma-hoang-tu), [lan ý nữ hoàng](/san-pham/lan-y-nu-hoang)."}, {"type": "h3", "text": "Lớp 3: Cây trên kệ, cây treo"}, {"type": "p", "text": "Kệ sách phía sau hoặc bên cạnh bàn đặt thêm 1–2 chậu nhỏ, hoặc một chậu lan chi treo rủ. Ba lớp cây ở ba độ cao khác nhau tạo cảm giác có chiều sâu mà không chiếm diện tích bàn."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/DPZPTWJ07T.jpg", "caption": "Một chậu cây nhỏ ở góc bàn cạnh cửa sổ — đủ sáng cho cây, không chắn màn hình và không vướng tay."}, {"type": "h2", "text": "Đặt theo ánh sáng"}, {"type": "list", "items": ["Bàn sát cửa sổ: hầu hết kiểng lá đều sống tốt; nếu nắng chiều chiếu thẳng thì cần rèm mỏng.", "Bàn giữa phòng, chỉ có đèn: chọn cây chịu bóng (lưỡi hổ, phú quý, bạch mã). Đèn bàn ánh sáng trắng cũng giúp cây phần nào."], "ordered": false}, {"type": "p", "text": "Xem thêm [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."}, {"type": "h2", "text": "Giữ bàn sạch, an toàn"}, {"type": "list", "items": ["Luôn có **đĩa hứng** dưới chậu; dùng chậu bọc ngoài không lỗ, bên trong là chậu nhựa có lỗ.", "Phủ mặt chậu bằng sỏi nhỏ hoặc đá trang trí: đất không văng, bàn sạch hơn.", "Không đặt cây sát laptop, ổ điện, sạc điện thoại.", "Tưới bằng bình có vòi nhỏ, tưới chậm, ngồi nhìn tới khi nước vừa ra đáy chậu."], "ordered": true}, {"type": "h2", "text": "Chăm khi bận rộn"}, {"type": "list", "items": ["Gắn việc tưới với một thói quen cố định, ví dụ sáng thứ Hai và thứ Năm kiểm tra đất.", "Chọn cây cùng nhu cầu nước để tưới một lượt.", "Mỗi tháng lau lá một lần — vừa làm đẹp vừa kiểm tra sâu bệnh. Xem [lau lá, cắt tỉa lá già](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la)."], "ordered": false}, {"type": "p", "text": "Muốn biết cây nào sống khỏe nhất trên bàn làm việc, đọc [8 cây để bàn làm việc dễ chăm](/goc-cham-cay/cay-de-ban-lam-viec-de-cham)."}, {"type": "products", "title": "Cây cho góc làm việc tại nhà", "slugs": ["ngoc-ngan", "lan-chi", "mon-melo", "trau-ba-de-vuong-xanh", "bach-ma-hoang-tu", "luoi-ho"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/DB8D7GBTJH.jpg', 2, '[]'::jsonb, '["bàn làm việc", "làm việc tại nhà", "decor", "cây để bàn"]'::jsonb, 'Ý tưởng tạo góc xanh cho bàn làm việc tại nhà: chọn cây để bàn, cây đứng cạnh bàn, kệ treo, sắp xếp theo ánh sáng, giữ bàn sạch và cách chăm cây khi bận rộn.', 12),
('trang-tri-ke-sach-bang-cay', 'decor', 'Trang trí kệ sách, kệ tivi bằng cây xanh: chọn cây nhỏ, cây rủ và cách đặt cho đẹp mà không làm hỏng kệ', 'Vài chậu cây xen giữa những hàng sách, khung ảnh làm kệ sinh động hẳn. Nhưng kệ thường xa cửa sổ, chậu dễ làm ẩm gỗ. Bài này gợi ý cây hợp kệ, cách phối chiều cao và giữ kệ không bị hỏng vì nước tưới.', '[{"type": "p", "text": "Kệ sách là nơi trưng bày những thứ ta yêu thích. Thêm vài chậu cây, kệ trở nên mềm mại, có sức sống hơn. Vấn đề là kệ thường đặt sát tường, xa cửa sổ, nên cần chọn cây chịu bóng và có cách đặt hợp lý."}, {"type": "h2", "text": "Nguyên tắc phối cây trên kệ"}, {"type": "list", "items": ["**Ít mà chất:** 1 chậu cây cho mỗi 2–3 ngăn kệ là vừa; quá nhiều cây làm kệ rối.", "**Phối chiều cao:** cây đứng thẳng ở ngăn dưới, cây nhỏ tròn ở giữa, cây rủ ở ngăn trên cùng để lá buông xuống.", "**Đặt theo đường chéo:** cây ở ngăn trên bên trái, ngăn giữa bên phải, ngăn dưới bên trái… mắt nhìn sẽ thấy cân đối.", "**Đồng bộ chậu:** chọn 2–3 kiểu chậu cùng tông màu (trắng, đất nung, xám) cho cả kệ."], "ordered": true}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/1XAJHYVE9L.jpg", "caption": "Kệ sách với vài chậu cây nhỏ xen giữa — ít mà chất, đặt so le giữa các ngăn để kệ không rối."}, {"type": "h2", "text": "Cây hợp kệ sách"}, {"type": "table", "rows": [["Vị trí trên kệ", "Cây gợi ý"], ["Ngăn trên cùng (cây rủ)", "[Lan chi](/san-pham/lan-chi), trầu bà leo"], ["Ngăn giữa (cây nhỏ, tán tròn)", "[Ngọc ngân](/san-pham/ngoc-ngan), [môn melo](/san-pham/mon-melo), [đuôi công xanh](/san-pham/duoi-cong-xanh)"], ["Ngăn dưới, mặt kệ tivi (cây đứng)", "[Lưỡi hổ](/san-pham/luoi-ho), [phú quý](/san-pham/phu-quy)"], ["Cạnh kệ dưới sàn", "[Bạch mã](/san-pham/bach-ma-hoang-tu), [vạn niên thanh](/san-pham/van-nien-thanh)"]]}, {"type": "h2", "text": "Bảo vệ kệ gỗ"}, {"type": "list", "items": ["**Chậu bọc ngoài không lỗ** (hoặc đĩa hứng có thành cao) để nước không chảy ra gỗ.", "Lót miếng đệm cao su hoặc khay nhỏ dưới chậu để chậu không chạm trực tiếp mặt gỗ, không đọng hơi ẩm.", "**Bê chậu ra bồn rửa để tưới**, đợi ráo nước mới đặt lại kệ — cách này an toàn nhất cho kệ.", "Không đặt cây sát thiết bị điện tử trên kệ tivi."], "ordered": false}, {"type": "h2", "text": "Ánh sáng cho cây trên kệ"}, {"type": "p", "text": "Kệ cách cửa sổ 2–3m thường chỉ đủ cho cây chịu bóng. Để cây khỏe lâu:"}, {"type": "list", "items": ["Xoay chậu mỗi tuần để cây không nghiêng hẳn một phía.", "Mỗi 2–3 tuần cho cây \"đi nghỉ\" ở chỗ sáng hơn vài ngày, thay phiên giữa hai cây cùng loại.", "Cây ra lá nhỏ, nhạt màu, vươn dài là dấu hiệu thiếu sáng — đổi chỗ hoặc chọn cây chịu bóng hơn. Xem [cây sống khỏe ở góc thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang)."], "ordered": false}, {"type": "products", "title": "Cây nhỏ, cây rủ cho kệ", "slugs": ["lan-chi", "ngoc-ngan", "mon-melo", "duoi-cong-xanh", "luoi-ho", "phu-quy"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/KVIJTZ5LHP.jpg', 2, '[]'::jsonb, '["kệ sách", "trang trí", "decor", "cây rủ"]'::jsonb, 'Cách trang trí kệ sách, kệ tivi bằng cây xanh: chọn cây nhỏ chịu bóng, cây rủ lá, phối chiều cao, chậu bọc, chống ẩm gỗ và chăm cây đặt trên kệ xa cửa sổ.', 19),
('phoi-mau-chau-cay-voi-noi-that', 'decor', 'Phối chậu và cây với nội thất: chọn màu chậu, chất liệu, cỡ cây cho từng phong cách nhà', 'Cùng một cây nhưng đặt trong chậu khác nhau sẽ cho cảm giác rất khác: chậu trắng hiện đại, chậu đất nung mộc mạc, chậu đen sang trọng. Bài này hướng dẫn chọn chậu và cây hợp phong cách nội thất mà vẫn tốt cho rễ cây.', '[{"type": "p", "text": "Chậu cây là \"trang phục\" của cây. Chọn đúng chậu giúp cây hòa vào không gian, trông như một phần của nội thất chứ không phải món đồ đặt tạm. Đồng thời, chậu cũng ảnh hưởng trực tiếp đến sức khỏe bộ rễ."}, {"type": "h2", "text": "Chất liệu chậu: đẹp và hợp cây"}, {"type": "table", "rows": [["Chất liệu", "Cảm giác", "Lưu ý cho cây"], ["Sứ men, gốm tráng men", "Sang, sạch, dễ phối", "Thường không có lỗ — dùng làm chậu bọc"], ["Đất nung không men", "Mộc mạc, ấm", "Thoát hơi tốt, đất khô nhanh hơn — hợp cây sợ úng"], ["Nhựa", "Nhẹ, rẻ, nhiều màu", "Giữ ẩm lâu, nên chọn loại dày, có lỗ"], ["Xi măng, đá mài", "Hiện đại, công nghiệp", "Nặng, hợp cây lớn đặt cố định"], ["Giỏ mây, cói, vải", "Tự nhiên, nhẹ nhàng", "Chỉ dùng bọc ngoài, bên trong có chậu nhựa và đĩa hứng"]]}, {"type": "h2", "text": "Phối theo phong cách nhà"}, {"type": "h3", "text": "Hiện đại, tối giản"}, {"type": "p", "text": "Chậu trắng, xám, đen trơn, dáng trụ hoặc vuông. Cây lá đơn giản, dáng gọn: [lưỡi hổ](/san-pham/luoi-ho), [trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh)."}, {"type": "h3", "text": "Bắc Âu, gỗ sáng"}, {"type": "p", "text": "Chậu đất nung, gốm màu kem, giỏ cói. Cây lá mềm: [lan chi](/san-pham/lan-chi), [dương xỉ](/san-pham/duong-xi), [đuôi công](/san-pham/duoi-phung)."}, {"type": "h3", "text": "Á Đông, gỗ tối"}, {"type": "p", "text": "Chậu men lam, men nâu, chậu gốm Bát Tràng, Biên Hòa. Cây dáng đứng, lá bóng: [phú quý](/san-pham/phu-quy), [bạch mã](/san-pham/bach-ma-hoang-tu), [tùng thơm](/san-pham/tung-thom)."}, {"type": "h2", "text": "Phối màu lá với nội thất"}, {"type": "list", "items": ["Tường trắng, sàn sáng: cây lá đậm (xanh thẫm, đỏ tía) làm điểm nhấn — [trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do), [vạn lộc](/san-pham/van-loc).", "Tường tối, gỗ sậm: cây lá sáng, đốm trắng — [ngọc ngân](/san-pham/ngoc-ngan), [ngân hậu](/san-pham/ngan-hau).", "Không gian nhiều màu: chọn cây lá xanh trơn để không rối mắt."], "ordered": false}, {"type": "h2", "text": "Chọn cỡ cây theo không gian"}, {"type": "list", "items": ["Cây đặt sàn nên cao khoảng **1/3 đến 1/2 chiều cao trần** nếu muốn làm điểm nhấn góc phòng.", "Cây trên bàn không cao quá tầm mắt khi ngồi.", "Chậu nên cân với cây: cây cao thì chậu đủ nặng để không đổ."], "ordered": false}, {"type": "h2", "text": "Chậu đẹp nhưng phải tốt cho rễ"}, {"type": "p", "text": "Chậu đẹp không có lỗ thoát nước là nguyên nhân hàng đầu khiến cây [thối rễ](/benh-cay/thoi-re). Cách giải quyết: dùng chậu đẹp làm **chậu bọc**, cây trồng trong chậu nhựa có lỗ đặt bên trong, kê một lớp sỏi ở đáy chậu bọc. Sau mỗi lần tưới, kiểm tra và đổ nước đọng. Hiểu thêm về cỡ chậu ở bài [mã chậu C6, C7, C9, C10](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."}, {"type": "products", "title": "Cây dễ phối nội thất", "slugs": ["luoi-ho", "trau-ba-de-vuong-xanh", "trau-ba-de-vuong-do", "ngoc-ngan", "phu-quy", "lan-chi"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Terracotta_Pots_%28Unsplash%29.jpg/960px-Terracotta_Pots_%28Unsplash%29.jpg', 2, '["thoi-re"]'::jsonb, '["chậu cây", "nội thất", "decor", "phối màu"]'::jsonb, 'Cách phối chậu cây với nội thất: chọn màu, chất liệu chậu sứ, đất nung, nhựa, xi măng, mây tre và cỡ cây hợp từng phong cách nhà.', 26),
('cay-treo-gio-treo-trang-tri', 'decor', 'Trang trí bằng cây treo, giỏ treo: chọn cây rủ, móc treo an toàn và cách tưới không nhỏ giọt', 'Cây treo tận dụng khoảng trống trên cao, làm nhà có cảm giác xanh mát mà không chiếm sàn. Bài này gợi ý cây hợp treo trong nhà và ngoài ban công, cách chọn móc, giỏ treo chịu lực và tưới cây treo sạch sẽ.', '[{"type": "p", "text": "Cây treo là cách tốt để có thêm màu xanh cho nhà nhỏ: góc cửa sổ, hiên nhà, ban công, phòng tắm có cửa sáng. Cây rủ lá tạo đường cong mềm mại, nhìn từ dưới lên rất đẹp."}, {"type": "h2", "text": "Cây hợp treo"}, {"type": "table", "rows": [["Vị trí", "Cây gợi ý"], ["Trong nhà, gần cửa sổ", "[Lan chi](/san-pham/lan-chi) (cây con rủ xuống từ cây mẹ), trầu bà leo, dương xỉ"], ["Hiên nhà, ban công nắng nhẹ", "[Mai địa thảo](/san-pham/mai-dia-thao), [dương xỉ](/san-pham/duong-xi)"], ["Ban công nắng nhiều", "Cây mọng nước rủ, hoa mười giờ"]]}, {"type": "p", "text": "Lan chi là cây treo dễ nhất: rễ củ trữ nước, cây mẹ ra các \"cây con\" trên ngọn dây rủ xuống, có thể tách trồng thành chậu mới."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Peperomia_boivinii_in_cultivation.jpg/960px-Peperomia_boivinii_in_cultivation.jpg", "caption": "Chậu đất nung treo bằng dây đan — cây lá nhỏ rủ xuống mềm mại, không chiếm diện tích sàn."}, {"type": "h2", "text": "Chọn móc treo và giỏ treo an toàn"}, {"type": "list", "items": ["Một chậu treo đường kính 20cm sau khi tưới có thể nặng 3–5kg. Móc treo phải bắt vào **dầm, trần bê tông** bằng tắc kê, không treo vào trần thạch cao nếu không có khung chịu lực.", "Dây treo bằng cáp, xích hoặc dây dù to; kiểm tra dây buộc định kỳ, nhất là dây ngoài trời dễ mục.", "Ngoài ban công, treo phía trong lan can, tránh vị trí gió giật mạnh.", "Treo ở độ cao không cụng đầu người đi qua."], "ordered": false}, {"type": "h2", "text": "Chậu treo nên có khay"}, {"type": "p", "text": "Chọn chậu treo có **khay hứng liền** hoặc có lớp lót xơ dừa dày. Trong nhà, dùng chậu nhựa có lỗ đặt trong chậu treo kín đáy — nước thừa đọng lại bên trong, không nhỏ xuống sàn."}, {"type": "h2", "text": "Tưới cây treo không nhỏ giọt"}, {"type": "list", "items": ["Cách sạch nhất: **gỡ chậu xuống**, đặt vào bồn rửa, tưới đẫm, để ráo 15–20 phút rồi treo lại.", "Nếu không gỡ xuống được, dùng bình có vòi dài, tưới chậm từng ít một, dừng khi thấy nước vừa đến đáy.", "Đặt thêm khay hứng hoặc lót khăn dưới sàn chỗ treo khi tưới.", "Cây treo ở trên cao khô nhanh hơn chậu dưới sàn (gần trần nóng hơn, gió nhiều hơn) — kiểm tra đất thường hơn. Cây héo rũ do khát xem bài [héo do thiếu nước](/benh-cay/heo-thieu-nuoc)."], "ordered": true}, {"type": "h2", "text": "Chăm sóc thêm"}, {"type": "list", "items": ["Xoay chậu mỗi tuần để cây đều tán.", "Tỉa dây quá dài, dây khô để cây gọn.", "Bón phân loãng 1 tháng 1 lần trong mùa sinh trưởng; xem [cách bón phân cho kiểng lá trong nhà](/goc-cham-cay/bon-phan-cay-kieng-la-trong-nha)."], "ordered": false}, {"type": "products", "title": "Cây hợp treo", "slugs": ["lan-chi", "duong-xi", "mai-dia-thao"]}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/380B8E608B.jpg', 2, '["heo-thieu-nuoc"]'::jsonb, '["cây treo", "giỏ treo", "trang trí", "ban công"]'::jsonb, 'Trang trí nhà bằng cây treo, giỏ treo: chọn cây rủ cho trong nhà, ban công; móc treo chịu lực, chậu có khay và cách tưới không nhỏ nước.', 33),
('san-vuon-nho-nha-pho', 'decor', 'Thiết kế sân vườn nhỏ cho nhà phố: biến khoảng sân 10–20m² thành góc xanh dễ chăm', 'Khoảng sân trước hay sau nhà phố chỉ vài mét vuông vẫn đủ để có một góc vườn: một cây tạo bóng, vài bồn cây bụi, lối đi lát đá và chỗ ngồi nhỏ. Bài này gợi ý cách chia khu, chọn cây theo nắng và giữ sân sạch, ít công chăm.', '[{"type": "p", "text": "Nhà phố miền Tây thường có một khoảng sân trước để xe, hoặc sân sau nhỏ cạnh bếp. Chỉ cần sắp xếp hợp lý, khoảng sân 10–20m² có thể thành góc xanh mát, có chỗ ngồi uống trà, có vài chậu cây ăn trái cho trẻ con hái."}, {"type": "h2", "text": "Bước 1: Quan sát trước khi trồng"}, {"type": "list", "items": ["**Nắng:** sân hứng nắng mấy giờ, buổi nào? Sân giữa hai dãy nhà cao có khi chỉ có nắng trưa.", "**Thoát nước:** mưa lớn nước rút về đâu, có đọng không?", "**Công dụng:** sân để xe, để phơi đồ, để trẻ chơi hay để ngồi nghỉ? Chừa đủ chỗ cho việc chính."], "ordered": false}, {"type": "h2", "text": "Bước 2: Chia khu đơn giản"}, {"type": "list", "items": ["**Cây tạo bóng hoặc cây điểm nhấn:** một cây ở góc sân, tán vừa phải, rễ không phá nền. Với sân nhỏ, nên trồng chậu lớn hoặc bồn xây.", "**Bồn cây bụi, cây hoa dọc tường rào:** che tường, tạo nền xanh.", "**Lối đi:** lát đá, gạch thẻ hoặc sỏi, để đi lại không giẫm lên đất.", "**Chỗ ngồi:** một băng ghế, bàn nhỏ ở chỗ râm."], "ordered": true}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/HZN7IJIKBN.jpg", "caption": "Lối đi gọn giữa hai bồn cây giúp sân vườn dễ đi lại, dễ chăm và trông ngăn nắp hơn."}, {"type": "h2", "text": "Chọn cây cho sân nhỏ"}, {"type": "table", "rows": [["Vai trò", "Cây gợi ý"], ["Điểm nhấn, tạo dáng", "[Cau trắng](/san-pham/cau-trang), [chuối rẻ quạt](/san-pham/chuoi-re-quat), [thiên điểu Thái](/san-pham/thien-dieu-thai)"], ["Cây ăn trái trồng chậu", "[Tắc cẩm thạch](/san-pham/tac-cam-thach-thai), [sơ ri](/san-pham/cay-so-ri)"], ["Cây bụi, hoa", "[Hoa hồng](/san-pham/hoa-hong), [mai địa thảo](/san-pham/mai-dia-thao) (chỗ nắng nhẹ)"], ["Góc râm sát nhà", "[Vạn niên thanh](/san-pham/van-nien-thanh), [bạch mã](/san-pham/bach-ma-hoang-tu)"]]}, {"type": "p", "text": "Sân nhỏ **không nên** trồng cây bóng mát cỡ lớn dưới đất (bàng, bằng lăng, dầu…) sát nhà: rễ lớn, tán rộng, lá rụng nhiều. Những cây này hợp với khuôn viên rộng, xem [cây sân vườn cho nhà phố, nhà vườn](/goc-cham-cay/cay-san-vuon-nha-pho-mien-tay)."}, {"type": "h2", "text": "Giữ sân ít công chăm"}, {"type": "list", "items": ["Gom cây theo nhu cầu nước: cây ưa ẩm một khu, cây chịu khô một khu.", "Phủ gốc bằng vỏ cây, sỏi để giữ ẩm, giảm cỏ dại.", "Lắp vòi tưới nhỏ giọt hẹn giờ cho bồn cây nếu hay đi vắng.", "Kê chậu lên chân đế để nền thoáng, không ố gạch, không đọng nước."], "ordered": false}, {"type": "h2", "text": "Mùa mưa và mùa khô"}, {"type": "p", "text": "Miền Tây có hai mùa rõ rệt: mùa mưa cần thoát nước tốt, phòng nấm; mùa khô cần tưới đều, che nắng cho cây non. Xem [chăm cây mùa mưa](/goc-cham-cay/cham-cay-mua-mua-mien-tay) và [chăm cây mùa khô](/goc-cham-cay/cham-cay-mua-kho-nang-nong)."}, {"type": "products", "title": "Cây cho sân vườn nhỏ", "slugs": ["cau-trang", "tac-cam-thach-thai", "cay-so-ri", "hoa-hong", "chuoi-re-quat", "thien-dieu-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Nature_-_Natura_%2814897742652%29.jpg/960px-Nature_-_Natura_%2814897742652%29.jpg', 2, '[]'::jsonb, '["sân vườn", "nhà phố", "thiết kế vườn", "cây sân vườn"]'::jsonb, 'Ý tưởng sân vườn nhỏ cho nhà phố 10–20m²: chia khu, chọn cây điểm nhấn, cây ăn trái chậu, lối đi, thoát nước và cây dễ chăm ở miền Tây.', 40),
('cham-cay-mua-mua-mien-tay', 'theo-mua', 'Chăm cây cảnh mùa mưa ở miền Tây: chống úng, phòng nấm, giảm tưới và bón phân đúng lúc', 'Mùa mưa miền Tây kéo dài khoảng từ tháng 5 đến tháng 11, mưa nhiều, độ ẩm cao, ít nắng. Cây trồng chậu dễ úng rễ, cây ngoài trời dễ nấm bệnh. Đây là những việc cần làm để cây qua mùa mưa khỏe mạnh.', '[{"type": "p", "text": "Mùa mưa là mùa cây cảnh ra lá mới mạnh nhờ trời mát và đủ nước. Nhưng cũng là mùa nhiều cây chết nhất vì úng rễ và nấm bệnh. Ở miền Tây, mưa thường tập trung chiều tối, có những đợt mưa dầm vài ngày liền, nền đất thấp dễ đọng nước."}, {"type": "h2", "text": "1. Chống úng cho cây chậu"}, {"type": "list", "items": ["**Kê chậu cao** lên gạch, chân đế để nước thoát nhanh khỏi lỗ đáy.", "**Bỏ đĩa hứng** dưới chậu ngoài trời, hoặc đổ nước đọng sau mỗi trận mưa.", "Cây không có lỗ thoát nước, chậu bọc kín: kiểm tra đáy chậu sau mưa.", "Cây kỵ nước (lưỡi hổ, ngọc bích, sen đá, môn): đưa vào chỗ có mái hiên."], "ordered": false}, {"type": "h2", "text": "2. Giảm tưới, tưới theo đất"}, {"type": "p", "text": "Đừng tưới theo lịch mùa nắng. Ngày mưa thì không tưới; ngày âm u kiểm tra đất bằng ngón tay, chỉ tưới khi khô mặt 2–3cm. Cây trong nhà cũng hút nước chậm hơn khi trời âm u kéo dài."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Rauenthal%2C_lupine_leaves_with_rain_drops.jpg/960px-Rauenthal%2C_lupine_leaves_with_rain_drops.jpg", "caption": "Giọt nước đọng trên lá sau mưa — lá ướt lâu qua đêm là điều kiện để nấm bệnh phát triển."}, {"type": "h2", "text": "3. Phòng nấm bệnh"}, {"type": "list", "items": ["Dọn sạch lá già, lá vàng, lá rụng quanh gốc đầu mùa mưa.", "Tỉa tán cho thoáng, kê các chậu cách nhau.", "Sau mưa lớn, kiểm tra lá trong tán: thấy đốm lá có viền, vết lõm thì cắt bỏ ngay. Xem [đốm lá do nấm mùa mưa](/goc-cham-cay/dom-la-nam-mua-mua) và [thán thư](/benh-cay/than-thu).", "Có thể trộn chế phẩm [Trichoderma](/goc-cham-cay/trichoderma-che-pham-sinh-hoc) vào đất để phòng thối rễ."], "ordered": false}, {"type": "h2", "text": "4. Theo dõi thối rễ, thối nhũn"}, {"type": "p", "text": "Dấu hiệu: lá vàng hàng loạt, gốc mềm, đất có mùi hôi. Cây môn, lan ý, trầu bà rất dễ bị. Phát hiện sớm thì lấy cây ra, cắt rễ thối, thay đất thoát nước. Xem [thối rễ](/benh-cay/thoi-re), [thối nhũn củ cây môn](/goc-cham-cay/thoi-nhun-cu-mon-alocasia)."}, {"type": "h2", "text": "5. Bón phân thế nào mùa mưa?"}, {"type": "list", "items": ["Mưa nhiều làm phân hòa tan bị rửa trôi nhanh — với cây ngoài trời, dùng phân tan chậm hoặc phân hữu cơ hiệu quả hơn.", "Bón khi đất ẩm vừa, không bón ngay trước trận mưa lớn.", "Giảm đạm, tăng kali một chút giúp cây cứng cáp, chịu gió mưa."], "ordered": false}, {"type": "p", "text": "Xem thêm [phân tan chậm hay phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan)."}, {"type": "h2", "text": "6. Ốc sên và côn trùng mùa mưa"}, {"type": "p", "text": "Ốc sên, sên nhớt bò ra nhiều sau mưa, ăn lá non, rau. Bắt tay ban đêm, dọn chỗ trú. Xem [cách xử lý ốc sên an toàn](/goc-cham-cay/oc-sen-an-la-ban-cong)."}, {"type": "h2", "text": "7. Cây lớn, cây công trình"}, {"type": "list", "items": ["Kiểm tra cọc chống, dây buộc trước mùa giông.", "Tỉa bớt cành rậm, cành sát mái nhà, dây điện để giảm gãy đổ.", "Khơi rãnh thoát nước quanh gốc cây trồng ở chỗ trũng."], "ordered": false}, {"type": "note", "title": "Lưu ý an toàn", "text": "Mùa mưa nấm bệnh phát nhiều, nhưng đừng phun thuốc theo lịch khi cây chưa bệnh. Nếu cần dùng thuốc trừ nấm, chọn thuốc có đăng ký, phun lúc trời tạnh, đọc kỹ nhãn về liều và cách dùng."}, {"type": "products", "title": "Cây chịu mưa tốt ngoài trời", "slugs": ["cau-trang", "tac-cam-thach-thai", "hoa-hong", "chuoi-re-quat"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Leaves_in_spring_rain_-_Arlington%2C_MA.jpg/960px-Leaves_in_spring_rain_-_Arlington%2C_MA.jpg', 3, '["thoi-re", "dom-la-nam", "than-thu", "oc-sen", "thoi-nhun"]'::jsonb, '["mùa mưa", "miền Tây", "chống úng", "phòng bệnh"]'::jsonb, 'Cách chăm sóc cây cảnh mùa mưa ở miền Tây: chống úng cho cây chậu, giảm tưới, kê chậu, che mưa, phòng nấm bệnh, thối rễ, ốc sên và bón phân phù hợp mùa mưa.', 4),
('cham-cay-mua-kho-nang-nong', 'theo-mua', 'Chăm cây mùa khô nắng nóng: tưới đúng giờ, che nắng, giữ ẩm và phòng nhện đỏ', 'Từ khoảng tháng 12 đến tháng 4, miền Tây nắng nóng, ít mưa, gió chướng làm đất khô rất nhanh. Cây ban công, cây sân vườn dễ héo, cháy lá; cây trong nhà dễ bị nhện đỏ. Đây là kinh nghiệm giữ cây xanh qua mùa khô.', '[{"type": "p", "text": "Mùa khô ở miền Tây có nắng gắt, độ ẩm thấp và gió chướng thổi mạnh. Đất trong chậu nhỏ ngoài nắng có khi khô hẳn chỉ sau nửa ngày. Đây là mùa cây ra hoa đẹp (nhiều cây ưa nắng), nhưng cũng là mùa cây chậu chết khát nhiều nhất."}, {"type": "h2", "text": "1. Tưới đúng giờ"}, {"type": "list", "items": ["Tưới **sáng sớm** (trước 8 giờ) là tốt nhất: cây có nước dùng cho cả ngày nắng.", "Chiều mát (sau 16–17 giờ) tưới thêm cho cây chậu nhỏ, cây ở sân thượng.", "**Tránh tưới giữa trưa nắng** lên lá: nước đọng trên lá dưới nắng gắt dễ làm lá bị cháy loang, đất nóng bốc hơi nhanh.", "Tưới đẫm cho nước ra tới đáy chậu, đừng tưới lắt nhắt ướt mặt."], "ordered": false}, {"type": "h2", "text": "2. Che nắng cho cây không ưa nắng gắt"}, {"type": "list", "items": ["Lưới che nắng 50–70% cho ban công hướng Tây, sân thượng.", "Kéo cây kiểng lá vào sâu bên trong hiên, tránh nắng chiều.", "Cây mới trồng, cây con, cây vừa thay chậu: che kỹ hơn."], "ordered": false}, {"type": "p", "text": "Xem thêm [cây ban công nắng gắt hướng Tây](/goc-cham-cay/cay-ban-cong-nang-gat)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Polygonal_cracks_in_drought-dried_soil_near_La_Guardia%2C_Margarita_Island%2C_Venezuela.jpg/960px-Polygonal_cracks_in_drought-dried_soil_near_La_Guardia%2C_Margarita_Island%2C_Venezuela.jpg", "caption": "Mùa khô đất mặt khô nứt rất nhanh — phủ gốc và tưới đẫm vào sáng sớm giúp cây giữ ẩm cả ngày."}, {"type": "h2", "text": "3. Giữ ẩm cho đất"}, {"type": "list", "items": ["**Phủ gốc** bằng xơ dừa, vỏ thông, rơm, lá khô dày 3–5cm: giảm bốc hơi rất nhiều.", "Gom chậu nhỏ lại gần nhau, đặt trên khay sỏi có nước.", "Chậu đất nung ngoài nắng khô nhanh hơn chậu nhựa — có thể đặt chậu đất nung vào chậu bọc lớn hơn."], "ordered": false}, {"type": "h2", "text": "4. Cây trong nhà và máy lạnh"}, {"type": "p", "text": "Mùa nóng máy lạnh chạy nhiều, không khí trong phòng rất khô. Đừng đặt cây trước luồng gió lạnh; kiểm tra mặt dưới lá thường xuyên vì đây là mùa [nhện đỏ](/goc-cham-cay/nhen-do-mua-kho-cay-canh) bùng phát."}, {"type": "h2", "text": "5. Nhận biết cây thiếu nước và cháy nắng"}, {"type": "list", "items": ["Lá rũ buổi trưa nhưng tối dựng lại: cây đang chịu nóng, chưa đáng lo — kiểm tra đất.", "Lá rũ cả buổi sáng, đất khô cứng: thiếu nước thật. Tưới đẫm từ từ. Xem [héo do thiếu nước](/benh-cay/heo-thieu-nuoc).", "Mảng trắng bạc, nâu khô trên lá hứng nắng: [cháy lá do nắng gắt](/benh-cay/chay-la-do-nang)."], "ordered": false}, {"type": "h2", "text": "6. Bón phân mùa khô"}, {"type": "p", "text": "Bón khi đất đã được tưới ẩm, không bón lúc đất khô hay giữa trưa. Giảm liều phân hòa tan vì nước bốc hơi nhanh làm phân đậm đặc trong đất. Cây ra hoa mùa khô (hoa giấy, mai, hồng) cần thêm kali."}, {"type": "h2", "text": "7. Nguồn nước tưới"}, {"type": "p", "text": "Mùa khô ở các tỉnh ven biển miền Tây, nước sông có thể bị nhiễm mặn. Không tưới cây bằng nước sông khi chưa đo độ mặn — xem [phòng mặn cho cây sân vườn](/goc-cham-cay/phong-man-cho-cay-san-vuon)."}, {"type": "note", "title": "Mẹo nhỏ", "text": "Trước khi đi làm cả ngày mùa nắng, gom cây ban công vào chỗ râm và tưới đẫm. Cây chậu nhỏ có thể đặt vào khay nước nông 1–2cm trong ngày nắng gắt nhất, nhưng đừng để ngâm qua nhiều ngày."}, {"type": "products", "title": "Cây chịu nắng nóng mùa khô", "slugs": ["tac-cam-thach-thai", "tung-thom", "hoa-hong", "ngoc-bich", "luoi-ho"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Dry_Cracked_Mud_%284957b8b2-f52c-43b0-acc2-ead42cf6f03b%29.jpg/960px-Dry_Cracked_Mud_%284957b8b2-f52c-43b0-acc2-ead42cf6f03b%29.jpg', 3, '["chay-la-do-nang", "heo-thieu-nuoc", "nhen-do", "bo-tri"]'::jsonb, '["mùa khô", "nắng nóng", "tưới cây", "miền Tây"]'::jsonb, 'Cách chăm cây cảnh mùa khô nắng nóng ở miền Tây: tưới đúng giờ, che lưới, phủ gốc giữ ẩm, chống cháy lá, phòng nhện đỏ cho cây ban công.', 11),
('chuan-bi-cay-canh-don-tet', 'theo-mua', 'Chuẩn bị cây cảnh đón Tết: chọn cây chưng, chăm cây trong nhà và giữ hoa bền sau Tết', 'Từ đầu tháng Chạp, nhà nào cũng tính chuyện chưng cây Tết: mai, quất, tắc, cây kiểng lá đỏ hồng cho phòng khách. Bài này hướng dẫn chọn cây khỏe, chăm cây trong những ngày Tết và giữ cây sống lâu sau Tết.', '[{"type": "p", "text": "Tết Nguyên đán thường rơi vào khoảng cuối tháng 1 đến giữa tháng 2 dương lịch — đúng giữa mùa khô miền Tây, trời nắng ráo. Cây chưng Tết vừa để trang trí vừa gửi gắm mong muốn một năm mới sung túc. Chọn cây khỏe và chăm đúng giúp cây đẹp suốt Tết, có cây còn giữ được sang năm."}, {"type": "h2", "text": "Chọn cây chưng Tết"}, {"type": "table", "rows": [["Cây", "Ý nghĩa dân gian", "Đặt ở đâu"], ["Mai vàng", "Phú quý, may mắn — cây Tết đặc trưng miền Nam", "Sân, hiên nhà nhiều nắng"], ["[Tắc cẩm thạch](/san-pham/tac-cam-thach-thai)", "Trái nhiều, sung túc", "Hiên, cửa ra vào, nơi có nắng"], ["[Phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc)", "Tài lộc, màu đỏ may mắn", "Phòng khách, bàn thờ, quầy"], ["[Kim cương hồng](/san-pham/kim-cuong-hong), [cung điện vàng](/san-pham/cung-dien-vang)", "Sang trọng", "Phòng khách, làm quà"], ["[Lan ý](/san-pham/lan-y)", "Thanh khiết, bình an", "Bàn trà, phòng khách"], ["[Tulip Thái](/san-pham/tulip-thai)", "Hoa hồng tím tươi tắn", "Ban công, hiên có nắng nhẹ"]]}, {"type": "p", "text": "Xem thêm [ý nghĩa tên gọi các cây tài lộc](/goc-cham-cay/y-nghia-ten-goi-cay-tai-loc)."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Hoa_ng%C3%A0y_T%E1%BA%BFt.jpg/960px-Hoa_ng%C3%A0y_T%E1%BA%BFt.jpg", "caption": "Chợ hoa ngày Tết nhiều chậu hoa, cây cảnh rực rỡ — nên chọn cây có nhiều nụ sắp nở để chưng được lâu."}, {"type": "h2", "text": "Chọn cây khỏe khi mua"}, {"type": "list", "items": ["Lá xanh, bóng, không vàng úa, không có đốm, mặt dưới lá không có rệp, nhện.", "Cây trái: trái bám chắc, không rụng khi lắc nhẹ, có cả trái chín và trái xanh để chưng được lâu.", "Cây hoa: chọn cây có nhiều nụ sắp nở hơn là hoa đã nở bung.", "Gốc chắc, cây không lung lay trong chậu."], "ordered": false}, {"type": "p", "text": "Chi tiết ở bài [cách chọn cây khỏe khi mua](/goc-cham-cay/cach-chon-cay-khoe-khi-mua)."}, {"type": "h2", "text": "Chăm cây những ngày Tết"}, {"type": "list", "items": ["**Cây ưa nắng đặt trong nhà** (tắc, mai) chỉ nên để trong nhà vài ngày chính Tết, rồi đem ra chỗ nắng. Trong nhà tối lâu, cây rụng lá, rụng trái.", "**Tưới vừa đủ**: Tết thường bận rộn, giao việc tưới cho một người. Không tưới ngập rồi đi chơi xa vài ngày.", "Tránh đặt cây sát quạt, máy lạnh, cửa gió.", "Không bón phân trong những ngày đang chưng.", "Đi chơi xa ngày Tết: xem [mẹo giữ cây khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang)."], "ordered": true}, {"type": "h2", "text": "Giữ hoa bền"}, {"type": "list", "items": ["Hoa nở dưới nắng nóng tàn nhanh; đặt cây nơi mát, sáng tán xạ sẽ giữ hoa lâu hơn.", "Tưới vào gốc, không tưới lên hoa.", "Ngắt bỏ hoa tàn để cây gọn đẹp."], "ordered": false}, {"type": "h2", "text": "Sau Tết"}, {"type": "p", "text": "Cây chưng Tết thường bị \"sốc\" vì đổi chỗ, ít nắng. Xem [chăm cây sau Tết để giữ cây sống sang năm](/goc-cham-cay/cham-cay-sau-tet)."}, {"type": "p", "text": "Cửa hàng, công ty cần cây Tết số lượng lớn để trang trí hay làm quà có thể gửi danh sách ở trang [báo giá sỉ](/bao-gia-si)."}, {"type": "note", "title": "Mẹo nhỏ", "text": "Chụp ảnh lại cây khi vừa mua về. Sau Tết, so sánh để biết cây có bị rụng lá, rụng trái nhiều không — từ đó điều chỉnh chỗ đặt và cách tưới cho năm sau."}, {"type": "products", "title": "Cây chưng Tết", "slugs": ["tac-cam-thach-thai", "phu-quy", "van-loc", "kim-cuong-hong", "lan-y", "tulip-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mai_v%C3%A0ng.jpg/960px-Mai_v%C3%A0ng.jpg', 3, '["rung-la-soc-moi-truong"]'::jsonb, '["cây Tết", "chưng Tết", "tắc", "cây kiểng lá"]'::jsonb, 'Chuẩn bị cây cảnh chưng Tết: chọn mai, tắc, cây kiểng lá đỏ hồng; cách chọn cây khỏe, đặt cây ngày Tết, tưới nước, giữ hoa bền và chăm sau Tết.', 18),
('lich-cham-cay-12-thang-mien-tay', 'theo-mua', 'Lịch chăm cây cảnh 12 tháng ở miền Tây: tháng nào thay chậu, bón phân, phòng bệnh', 'Miền Tây có hai mùa rõ rệt: mùa khô và mùa mưa. Biết trước mỗi tháng cây cần gì giúp bạn chủ động thay chậu, bón phân, phòng bệnh đúng lúc thay vì đợi cây có vấn đề mới xử lý. Đây là lịch gợi ý theo từng tháng.', '[{"type": "p", "text": "Lịch dưới đây dựa trên thời tiết chung của đồng bằng sông Cửu Long: mùa khô khoảng tháng 12–4, mùa mưa khoảng tháng 5–11. Mỗi năm thời tiết có thể đến sớm hoặc muộn vài tuần, nên hãy nhìn trời và nhìn cây để điều chỉnh."}, {"type": "h2", "text": "Tóm tắt theo mùa"}, {"type": "table", "rows": [["Thời gian", "Thời tiết", "Việc chính"], ["Tháng 12–1", "Đầu mùa khô, mát, Tết", "Chưng cây Tết, tưới đều, ít bón"], ["Tháng 2–4", "Khô nóng, gió chướng, có nơi nhiễm mặn", "Giữ ẩm, che nắng, phòng nhện đỏ, kiểm tra độ mặn nước tưới"], ["Tháng 5–6", "Đầu mùa mưa", "Thay chậu, nhân giống, trồng cây mới"], ["Tháng 7–9", "Giữa mùa mưa", "Chống úng, phòng nấm, bón phân tan chậm"], ["Tháng 9–11", "Cuối mùa mưa, nước nổi vùng đầu nguồn", "Bảo vệ cây khỏi ngập, dọn lá bệnh"]]}, {"type": "h2", "text": "Tháng 12 và tháng 1"}, {"type": "list", "items": ["Trời mát, khô ráo — cây kiểng lá đẹp, cây hoa ra nụ.", "Chuẩn bị cây Tết: xem [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet).", "Cây ra hoa Tết cần thêm lân, kali theo từng giai đoạn.", "Giảm phân đạm cho cây kiểng lá vì cây mọc chậm hơn."], "ordered": false}, {"type": "h2", "text": "Tháng 2 đến tháng 4"}, {"type": "list", "items": ["Nắng nóng nhất năm: tưới sáng sớm, phủ gốc, che lưới cho cây không ưa nắng gắt. Xem [chăm cây mùa khô](/goc-cham-cay/cham-cay-mua-kho-nang-nong).", "Kiểm tra mặt dưới lá hằng tuần — [nhện đỏ](/benh-cay/nhen-do), [bọ trĩ](/benh-cay/bo-tri) phát mạnh.", "Vùng ven biển: đo độ mặn nước trước khi tưới, trữ nước ngọt. Xem [phòng mặn cho cây](/goc-cham-cay/phong-man-cho-cay-san-vuon).", "Chăm cây sau Tết: tỉa, đổi chỗ, bón nhẹ. Xem [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Wood_sorrel_after_rain.jpg/960px-Wood_sorrel_after_rain.jpg", "caption": "Đầu mùa mưa trời mát, ẩm, cây ra lá mới mạnh — thời điểm thuận lợi để thay chậu, giâm cành và trồng cây mới."}, {"type": "h2", "text": "Tháng 5 và tháng 6"}, {"type": "list", "items": ["Những cơn mưa đầu mùa: **thời điểm tốt nhất để thay chậu, tách bụi, giâm cành, trồng cây mới**. Xem [thay chậu đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach), [nhân giống cây cảnh](/goc-cham-cay/nhan-giong-cay-canh-tai-nha).", "Dọn sạch lá già, lá rụng chuẩn bị mùa mưa.", "Trồng cây công trình, cây bóng mát: tận dụng nước mưa giúp cây bén rễ."], "ordered": false}, {"type": "h2", "text": "Tháng 7 đến tháng 9"}, {"type": "list", "items": ["Mưa nhiều: giảm tưới, kê chậu cao, đổ nước đọng. Xem [chăm cây mùa mưa](/goc-cham-cay/cham-cay-mua-mua-mien-tay).", "Theo dõi [đốm lá do nấm](/benh-cay/dom-la-nam), [thối rễ](/benh-cay/thoi-re).", "Bón phân tan chậm hoặc phân hữu cơ (phân hòa tan dễ bị rửa trôi)."], "ordered": false}, {"type": "h2", "text": "Tháng 9 đến tháng 11"}, {"type": "list", "items": ["Vùng đầu nguồn (An Giang, Đồng Tháp) vào mùa nước nổi: kê cao chậu, chuẩn bị chỗ dời cây. Xem [bảo vệ cây mùa nước nổi](/goc-cham-cay/bao-ve-cay-mua-nuoc-noi).", "Cuối mùa mưa: tỉa cành, kiểm tra cọc chống trước các đợt gió.", "Bắt đầu kế hoạch cây Tết: cây ra hoa cần chăm theo lịch từ sớm."], "ordered": false}, {"type": "note", "title": "Lưu ý", "text": "Lịch chỉ để tham khảo. Mỗi loại cây có nhịp sinh trưởng riêng — thấy cây ra lá mới mạnh thì là lúc cây cần nước, phân; cây đứng lá thì giảm phân, giảm tưới."}, {"type": "products", "title": "Cây dễ chăm quanh năm", "slugs": ["luoi-ho", "phu-quy", "van-loc", "trau-ba-de-vuong-xanh", "tac-cam-thach-thai"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Leaves_after_rain_-_Arlington%2C_MA.jpg/960px-Leaves_after_rain_-_Arlington%2C_MA.jpg', 3, '["nhen-do", "dom-la-nam", "thoi-re"]'::jsonb, '["lịch chăm cây", "miền Tây", "theo mùa", "mùa mưa", "mùa khô"]'::jsonb, 'Lịch chăm cây cảnh 12 tháng ở miền Tây: mùa khô, mùa mưa, nước nổi, Tết; tháng nào thay chậu, nhân giống, bón phân, phòng nấm, chống mặn.', 25),
('bao-ve-cay-mua-nuoc-noi', 'theo-mua', 'Bảo vệ cây cảnh mùa nước nổi, ngập úng: chuẩn bị trước lũ và cứu cây sau khi nước rút', 'Vùng đầu nguồn miền Tây như Đồng Tháp, An Giang có mùa nước nổi hằng năm; nhiều nơi khác cũng ngập khi triều cường, mưa lớn. Cây bị ngập vài ngày có thể chết vì rễ thiếu khí. Đây là việc cần làm trước, trong và sau khi ngập.', '[{"type": "p", "text": "Mùa nước nổi ở vùng đầu nguồn đồng bằng sông Cửu Long thường diễn ra khoảng tháng 8 đến tháng 11, nước lên dần rồi rút dần. Ngoài ra, nhiều khu dân cư trũng có thể ngập khi triều cường kết hợp mưa lớn. Với cây trồng, nước ngập làm rễ thiếu oxy; ngập càng lâu, cây càng dễ chết."}, {"type": "h2", "text": "Trước mùa ngập"}, {"type": "list", "items": ["**Kê cao chậu** lên kệ, bục gạch cao hơn mức nước ngập năm trước.", "**Dời cây chậu nhỏ** lên hiên, lên lầu, chỗ cao.", "**Khơi rãnh thoát nước** quanh bồn cây, gốc cây trồng đất.", "**Vun gốc cao** cho cây sân vườn, cây ăn trái trồng đất; làm mô đất quanh gốc.", "**Chống cọc** cho cây cao: đất ngập mềm, cây dễ đổ khi có gió.", "Cây trồng mới, cây non: nếu được, trồng trên mô cao hoặc trồng chậu."], "ordered": true}, {"type": "h2", "text": "Trong lúc ngập"}, {"type": "list", "items": ["Không tưới, không bón phân.", "Hạn chế đi lại giẫm lên đất quanh gốc khi đất còn ngập — đất bị nén chặt.", "Cây chậu bị ngập: nếu nhấc ra được, đặt lên chỗ cao ngay, nghiêng chậu cho nước thoát."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Flooding_on_the_Mekong_River_%2813982%29.jpg/960px-Flooding_on_the_Mekong_River_%2813982%29.jpg", "caption": "Ảnh vệ tinh mùa lũ trên lưu vực sông Mê Kông — vùng màu sẫm là nơi nước ngập."}, {"type": "h2", "text": "Sau khi nước rút"}, {"type": "list", "items": ["**Thoát nước nhanh:** khơi rãnh cho nước trong bồn, quanh gốc rút hết.", "**Rửa lớp bùn** bám trên lá để lá quang hợp được.", "**Xới nhẹ đất mặt** cho thoáng khí khi đất đã ráo bớt.", "**Cắt tỉa** lá vàng, cành khô, giảm bớt tán để cây đỡ mất nước trong khi rễ còn yếu.", "**Kiểm tra rễ cây chậu:** rễ đen, mềm, có mùi hôi là rễ thối. Cắt bỏ rễ thối, thay đất mới thoát nước. Xem [thối rễ](/benh-cay/thoi-re).", "**Chưa bón phân ngay.** Chờ cây ra rễ mới, lá non (khoảng 2–3 tuần) rồi bón phân hữu cơ, phân có lân nhẹ để kích rễ. Có thể dùng chế phẩm [Trichoderma](/goc-cham-cay/trichoderma-che-pham-sinh-hoc) giúp phòng nấm rễ."], "ordered": true}, {"type": "h2", "text": "Dấu hiệu cây khó cứu"}, {"type": "list", "items": ["Thân, cành nâu khô, cạo vỏ không còn lớp xanh.", "Lá héo xanh rồi khô nhanh dù đất đã ráo — có thể do vi khuẩn. Xem [héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan).", "Gốc cây ăn trái có vết thối, chảy nhựa."], "ordered": false}, {"type": "p", "text": "Cây quý mà không chắc còn cứu được, có thể mang mẫu lá, cành đến [cửa hàng](/he-thong-cua-hang) để được xem."}, {"type": "h2", "text": "Chọn cây cho vùng hay ngập"}, {"type": "p", "text": "Ưu tiên trồng chậu cho cây quý; cây trồng đất chọn loại chịu ẩm, trồng trên mô cao. Xem thêm [cây sân vườn cho nhà phố, nhà vườn miền Tây](/goc-cham-cay/cay-san-vuon-nha-pho-mien-tay)."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Sau ngập, nước và bùn có thể bẩn, có mảnh vỡ, rắn rết trú ẩn. Mang ủng, găng tay khi dọn vườn; ngắt điện khu vực sân vườn nếu có ổ cắm, máy bơm, đèn trang trí bị ngập."}, {"type": "products", "title": "Cây chậu dễ dời khi ngập", "slugs": ["tac-cam-thach-thai", "cay-so-ri", "hoa-hong", "cau-trang"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Vietnamese_children_playing_in_flooded_streets_in_Chau_Duc_Province.jpg/960px-Vietnamese_children_playing_in_flooded_streets_in_Chau_Duc_Province.jpg', 3, '["thoi-re", "heo-xanh-vi-khuan", "rung-la-soc-moi-truong"]'::jsonb, '["mùa nước nổi", "ngập úng", "triều cường", "miền Tây"]'::jsonb, 'Cách bảo vệ cây cảnh, cây sân vườn mùa nước nổi, ngập úng ở miền Tây: kê cao chậu, khơi rãnh, cứu cây sau ngập, xử lý rễ thối sau khi nước rút.', 32),
('phong-man-cho-cay-san-vuon', 'theo-mua', 'Phòng mặn cho cây sân vườn mùa khô ở miền Tây: đo độ mặn, trữ nước ngọt và cứu cây bị ngộ mặn', 'Mùa khô, gió chướng đẩy nước biển vào sâu trong sông rạch ở các tỉnh ven biển miền Tây. Tưới cây bằng nước nhiễm mặn làm lá cháy mép, rụng lá, cây có thể chết. Đây là cách đo độ mặn, trữ nước và chăm cây khi có hạn mặn.', '[{"type": "p", "text": "Xâm nhập mặn là hiện tượng nước biển lấn sâu vào hệ thống sông rạch, thường gặp trong mùa khô ở các tỉnh ven biển đồng bằng sông Cửu Long, nhất là những năm ít nước từ thượng nguồn. Nhiều vườn cây ăn trái, cây cảnh từng bị thiệt hại nặng chỉ vì tưới vài lần nước nhiễm mặn mà không biết."}, {"type": "h2", "text": "Theo dõi thông tin độ mặn"}, {"type": "p", "text": "Mùa khô, cơ quan chuyên môn ở địa phương thường thông báo độ mặn theo từng điểm trên sông, kèm khuyến cáo lịch lấy nước. Theo dõi thông báo của xã, phường, đài phát thanh địa phương để biết khi nào nước sông an toàn."}, {"type": "h2", "text": "Đo độ mặn trước khi tưới"}, {"type": "list", "items": ["Dùng **bút đo độ mặn** (khúc xạ kế hoặc bút điện tử) — giá không cao, rất đáng mua nếu nhà bạn ở vùng hay nhiễm mặn.", "Nước có vị mặn khi nếm là đã quá mặn để tưới; nước nếm chưa thấy mặn vẫn có thể gây hại cho cây nhạy cảm.", "Đa số cây cảnh và cây ăn trái nhạy cảm với mặn. Khuyến cáo phổ biến là chỉ tưới nước có độ mặn **dưới 1‰** (một phần nghìn), cây nhạy cảm nên dưới 0,5‰. Nếu không chắc, đừng tưới."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/20190924_Ben_Tre_river_boat-1.jpg/960px-20190924_Ben_Tre_river_boat-1.jpg", "caption": "Sông nước vùng Bến Tre — mùa khô, nước mặn có thể lấn sâu vào sông rạch ở các tỉnh ven biển, phải đo trước khi lấy nước tưới."}, {"type": "h2", "text": "Trữ nước ngọt"}, {"type": "list", "items": ["Trữ nước mưa cuối mùa mưa vào lu, bồn, túi trữ nước.", "Ao, mương trữ nước ngọt trong vườn: đóng cống khi nước ngoài sông bắt đầu mặn.", "Dùng nước máy cho cây chậu quý khi nước sông nhiễm mặn."], "ordered": false}, {"type": "h2", "text": "Tiết kiệm nước tưới"}, {"type": "list", "items": ["Phủ gốc dày bằng rơm, lá khô, xơ dừa — giảm bốc hơi đáng kể.", "Tưới gốc vào sáng sớm, chiều mát; tưới nhỏ giọt cho bồn cây.", "Che lưới cho cây non, cây mới trồng.", "Tạm ngưng bón phân hóa học (phân làm tăng nồng độ muối trong đất)."], "ordered": false}, {"type": "p", "text": "Xem thêm [chăm cây mùa khô nắng nóng](/goc-cham-cay/cham-cay-mua-kho-nang-nong)."}, {"type": "h2", "text": "Dấu hiệu cây bị ngộ mặn"}, {"type": "list", "items": ["Mép lá, chóp lá cháy nâu, lan dần vào trong lá.", "Lá vàng, rụng nhiều dù đất vẫn ẩm.", "Cây héo dù vừa tưới.", "Cây ăn trái rụng trái non."], "ordered": false}, {"type": "p", "text": "Dễ nhầm với [cháy lá do nắng](/benh-cay/chay-la-do-nang) hoặc [thiếu nước](/benh-cay/heo-thieu-nuoc) — hãy nhớ lại nguồn nước đã tưới mấy ngày gần đây."}, {"type": "h2", "text": "Cứu cây đã bị ngộ mặn"}, {"type": "list", "items": ["Ngưng ngay nguồn nước mặn.", "**Rửa mặn:** tưới đẫm nhiều lần bằng nước ngọt cho nước thoát qua đất, cuốn muối đi (cây chậu: tưới cho nước chảy ra đáy chậu nhiều lần).", "Cắt tỉa bớt lá cháy, cành khô, giảm tán.", "Cây chậu nặng: thay đất mới.", "Khi cây ra lá non, bón phân hữu cơ nhẹ để cây phục hồi; chưa bón phân hóa học liều cao."], "ordered": true}, {"type": "note", "title": "Lưu ý", "text": "Mức độ mặn an toàn khác nhau theo loại cây và độ tuổi cây. Với vườn cây ăn trái lớn, nên hỏi thêm khuyến cáo của cơ quan nông nghiệp địa phương mỗi mùa khô."}, {"type": "products", "title": "Cây sân vườn, cây ăn trái chậu", "slugs": ["tac-cam-thach-thai", "cay-so-ri", "hoa-hong", "cau-trang"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/20190924_Ben_Tre_river_barge-24.jpg/960px-20190924_Ben_Tre_river_barge-24.jpg', 3, '["chay-la-do-nang", "heo-thieu-nuoc"]'::jsonb, '["xâm nhập mặn", "mùa khô", "miền Tây", "tưới cây"]'::jsonb, 'Cách phòng mặn cho cây sân vườn mùa khô ở miền Tây: đo độ mặn nước tưới, trữ nước ngọt, dấu hiệu cây ngộ mặn, cách rửa mặn và phục hồi cây.', 39),
('cham-cay-sau-tet', 'theo-mua', 'Chăm cây sau Tết: cứu cây rụng lá, cắt tỉa, đổi chỗ và bón phân để giữ cây sang năm', 'Sau những ngày chưng Tết trong nhà, nhiều cây rụng lá, rụng trái, héo hoa. Đừng vội bỏ: phần lớn cây chỉ bị sốc vì thiếu nắng và đổi chỗ. Chăm đúng trong vài tuần sau Tết, cây sẽ hồi lại và có thể chưng tiếp năm sau.', '[{"type": "p", "text": "Cây chưng Tết thường được đưa từ vườn về nhà, đặt trong phòng khách ít nắng, rồi lại di chuyển nhiều lần. Sau Tết, cây yếu đi là chuyện bình thường. Điều quan trọng là cho cây nghỉ ngơi và phục hồi đúng cách."}, {"type": "h2", "text": "Tuần đầu sau Tết"}, {"type": "list", "items": ["**Đưa cây ưa nắng ra ngoài** (tắc, mai, cây hoa) — nhưng tập nắng dần: 2–3 ngày đầu để chỗ nắng nhẹ buổi sáng, rồi mới ra nắng nhiều hơn.", "**Cắt bỏ hoa tàn, trái hư, lá vàng.** Với tắc, nên hái bớt trái để cây không bị kiệt sức.", "**Tưới đều**, không để khô kiệt rồi tưới ngập.", "Kiểm tra sâu bệnh: cây chưng Tết dễ có [rệp sáp](/goc-cham-cay/tri-rep-sap-cay-kieng-la), rệp muội."], "ordered": true}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Ch%E1%BA%ADu_mai_tr%E1%BA%AFng.jpg/960px-Ch%E1%BA%ADu_mai_tr%E1%BA%AFng.jpg", "caption": "Chậu mai sau Tết cần đưa ra nắng dần, cắt tỉa và bón phân nhẹ để cây hồi sức cho năm sau."}, {"type": "h2", "text": "Cây kiểng lá chưng Tết"}, {"type": "p", "text": "Phú quý, vạn lộc, kim cương… chưng ở phòng khách thường vẫn ổn. Nếu lá vàng vài lá, chỉ cần cắt bỏ, đặt chỗ sáng tán xạ, tưới khi đất khô mặt. Đừng bón phân ngay."}, {"type": "h2", "text": "Cây rụng lá nhiều — có cứu được không?"}, {"type": "p", "text": "Rụng lá sau khi đổi chỗ là phản ứng [sốc môi trường](/benh-cay/rung-la-soc-moi-truong). Kiểm tra:"}, {"type": "list", "items": ["Cành còn xanh, mầm ngủ còn tươi: cây sẽ ra lá lại sau 2–4 tuần nếu đủ nắng, đủ nước.", "Cạo nhẹ vỏ cành thấy xanh: cành còn sống.", "Gốc mềm, rễ thối: cây khó cứu, xem bài [thối rễ](/benh-cay/thoi-re)."], "ordered": false}, {"type": "h2", "text": "2–4 tuần sau Tết"}, {"type": "list", "items": ["**Cắt tỉa tạo tán:** tỉa cành khô, cành yếu, cành mọc lộn xộn.", "**Thay chậu** nếu cây chật chậu, đất chai: làm sau khi cây đã ổn định, trời không quá nắng. Xem [thay chậu đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach).", "**Bón phân phục hồi:** khi cây ra lá non, bón phân hữu cơ hoai hoặc phân NPK cân đối liều nhẹ. Xem [phân hữu cơ cho cây cảnh](/goc-cham-cay/phan-huu-co-cho-cay-canh)."], "ordered": false}, {"type": "h2", "text": "Giữ cây để chưng năm sau"}, {"type": "p", "text": "Cây ăn trái chưng Tết (tắc) cần nhiều nắng, phân và chăm theo lịch cả năm mới cho trái đẹp đúng dịp Tết năm sau. Cây kiểng lá thì dễ hơn: chăm như cây trong nhà bình thường. Xem [lịch chăm cây 12 tháng ở miền Tây](/goc-cham-cay/lich-cham-cay-12-thang-mien-tay) để biết tháng nào cần làm gì."}, {"type": "note", "title": "Lưu ý", "text": "Mùa sau Tết là giữa mùa khô, nắng nóng — đừng đem cây vừa ở trong nhà ra nắng gắt giữa trưa ngay. Cây cháy lá sau Tết phần lớn là do đổi chỗ quá đột ngột."}, {"type": "products", "title": "Cây chưng Tết giữ được sang năm", "slugs": ["tac-cam-thach-thai", "phu-quy", "van-loc", "kim-cuong-hong", "cung-dien-vang"]}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Hoa_mai.jpg/960px-Hoa_mai.jpg', 2, '["rung-la-soc-moi-truong", "rep-sap"]'::jsonb, '["sau Tết", "cây Tết", "phục hồi cây", "cắt tỉa"]'::jsonb, 'Cách chăm cây cảnh sau Tết: xử lý cây rụng lá, rụng trái, cắt tỉa hoa tàn, đưa cây ra nắng, thay chậu, bón phân để giữ cây sống sang năm.', 45)
) AS v(slug, category, title, excerpt, body, cover, minutes, diseases, tags, seo, ord)
WHERE NOT EXISTS (SELECT 1 FROM "posts" p WHERE p."slug" = v.slug);
