UPDATE "posts" SET "status" = 'published', "published_at" = now() - interval '9 hours' - (("id" % 1000) * interval '10 minutes'),
  "updated_at" = now(), "updated_by" = 'Hệ thống'
WHERE "category" = 'cam-nang' AND "status" = 'draft' AND "slug" IN ('cay-de-ban-lam-viec-de-cham', 'cay-van-phong-chiu-bong-it-tuoi',
  'phan-biet-cac-loai-trau-ba-de-vuong', 'phan-biet-cay-duoi-cong-calathea', 'mon-quan-am-va-mon-melo', 'phan-biet-phu-quy-van-loc-ngoc-ngan-ngan-hau',
  'chon-cay-cong-trinh-duong-pho-san-truong', 'cay-ban-cong-nang-gat', 'cay-trong-nha-thieu-sang', 'chon-cay-theo-menh-ngu-hanh',
  'cay-canh-an-toan-tre-nho-thu-cung', 'chon-cay-qua-tang-khai-truong-tan-gia', 'cay-dat-phong-ngu', 'cay-trang-tri-quan-ca-phe',
  'cay-de-cham-cho-nguoi-moi-bat-dau', 'cach-chon-cay-khoe-khi-mua', 'chon-chau-va-co-cay-ma-chau-c', 'cay-san-vuon-nha-pho-mien-tay',
  'cay-canh-loc-khong-khi-that-khong', 'bo-tri-cay-phong-khach-can-ho');
